insert into public.email_automations(id,key,name,trigger_type,is_active) values('7e7632e2-2733-597f-8534-d452861c4787','course_intensive-strength','Интенсив «Сила»','course',false) on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('969d65d6-7d75-5b24-a939-025ee15acf64','7e7632e2-2733-597f-8534-d452861c4787','Вводное письмо',1,0,'{Интенсив Сила} Добро пожаловать!','{"ru":"{Интенсив Сила} Добро пожаловать!","en":"{The “Strength” Intensive} Welcome!","de":"{Intensivkurs „Kraft“} Willkommen!","fr":"{Intensif « Force »} Bienvenue !","it":"{Intensivo «Forza»} Benvenuto!","es":"{Intensivo «Fuerza»} ¡Bienvenido!","pt":"{Intensivo «Força»} Bem-vindo!","nl":"{Intensive «Kracht»} Welkom!"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-strength/i3_email-3ec2fc66f836.png" alt="Интенсив «Сила»" width="504" height="119" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!<br> <br>Я рад, что вы решились в течение месяца целенаправленно поработать с состояниями силы, решительности, целеустремлённости, пассионарности... Вроде бы как это естественные, доступные каждому состояния. Однако, в социуме действует множество как побудительных, так и запретительных сценариев, которые управляют нашим поведением. Выполняя практики на йоговском коврике и в жизни, размышляя, корректируя свои мысли и поступки, в течение месяца можно получить важные результаты, которые проявятся как на уровне тела (оздоравливание), так и на уровне психологического фона (удовлетворённость и счастье).</p><p></p><p></p><p> В течение этого месяца вы получите 30 практик, направленных на гармонизацию третьей чакры. Внимательно прочитайте это письмо, чтобы понимать, что и как будет происходить. <br> <br><strong>1. Самая суть</strong><br> Это не учебный курс, а интенсивный практикум, ядром которого являются ежедневные практики йоги. Данные практики я проводил по утрам в прямом эфире, синхронизируя направление каждой практики с планетными ритмами в тот день. В этом интенсиве я собрал видеозаписи лучших практик, которые были направлены именно на первую чакру (иногда во взаимодействии с какой-нибудь ещё чакрой), дополнил их поведенческими (психологическими) практиками. В результате получился мощнейший заряд для гармонизации сферы здоровья. </p><p></p><p></p><p>Если вы не проходили моих курсов и не понимаете при чём здесь какая-то там «третья чакра», я рекомендую вам совместить прохождение данного интенсива с практикумом или курсом, в котором я плавно подвожу к пониманию того, чем мы здесь занимаемся. Важно не просто «поверить» мне, а открыть в себе понимание через личный опыт - как на йоговском коврике, так и в жизни. Тогда практики начинают работать гораздо глубже. Иначе получаем физкультуру - так как это базовое понимание (опыт) йоги, которое есть у каждого. </p><p></p><p></p><p>Данный интенсив вы можете дополнить следующими учебными программами:<br> - Практикум «Месяц силы»: <a href="https://zamkovoi.yoga/m3">https://zamkovoi.yoga/m3</a> </p><p></p><p>- Курс «Осуществи мечту»: <a href="https://zamkovoi.yoga/yoga3">https://zamkovoi.yoga/yoga3</a> <br>  <br><strong>2. Практики йоги</strong><br> Практики йоги, которые вас ожидают, отличаются от того, что вы можете встретить в фитнес-центре. Я предполагаю, что вам важен результат, а не лицедейство. Мы работаем с внутренними состояниями (то есть с энергиями), соединяя медитацию, пранаяму и асаны в той мере, в которой это необходимо для получения желаемого результата на максимально глубоком уровне. Большинство практик начинаются с небольшого введения, которое необходимо, чтобы ваше сознание переключилось с обыденности на волну практики, вы вошли в соответствующий энергетический поток и активировалось ваше внутреннее намерение. Далее следует сама практика, которая в разные дни имеет разную длительность и состав элементов. После практики я рекомендую вам некоторое время побыть в медитации, а может быть в возникшем состоянии осознанности продолжить выполнять асаны, которые будет просить ваше тело. Средняя продолжительность практик 30-40 минут. Но некоторые практики короче, а некоторые длятся около часа. Важно, чтобы во время практики вас ничто не отвлекало и не торопило. И ещё очень важно - начав практику, не прерывайтесь до её окончания!!! Каждая практика - это живая история, которая проводит вас по определённому пути. Прервав практику, вы можете оказаться в менее ресурсном состоянии, чем были в её начале. Даже если сейчас эти слова вам кажутся мистификацией и пустой эзотерикой, прислушайтесь к моим рекомендациям. <br>  <br><strong>3. Поведенческие практики</strong><br> Каждый день в письме вместе с практикой йоги я буду присылать вам «совет дня». Попробуйте воспринимать его не как ещё одну умную мысль, подобную которой вы уже много раз слышали. У меня нет цели вас удивить, сказав то, что вы ещё не слышали. Воспринимайте этот «совет» как задание, как поведенческую практику! Выполняйте эту практику в данный день. И поверьте - вам станет гораздо интересней, и этот интенсив принесёт вам гораздо больше пользы. Некоторые такие практики могут казаться вам проще, некоторые сложнее. Некоторые прагматичнее, некоторые более психологическими. В любом случае, это не как если бы я предложил вам 20 раз присесть. Тут мы работаем с вашими поведенческими и психологическими шаблонами. И ключ к успеху в том, чтобы не сражаться с собой, не вызывать дополнительное внутреннее напряжение, а как в асанах - дышать и расслабляться. Поэтому практика звучит мягко - как &quot;совет дня&quot; - чтобы не вызывать сигнал тревоги. Прочитайте, примерьте, попробуйте в течение дня мягко следовать этому совету или хотя бы вспоминать его, вновь примеряя и возвращаясь в ощущение, что вы ему следуете. Адаптируйтесь к новым состояниям... В некоторых случаях одна такая практика может растянуться на несколько дней или даже месяцев, потому что вы ощутите её значимость, и начнёте внедрять её в свою жизнь на уровне привычки, то есть корректируя текущий гомеостаз системы. И, хотя я не закладывал чёткую связь между поведенческими практиками и практиками йоги, которые предлагаю в одном письме, тем не менее вы можете выполнять каждую практику йоги в состоянии, возникшем когда вы воспринимаете себя следующим моему совету. Однако, это вовсе не обязательно, так как каждая из этих двух практик самодостаточна.<br>  <br><strong>4. Расписание занятий</strong><br> Каждый день в полночь вам будет открываться новая практика (прошлая при этом будет исчезать, как прошлый день). Благодаря такому подходу, у вас не будет накапливаться снежный ком невыполненных практик. В течение суток вы можете выбрать любое удобное вам время, и позаниматься. Я рекомендую вам заниматься утром, чтобы в полученном в результате практики состоянии проживать день, а не спать лечь. Воспринимайте этот интенсив не как компьютерную иллюзию, а как реальную жизнь - в которой всё важное происходит СЕГОДНЯ, и практика йоги расширяется с коврика на пространство вашей проявленности в том мире, который вы воспринимаете, как наиболее реальный!</p><p></p><p></p><p>Кстати, есть небольшой нюанс с временем получения второй практики. Если вы записались до 18:00, то вторую практику вы получите в ближайшую полночь. Если же вы записались после 18:00, то вторую практику вы получите не в ближайшую, а в следующую полночь. То есть у вас будет запас времени на случай, если вы не успеете выполнить практику в день записи на интенсив. <br>  <br><strong>5. Не насилуйте себя</strong><br> Когда вы покупаете месячный абонемент в фитнес центр, вы ведь понимаете, что вам не обязательно ходить в него каждый день? Более того, взяв слишком быстрый темп, вы можете забросить занятия не дойдя даже до конца месяца... В отношении практик данного интенсива действует то же правило - не жадничайте! Занимайтесь в удобном вам ритме - через день, через два... Конечно, хорошо заниматься каждый день, но ещё лучше - понимать свои долгосрочные задачи, и действовать соответственно. Скорее всего, ваши задачи выходят за рамки одного месяца, и вам необходимо регулярно действовать длительное время. Данный интенсив я задумал так, чтобы вы могли проходить его месяц за месяцем столько раз, сколько потребуется, пока поставленная вами цель не будет достигнута. Эта стратегия эффективней, чем один месяц втопить, а потом забросить практики или рвануть в другом направлении.<br>  <br><strong>6. Техника безопасности</strong><br> Я забочусь о вашем здоровье и напоминаю, что только вы несёте ответственность за адекватность выполнения асан, пранаям и медитаций, которые я буду предлагать, вашим физическим возможностям и психическому состоянию. Важно понимать, что это онлайн занятия, и я не могу контролировать ваше состояние. У вас могут быть физические и психологические особенности. Пожалуйста, будьте внимательны к своему состоянию. Если вы почувствуете, что какая-то асана, которую я предлагаю выполнить, для вас преждевременна, выполните её не очень глубоко, на компромиссном уровне, или вовсе замените её другой асаной - такой, которая приблизительно также включает тело, но проще для вас.<br>  <br><strong>7. Ответы на вопросы</strong><br> Каждую неделю (обычно по субботам) я провожу в Zoom групповые онлайн-консультации (вебинары), на которых мы общаемся, поддерживаем мотивацию, обсуждаем возникающие трудности и вопросы. Перед каждой такой консультацией я буду высылать вам письмо с указанием даты и времени её проведения, а также ссылкой для того, чтобы к ней присоединиться. То, что интересно вам, наверняка будет интересно и многим другим. Поэтому, обсуждение вопросов на групповых консультациях наиболее эффективно. Если случится так, что время консультации окажется вам неудобным, в этом случае пришлите ваши вопросы имейлом до её начала. Я отвечу на них на консультации, а вам пришлю ссылку на запись, чтобы вы могли посмотреть её в удобное вам время. Записи консультаций сохраняются в течение одной недели.<br> <br>Желаю вам плодотворных практик!</p><p></p><p>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-strength/i3_email-3ec2fc66f836.png\" alt=\"Интенсив «Сила»\" width=\"504\" height=\"119\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!<br> <br>Я рад, что вы решились в течение месяца целенаправленно поработать с состояниями силы, решительности, целеустремлённости, пассионарности... Вроде бы как это естественные, доступные каждому состояния. Однако, в социуме действует множество как побудительных, так и запретительных сценариев, которые управляют нашим поведением. Выполняя практики на йоговском коврике и в жизни, размышляя, корректируя свои мысли и поступки, в течение месяца можно получить важные результаты, которые проявятся как на уровне тела (оздоравливание), так и на уровне психологического фона (удовлетворённость и счастье).</p><p></p><p></p><p> В течение этого месяца вы получите 30 практик, направленных на гармонизацию третьей чакры. Внимательно прочитайте это письмо, чтобы понимать, что и как будет происходить. <br> <br><strong>1. Самая суть</strong><br> Это не учебный курс, а интенсивный практикум, ядром которого являются ежедневные практики йоги. Данные практики я проводил по утрам в прямом эфире, синхронизируя направление каждой практики с планетными ритмами в тот день. В этом интенсиве я собрал видеозаписи лучших практик, которые были направлены именно на первую чакру (иногда во взаимодействии с какой-нибудь ещё чакрой), дополнил их поведенческими (психологическими) практиками. В результате получился мощнейший заряд для гармонизации сферы здоровья. </p><p></p><p></p><p>Если вы не проходили моих курсов и не понимаете при чём здесь какая-то там «третья чакра», я рекомендую вам совместить прохождение данного интенсива с практикумом или курсом, в котором я плавно подвожу к пониманию того, чем мы здесь занимаемся. Важно не просто «поверить» мне, а открыть в себе понимание через личный опыт - как на йоговском коврике, так и в жизни. Тогда практики начинают работать гораздо глубже. Иначе получаем физкультуру - так как это базовое понимание (опыт) йоги, которое есть у каждого. </p><p></p><p></p><p>Данный интенсив вы можете дополнить следующими учебными программами:<br> - Практикум «Месяц силы»: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a> </p><p></p><p>- Курс «Осуществи мечту»: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a> <br>  <br><strong>2. Практики йоги</strong><br> Практики йоги, которые вас ожидают, отличаются от того, что вы можете встретить в фитнес-центре. Я предполагаю, что вам важен результат, а не лицедейство. Мы работаем с внутренними состояниями (то есть с энергиями), соединяя медитацию, пранаяму и асаны в той мере, в которой это необходимо для получения желаемого результата на максимально глубоком уровне. Большинство практик начинаются с небольшого введения, которое необходимо, чтобы ваше сознание переключилось с обыденности на волну практики, вы вошли в соответствующий энергетический поток и активировалось ваше внутреннее намерение. Далее следует сама практика, которая в разные дни имеет разную длительность и состав элементов. После практики я рекомендую вам некоторое время побыть в медитации, а может быть в возникшем состоянии осознанности продолжить выполнять асаны, которые будет просить ваше тело. Средняя продолжительность практик 30-40 минут. Но некоторые практики короче, а некоторые длятся около часа. Важно, чтобы во время практики вас ничто не отвлекало и не торопило. И ещё очень важно - начав практику, не прерывайтесь до её окончания!!! Каждая практика - это живая история, которая проводит вас по определённому пути. Прервав практику, вы можете оказаться в менее ресурсном состоянии, чем были в её начале. Даже если сейчас эти слова вам кажутся мистификацией и пустой эзотерикой, прислушайтесь к моим рекомендациям. <br>  <br><strong>3. Поведенческие практики</strong><br> Каждый день в письме вместе с практикой йоги я буду присылать вам «совет дня». Попробуйте воспринимать его не как ещё одну умную мысль, подобную которой вы уже много раз слышали. У меня нет цели вас удивить, сказав то, что вы ещё не слышали. Воспринимайте этот «совет» как задание, как поведенческую практику! Выполняйте эту практику в данный день. И поверьте - вам станет гораздо интересней, и этот интенсив принесёт вам гораздо больше пользы. Некоторые такие практики могут казаться вам проще, некоторые сложнее. Некоторые прагматичнее, некоторые более психологическими. В любом случае, это не как если бы я предложил вам 20 раз присесть. Тут мы работаем с вашими поведенческими и психологическими шаблонами. И ключ к успеху в том, чтобы не сражаться с собой, не вызывать дополнительное внутреннее напряжение, а как в асанах - дышать и расслабляться. Поэтому практика звучит мягко - как &quot;совет дня&quot; - чтобы не вызывать сигнал тревоги. Прочитайте, примерьте, попробуйте в течение дня мягко следовать этому совету или хотя бы вспоминать его, вновь примеряя и возвращаясь в ощущение, что вы ему следуете. Адаптируйтесь к новым состояниям... В некоторых случаях одна такая практика может растянуться на несколько дней или даже месяцев, потому что вы ощутите её значимость, и начнёте внедрять её в свою жизнь на уровне привычки, то есть корректируя текущий гомеостаз системы. И, хотя я не закладывал чёткую связь между поведенческими практиками и практиками йоги, которые предлагаю в одном письме, тем не менее вы можете выполнять каждую практику йоги в состоянии, возникшем когда вы воспринимаете себя следующим моему совету. Однако, это вовсе не обязательно, так как каждая из этих двух практик самодостаточна.<br>  <br><strong>4. Расписание занятий</strong><br> Каждый день в полночь вам будет открываться новая практика (прошлая при этом будет исчезать, как прошлый день). Благодаря такому подходу, у вас не будет накапливаться снежный ком невыполненных практик. В течение суток вы можете выбрать любое удобное вам время, и позаниматься. Я рекомендую вам заниматься утром, чтобы в полученном в результате практики состоянии проживать день, а не спать лечь. Воспринимайте этот интенсив не как компьютерную иллюзию, а как реальную жизнь - в которой всё важное происходит СЕГОДНЯ, и практика йоги расширяется с коврика на пространство вашей проявленности в том мире, который вы воспринимаете, как наиболее реальный!</p><p></p><p></p><p>Кстати, есть небольшой нюанс с временем получения второй практики. Если вы записались до 18:00, то вторую практику вы получите в ближайшую полночь. Если же вы записались после 18:00, то вторую практику вы получите не в ближайшую, а в следующую полночь. То есть у вас будет запас времени на случай, если вы не успеете выполнить практику в день записи на интенсив. <br>  <br><strong>5. Не насилуйте себя</strong><br> Когда вы покупаете месячный абонемент в фитнес центр, вы ведь понимаете, что вам не обязательно ходить в него каждый день? Более того, взяв слишком быстрый темп, вы можете забросить занятия не дойдя даже до конца месяца... В отношении практик данного интенсива действует то же правило - не жадничайте! Занимайтесь в удобном вам ритме - через день, через два... Конечно, хорошо заниматься каждый день, но ещё лучше - понимать свои долгосрочные задачи, и действовать соответственно. Скорее всего, ваши задачи выходят за рамки одного месяца, и вам необходимо регулярно действовать длительное время. Данный интенсив я задумал так, чтобы вы могли проходить его месяц за месяцем столько раз, сколько потребуется, пока поставленная вами цель не будет достигнута. Эта стратегия эффективней, чем один месяц втопить, а потом забросить практики или рвануть в другом направлении.<br>  <br><strong>6. Техника безопасности</strong><br> Я забочусь о вашем здоровье и напоминаю, что только вы несёте ответственность за адекватность выполнения асан, пранаям и медитаций, которые я буду предлагать, вашим физическим возможностям и психическому состоянию. Важно понимать, что это онлайн занятия, и я не могу контролировать ваше состояние. У вас могут быть физические и психологические особенности. Пожалуйста, будьте внимательны к своему состоянию. Если вы почувствуете, что какая-то асана, которую я предлагаю выполнить, для вас преждевременна, выполните её не очень глубоко, на компромиссном уровне, или вовсе замените её другой асаной - такой, которая приблизительно также включает тело, но проще для вас.<br>  <br><strong>7. Ответы на вопросы</strong><br> Каждую неделю (обычно по субботам) я провожу в Zoom групповые онлайн-консультации (вебинары), на которых мы общаемся, поддерживаем мотивацию, обсуждаем возникающие трудности и вопросы. Перед каждой такой консультацией я буду высылать вам письмо с указанием даты и времени её проведения, а также ссылкой для того, чтобы к ней присоединиться. То, что интересно вам, наверняка будет интересно и многим другим. Поэтому, обсуждение вопросов на групповых консультациях наиболее эффективно. Если случится так, что время консультации окажется вам неудобным, в этом случае пришлите ваши вопросы имейлом до её начала. Я отвечу на них на консультации, а вам пришлю ссылку на запись, чтобы вы могли посмотреть её в удобное вам время. Записи консультаций сохраняются в течение одной недели.<br> <br>Желаю вам плодотворных практик!</p><p></p><p>Сергей Замковой</p>","en":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-strength/i3_email-3ec2fc66f836.png\" alt=\"Интенсив «Сила»\" width=\"504\" height=\"119\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Hello, {{name}}!<br> <br>I am glad that you have decided to spend a month purposefully working with the states of strength, decisiveness, purposefulness, passionarity... It would seem that these are natural states available to everyone. However, in society there are many both motivating and prohibitive scripts that control our behavior. By performing practices on the yoga mat and in life, reflecting, correcting your thoughts and actions, over the course of a month you can obtain important results that will manifest both on the level of the body (healing) and on the level of psychological background (satisfaction and happiness).</p><p></p><p></p><p>During this month you will receive 30 practices aimed at harmonizing the third chakra. Read this letter carefully so that you understand what will happen and how.<br> <br><strong>1. The very essence</strong><br> This is not a training course, but an intensive workshop, the core of which is daily yoga practices. I conducted these practices in the mornings in live broadcasts, synchronizing the direction of each practice with the planetary rhythms on that day. In this intensive I have gathered video recordings of the best practices that were aimed specifically at the first chakra (sometimes in interaction with some other chakra), and supplemented them with behavioral (psychological) practices. The result is a most powerful charge for harmonizing the sphere of health. </p><p></p><p></p><p>If you have not taken my courses and do not understand what some “third chakra” has to do with it, I recommend that you combine taking this intensive with a workshop or course in which I smoothly lead you to an understanding of what we are doing here. It is important not simply to “believe” me, but to open understanding within yourself through personal experience - both on the yoga mat and in life. Then the practices begin to work much deeper. Otherwise we get physical education - since this is the basic understanding (experience) of yoga that everyone has.</p><p></p><p></p><p>You can supplement this intensive with the following educational programs:<br> - Workshop “A Month of Strength”: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a></p><p></p><p>- Course “Make Your Dream Come True”: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a> <br>  <br><strong>2. Yoga practices</strong><br> The yoga practices that await you differ from what you may encounter in a fitness center. I assume that the result matters to you, not playacting. We work with inner states (that is, with energies), combining meditation, pranayama, and asanas to the extent necessary to obtain the desired result at the deepest possible level. Most practices begin with a short introduction, which is necessary so that your consciousness switches from everydayness to the wave of the practice, you enter the corresponding energy flow, and your inner intention becomes activated. Then comes the practice itself, which on different days has a different duration and composition of elements. After the practice, I recommend that you spend some time in meditation, or perhaps, in the arising state of awareness, continue to perform the asanas that your body will ask for. The average duration of the practices is 30-40 minutes. But some practices are shorter, and some last about an hour. It is important that during the practice nothing distracts you and nothing hurries you. And one more very important thing - having begun the practice, do not interrupt it until it ends!!! Each practice is a living story that takes you along a certain path. If you interrupt the practice, you may end up in a less resourceful state than you were in at its beginning. Even if right now these words seem to you like mystification and empty esotericism, heed my recommendations. <br>  <br><strong>3. Behavioral practices</strong><br> Every day in the email, together with the yoga practice, I will send you a “tip of the day.” Try to perceive it not as yet another clever thought, similar to which you have already heard many times. I have no goal of surprising you by saying something you have not yet heard. Perceive this “tip” as a task, as a behavioral practice! Perform this practice on the given day. And believe me - it will become much more interesting for you, and this intensive will bring you much more benefit. Some such practices may seem easier to you, some harder. Some more pragmatic, some more psychological. In any case, it is not as if I suggested that you do 20 squats. Here we work with your behavioral and psychological patterns. And the key to success is not to fight with yourself, not to create additional inner tension, but, as in asanas, to breathe and relax. That is why the practice sounds soft - like a “tip of the day” - so as not to trigger an alarm signal. Read it, try it on, try during the day to gently follow this tip or at least to remember it, again trying it on and returning to the feeling that you are following it. Adapt to new states... In some cases, one such practice may stretch over several days or even months, because you will feel its significance and begin to introduce it into your life at the level of a habit, that is, adjusting the current homeostasis of the system. And although I did not build in a clear connection between the behavioral practices and the yoga practices that I offer in one email, nevertheless you can perform each yoga practice in the state that arises when you perceive yourself as following my tip. However, this is not at all obligatory, since each of these two practices is self-sufficient.<br>  <br><strong>4. Class schedule</strong><br> Every day at midnight a new practice will open for you (the previous one will disappear, like the previous day). Thanks to this approach, uncompleted practices will not accumulate into a snowball. During the day you can choose any time convenient for you and practice. I recommend that you practice in the morning, so that you live the day in the state obtained as a result of the practice, rather than go to sleep. Perceive this intensive not as a computer illusion, but as real life - in which everything important happens TODAY, and the yoga practice expands from the mat into the space of your manifestation in that world which you perceive as the most real!</p><p></p><p></p><p>By the way, there is a small nuance with the time you receive the second practice. If you signed up before 18:00, then you will receive the second practice at the nearest midnight. If you signed up after 18:00, then you will receive the second practice not at the nearest midnight, but at the following midnight. That is, you will have a reserve of time in case you do not manage to complete the practice on the day you signed up for the intensive. <br>  <br><strong>5. Do not force yourself</strong><br> When you buy a monthly membership at a fitness center, you do understand that you do not have to go there every day, right? Moreover, by taking too fast a pace, you may abandon the classes before you even reach the end of the month... The same rule applies to the practices of this intensive - do not be greedy! Practice at a pace convenient for you - every other day, every two days... Of course, it is good to practice every day, but it is even better to understand your long-term tasks and act accordingly. Most likely, your tasks go beyond one month, and you need to act regularly for a long time. I conceived this intensive so that you could go through it month after month as many times as needed until the goal you have set is achieved. This strategy is more effective than going all out for one month and then abandoning the practices or rushing off in another direction.<br>  <br><strong>6. Safety precautions</strong><br> I care about your health and remind you that only you bear responsibility for the adequacy of performing the asanas, pranayamas, and meditations that I will offer to your physical capabilities and mental state. It is important to understand that these are online classes, and I cannot control your state. You may have physical and psychological particularities. Please be attentive to your state. If you feel that some asana that I suggest performing is premature for you, perform it not very deeply, at a compromise level, or replace it altogether with another asana - one that approximately also engages the body but is easier for you.<br>  <br><strong>7. Answers to questions</strong><br> Every week (usually on Saturdays) I hold group online consultations (webinars) in Zoom, at which we communicate, maintain motivation, and discuss difficulties and questions that arise. Before each such consultation, I will send you an email indicating the date and time of its holding, as well as a link to join it. What is interesting to you will surely also be interesting to many others. Therefore, discussing questions at group consultations is most effective. If it happens that the time of the consultation is inconvenient for you, in that case send your questions by email before it begins. I will answer them at the consultation, and I will send you a link to the recording so that you can watch it at a time convenient for you. Consultation recordings are kept for one week.<br> <br>I wish you fruitful practices!</p><p></p><p></p><p>Sergei Zamkovoi</p>","de":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-strength/i3_email-3ec2fc66f836.png\" alt=\"Интенсив «Сила»\" width=\"504\" height=\"119\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Guten Tag, {{name}}!<br> <br>Ich freue mich, dass Sie sich entschieden haben, einen Monat lang gezielt mit den Zuständen von Kraft, Entschlossenheit, Zielstrebigkeit, Passionarität zu arbeiten … Es scheint, dass dies natürliche, jedem zugängliche Zustände sind. In der Gesellschaft wirken jedoch viele sowohl antreibende als auch verbietende Szenarien, die unser Verhalten steuern. Indem Sie Praktiken auf der Yogamatte und im Leben ausführen, nachdenken, Ihre Gedanken und Handlungen korrigieren, können Sie innerhalb eines Monats wichtige Ergebnisse erzielen, die sich sowohl auf der Ebene des Körpers (Gesundung) als auch auf der Ebene des psychologischen Hintergrunds (Zufriedenheit und Glück) zeigen.</p><p></p><p></p><p> In diesem Monat erhalten Sie 30 Praktiken, die auf die Harmonisierung des dritten Chakras ausgerichtet sind. Lesen Sie diesen Brief sorgfältig, damit Sie verstehen, was und wie geschehen wird. <br> <br><strong>1. Das Wesentliche</strong><br> Das ist kein Lehrkurs, sondern ein intensives Praktikum, dessen Kern tägliche Yoga-Praktiken sind. Diese Praktiken habe ich morgens live durchgeführt und dabei die Ausrichtung jeder Praxis mit den planetaren Rhythmen jenes Tages synchronisiert. In diesem Intensivkurs habe ich Videoaufzeichnungen der besten Praktiken gesammelt, die genau auf das erste Chakra ausgerichtet waren (manchmal in Wechselwirkung mit einem anderen Chakra), und sie um verhaltensbezogene (psychologische) Praktiken ergänzt. Daraus ist eine äußerst kraftvolle Ladung für die Harmonisierung des Bereichs Gesundheit entstanden. </p><p></p><p></p><p>Wenn Sie meine Kurse nicht besucht haben und nicht verstehen, was es mit diesem seltsamen „dritten Chakra“ auf sich hat, empfehle ich Ihnen, den Besuch dieses Intensivkurses mit einem Praktikum oder Kurs zu kombinieren, in dem ich Sie allmählich zum Verständnis dessen hinführe, womit wir uns hier beschäftigen. Wichtig ist, mir nicht einfach zu „glauben“, sondern in sich selbst ein Verständnis durch persönliche Erfahrung zu eröffnen – sowohl auf der Yogamatte als auch im Leben. Dann beginnen die Praktiken viel tiefer zu wirken. Andernfalls erhalten wir bloße Körperertüchtigung – denn das ist das grundlegende Verständnis (die Erfahrung) des Yoga, das jeder hat. </p><p></p><p></p><p>Diesen Intensivkurs können Sie durch folgende Lehrprogramme ergänzen:<br> - Praktikum „Monat der Kraft“: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a> </p><p></p><p>- Kurs „Verwirkliche den Traum“: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a> <br>  <br><strong>2. Yoga-Praktiken</strong><br> Die Yoga-Praktiken, die Sie erwarten, unterscheiden sich von dem, was Sie in einem Fitnesscenter antreffen können. Ich gehe davon aus, dass Ihnen das Ergebnis wichtig ist und nicht die Schauspielerei. Wir arbeiten mit inneren Zuständen (das heißt mit Energien) und verbinden Meditation, Pranayama und Asanas in dem Maße, wie es nötig ist, um das gewünschte Ergebnis auf möglichst tiefer Ebene zu erzielen. Die meisten Praktiken beginnen mit einer kurzen Einführung, die notwendig ist, damit Ihr Bewusstsein von der Alltäglichkeit auf die Welle der Praxis umschaltet, Sie in den entsprechenden energetischen Fluss eintreten und Ihr inneres Vorhaben aktiviert wird. Danach folgt die eigentliche Praxis, die an verschiedenen Tagen eine unterschiedliche Dauer und Zusammensetzung der Elemente hat. Nach der Praxis empfehle ich Ihnen, einige Zeit in Meditation zu verweilen, und vielleicht im entstandenen Zustand der Achtsamkeit weiter Asanas auszuführen, die Ihr Körper erbitten wird. Die durchschnittliche Dauer der Praktiken beträgt 30-40 Minuten. Aber manche Praktiken sind kürzer, und manche dauern etwa eine Stunde. Wichtig ist, dass Sie während der Praxis nichts ablenkt und nichts zur Eile treibt. Und noch sehr wichtig – wenn Sie die Praxis begonnen haben, unterbrechen Sie sie nicht bis zu ihrem Ende!!! Jede Praxis ist eine lebendige Geschichte, die Sie einen bestimmten Weg entlangführt. Wenn Sie die Praxis unterbrechen, können Sie in einem weniger ressourcenreichen Zustand landen, als Sie zu Beginn waren. Auch wenn Ihnen diese Worte jetzt wie Mystifikation und leere Esoterik erscheinen mögen, hören Sie auf meine Empfehlungen. <br>  <br><strong>3. Verhaltenspraktiken</strong><br> Jeden Tag werde ich Ihnen im Brief zusammen mit der Yoga-Praxis einen „Tipp des Tages“ schicken. Versuchen Sie, ihn nicht als einen weiteren klugen Gedanken zu betrachten, von der Art, wie Sie sie schon viele Male gehört haben. Ich habe nicht das Ziel, Sie zu überraschen, indem ich etwas sage, das Sie noch nicht gehört haben. Betrachten Sie diesen „Tipp“ als Aufgabe, als Verhaltenspraxis! Führen Sie diese Praxis an diesem Tag aus. Und glauben Sie mir – es wird Ihnen viel interessanter werden, und dieser Intensivkurs wird Ihnen viel mehr Nutzen bringen. Manche solcher Praktiken mögen Ihnen einfacher erscheinen, manche schwieriger. Manche pragmatischer, manche psychologischer. In jedem Fall ist es nicht so, als hätte ich Ihnen vorgeschlagen, 20 Kniebeugen zu machen. Hier arbeiten wir mit Ihren Verhaltens- und psychologischen Mustern. Und der Schlüssel zum Erfolg liegt darin, nicht mit sich zu kämpfen, keine zusätzliche innere Spannung zu erzeugen, sondern wie in den Asanas zu atmen und sich zu entspannen. Deshalb klingt die Praxis sanft – wie ein „Tipp des Tages“ –, damit kein Alarmsignal ausgelöst wird. Lesen Sie ihn, probieren Sie ihn aus, versuchen Sie im Laufe des Tages, diesem Tipp sanft zu folgen oder ihn wenigstens in Erinnerung zu rufen, ihn erneut anzuprobieren und in das Gefühl zurückzukehren, dass Sie ihm folgen. Passen Sie sich an die neuen Zustände an... In manchen Fällen kann sich eine solche Praxis über mehrere Tage oder sogar Monate erstrecken, weil Sie ihre Bedeutung spüren und beginnen, sie auf der Ebene der Gewohnheit in Ihr Leben einzuführen, das heißt, die aktuelle Homöostase des Systems zu korrigieren. Und obwohl ich keine klare Verbindung zwischen den Verhaltenspraktiken und den Yoga-Praktiken, die ich in einem Brief anbiete, angelegt habe, können Sie dennoch jede Yoga-Praxis in dem Zustand ausführen, der entsteht, wenn Sie sich als jemanden wahrnehmen, der meinem Tipp folgt. Das ist jedoch keineswegs zwingend, da jede dieser beiden Praktiken für sich genügt.<br>  <br><strong>4. Zeitplan der Übungen</strong><br> Jeden Tag um Mitternacht wird Ihnen eine neue Praxis freigeschaltet (die vorherige verschwindet dabei, wie der vergangene Tag). Durch diesen Ansatz wird sich bei Ihnen kein Schneeball unerledigter Praktiken ansammeln. Innerhalb von 24 Stunden können Sie jede Ihnen passende Zeit wählen und praktizieren. Ich empfehle Ihnen, morgens zu praktizieren, um den Tag in dem durch die Praxis entstandenen Zustand zu erleben, statt sich schlafen zu legen. Betrachten Sie diesen Intensivkurs nicht als Computer-Illusion, sondern als reales Leben – in dem alles Wichtige HEUTE geschieht und sich die Yoga-Praxis von der Matte auf den Raum Ihrer Manifestation in der Welt ausdehnt, die Sie als die realste wahrnehmen!</p><p></p><p></p><p>Übrigens gibt es eine kleine Besonderheit mit dem Zeitpunkt, zu dem Sie die zweite Praxis erhalten. Wenn Sie sich vor 18:00 Uhr angemeldet haben, erhalten Sie die zweite Praxis in der nächsten Mitternacht. Wenn Sie sich jedoch nach 18:00 Uhr angemeldet haben, erhalten Sie die zweite Praxis nicht in der nächsten, sondern in der darauffolgenden Mitternacht. Das heißt, Sie haben einen Zeitpuffer für den Fall, dass Sie die Praxis am Tag der Anmeldung zum Intensivkurs nicht mehr schaffen. <br>  <br><strong>5. Zwingen Sie sich nicht</strong><br> Wenn Sie ein Monatsabo in einem Fitnesscenter kaufen, verstehen Sie doch, dass Sie nicht unbedingt jeden Tag hingehen müssen? Mehr noch: Wenn Sie ein zu schnelles Tempo anschlagen, können Sie die Übungen aufgeben, ohne sogar das Ende des Monats erreicht zu haben... Für die Praktiken dieses Intensivkurses gilt dieselbe Regel – seien Sie nicht gierig! Praktizieren Sie in einem Ihnen angenehmen Rhythmus – jeden zweiten Tag, jeden dritten... Natürlich ist es gut, jeden Tag zu praktizieren, aber noch besser ist es, seine langfristigen Aufgaben zu verstehen und entsprechend zu handeln. Höchstwahrscheinlich gehen Ihre Aufgaben über einen Monat hinaus, und Sie müssen über einen längeren Zeitraum regelmäßig handeln. Diesen Intensivkurs habe ich so konzipiert, dass Sie ihn Monat für Monat so oft durchlaufen können, wie es nötig ist, bis das von Ihnen gesetzte Ziel erreicht ist. Diese Strategie ist effektiver, als einen Monat lang Vollgas zu geben und dann die Praktiken aufzugeben oder in eine andere Richtung davonzustürmen.<br>  <br><strong>6. Sicherheitstechnik</strong><br> Ich kümmere mich um Ihre Gesundheit und erinnere daran, dass allein Sie die Verantwortung dafür tragen, dass die Ausführung der Asanas, Pranayamas und Meditationen, die ich anbieten werde, Ihren körperlichen Möglichkeiten und Ihrem psychischen Zustand angemessen ist. Wichtig zu verstehen ist, dass dies Online-Kurse sind und ich Ihren Zustand nicht kontrollieren kann. Bei Ihnen können körperliche und psychologische Besonderheiten vorliegen. Bitte seien Sie aufmerksam gegenüber Ihrem Zustand. Wenn Sie spüren, dass eine bestimmte Asana, die ich zur Ausführung anbiete, für Sie verfrüht ist, führen Sie sie nicht sehr tief aus, auf einem Kompromissniveau, oder ersetzen Sie sie ganz durch eine andere Asana – eine, die den Körper ungefähr ebenfalls einbezieht, aber für Sie einfacher ist.<br>  <br><strong>7. Antworten auf Fragen</strong><br> Jede Woche (normalerweise samstags) führe ich in Zoom Gruppen-Online-Konsultationen (Webinare) durch, in denen wir uns austauschen, die Motivation aufrechterhalten und auftretende Schwierigkeiten und Fragen besprechen. Vor jeder solchen Konsultation werde ich Ihnen eine E-Mail mit Angabe von Datum und Uhrzeit ihrer Durchführung sowie einem Link zum Beitreten schicken. Was für Sie interessant ist, wird sicherlich auch für viele andere interessant sein. Deshalb ist die Besprechung von Fragen in den Gruppenkonsultationen am effektivsten. Sollte es geschehen, dass die Zeit der Konsultation für Sie ungünstig ist, senden Sie in diesem Fall Ihre Fragen vor ihrem Beginn per E-Mail. Ich werde sie in der Konsultation beantworten und Ihnen einen Link zur Aufzeichnung schicken, damit Sie sie zu einer Ihnen passenden Zeit ansehen können. Die Aufzeichnungen der Konsultationen werden eine Woche lang gespeichert.<br> <br>Ich wünsche Ihnen fruchtbare Praktiken!</p><p></p><p></p><p>Sergei Zamkovoi</p>","fr":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-strength/i3_email-3ec2fc66f836.png\" alt=\"Интенсив «Сила»\" width=\"504\" height=\"119\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Bonjour, {{name}} !<br> <br>Je suis heureux que vous ayez décidé, pendant un mois, de travailler de manière ciblée avec les états de force, de résolution, de détermination, de passionnalité... En apparence, ce sont des états naturels, accessibles à chacun. Cependant, dans la société agissent de nombreux scénarios, tant incitatifs que prohibitifs, qui gouvernent notre comportement. En accomplissant les pratiques sur le tapis de yoga et dans la vie, en réfléchissant, en corrigeant vos pensées et vos actes, au cours d’un mois vous pouvez obtenir des résultats importants qui se manifesteront tant au niveau du corps (amélioration de la santé) qu’au niveau du fond psychologique (satisfaction et bonheur).</p><p></p><p></p><p> Au cours de ce mois, vous recevrez 30 pratiques visant à harmoniser le troisième chakra. Lisez attentivement cette lettre pour comprendre ce qui va se passer et comment. <br> <br><strong>1. L’essentiel</strong><br> Ce n’est pas un cours d’apprentissage, mais un atelier intensif dont le cœur est constitué de pratiques quotidiennes de yoga. J’ai mené ces pratiques le matin en direct, en synchronisant l’orientation de chaque pratique avec les rythmes planétaires de ce jour-là. Dans cet intensif, j’ai réuni des enregistrements vidéo des meilleures pratiques qui étaient précisément destinées au premier chakra (parfois en interaction avec un autre chakra), et je les ai complétées par des pratiques comportementales (psychologiques). Il en est résulté une charge extrêmement puissante pour harmoniser le domaine de la santé. </p><p></p><p></p><p>Si vous n’avez pas suivi mes cours et ne comprenez pas ce que vient faire ici une quelconque « troisième chakra », je vous recommande de combiner le passage de cet intensif avec un atelier pratique ou un cours dans lequel j’amène progressivement à comprendre ce que nous faisons ici. Il est important non pas simplement de « me croire », mais d’ouvrir en vous la compréhension par l’expérience personnelle – tant sur le tapis de yoga que dans la vie. Alors les pratiques commencent à agir beaucoup plus profondément. Sinon, nous obtenons de la culture physique – car c’est la compréhension (l’expérience) de base du yoga que chacun possède.</p><p></p><p></p><p>Vous pouvez compléter cet intensif avec les programmes d’apprentissage suivants :<br> - Atelier pratique « Un mois de force » : <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a> </p><p></p><p>- Cours « Réalise ton rêve » : <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a> <br>  <br><strong>2. Pratiques de yoga</strong><br> Les pratiques de yoga qui vous attendent diffèrent de ce que vous pouvez rencontrer dans un centre de fitness. Je suppose que le résultat vous importe, et non le jeu d’acteur. Nous travaillons avec les états intérieurs (c’est-à-dire avec les énergies), en unissant la méditation, le pranayama et les asanas dans la mesure nécessaire pour obtenir le résultat souhaité au niveau le plus profond possible. La plupart des pratiques commencent par une courte introduction, nécessaire pour que votre conscience passe du quotidien à la vague de la pratique, que vous entriez dans le flux énergétique correspondant et que votre intention intérieure s’active. Vient ensuite la pratique elle-même, qui selon les jours a une durée et une composition d’éléments différentes. Après la pratique, je vous recommande de rester quelque temps en méditation, et peut-être, dans l’état de conscience apparu, de continuer à exécuter les asanas que votre corps demandera. La durée moyenne des pratiques est de 30-40 minutes. Mais certaines pratiques sont plus courtes, et d’autres durent environ une heure. Il est important que pendant la pratique rien ne vous distraie ni ne vous presse. Et encore très important - une fois la pratique commencée, ne l’interrompez pas avant sa fin!!! Chaque pratique est une histoire vivante qui vous conduit sur un chemin déterminé. En interrompant la pratique, vous pouvez vous retrouver dans un état moins pourvu en ressources que celui dans lequel vous étiez au début. Même si maintenant ces mots vous semblent une mystification et de l’ésotérisme vide, écoutez mes recommandations. <br>  <br><strong>3. Pratiques comportementales</strong><br> Chaque jour, dans l’e-mail, avec la pratique de yoga, je vous enverrai un « conseil du jour ». Essayez de le percevoir non pas comme une pensée intelligente de plus, semblable à celles que vous avez déjà entendues bien des fois. Je n’ai pas pour but de vous surprendre en disant ce que vous n’avez encore jamais entendu. Percevez ce « conseil » comme une tâche, comme une pratique comportementale ! Accomplissez cette pratique ce jour-là. Et croyez-moi - cela vous paraîtra beaucoup plus intéressant, et cet intensif vous apportera beaucoup plus de bienfaits. Certaines de ces pratiques peuvent vous sembler plus simples, d’autres plus difficiles. Certaines plus pragmatiques, d’autres plus psychologiques. Dans tous les cas, ce n’est pas comme si je vous proposais de faire 20 squats. Ici, nous travaillons avec vos schémas comportementaux et psychologiques. Et la clé du succès est de ne pas lutter contre vous-même, de ne pas provoquer une tension intérieure supplémentaire, mais, comme dans les asanas, de respirer et de vous détendre. C’est pourquoi la pratique se présente doucement - comme un « conseil du jour » - afin de ne pas déclencher de signal d’alarme. Lisez-le, essayez-le, tentez pendant la journée de suivre doucement ce conseil ou du moins de vous en souvenir, en l’essayant à nouveau et en revenant à la sensation que vous le suivez. Adaptez-vous aux nouveaux états... Dans certains cas, une telle pratique peut s’étendre sur plusieurs jours ou même plusieurs mois, parce que vous en ressentirez l’importance et commencerez à l’intégrer dans votre vie au niveau de l’habitude, c’est-à-dire en corrigeant l’homéostasie actuelle du système. Et, bien que je n’aie pas établi de lien précis entre les pratiques comportementales et les pratiques de yoga que je propose dans un même e-mail, vous pouvez néanmoins accomplir chaque pratique de yoga dans l’état apparu lorsque vous vous percevez comme suivant mon conseil. Cependant, ce n’est pas du tout obligatoire, car chacune de ces deux pratiques est autosuffisante.<br>  <br><strong>4. Horaire des séances</strong><br> Chaque jour à minuit, une nouvelle pratique s’ouvrira pour vous (la précédente disparaîtra alors, comme le jour précédent). Grâce à cette approche, les pratiques non accomplies ne s’accumuleront pas en boule de neige. Pendant les vingt-quatre heures, vous pouvez choisir n’importe quel moment qui vous convient et pratiquer. Je vous recommande de pratiquer le matin, afin de vivre la journée dans l’état obtenu grâce à la pratique, et non d’aller vous coucher. Percevez cet intensif non pas comme une illusion informatique, mais comme la vie réelle - dans laquelle tout ce qui est important se produit AUJOURD’HUI, et la pratique du yoga s’étend du tapis à l’espace de votre manifestation dans ce monde que vous percevez comme le plus réel !</p><p></p><p></p><p>À propos, il y a une petite nuance concernant le moment où vous recevez la deuxième pratique. Si votre inscription a eu lieu avant 18:00, vous recevrez la deuxième pratique à la prochaine minuit. Si en revanche votre inscription a eu lieu après 18:00, vous recevrez la deuxième pratique non pas à la prochaine minuit, mais à la minuit suivante. Autrement dit, vous aurez une marge de temps au cas où vous n’auriez pas le temps d’accomplir la pratique le jour de l’inscription à l’intensif. <br>  <br><strong>5. Ne vous forcez pas</strong><br> Lorsque vous achetez un abonnement mensuel dans un centre de fitness, vous comprenez bien que vous n’êtes pas obligé d’y aller chaque jour ? De plus, en prenant un rythme trop rapide, vous risquez d’abandonner les séances avant même d’arriver à la fin du mois... En ce qui concerne les pratiques de cet intensif, la même règle s’applique - ne soyez pas gourmand ! Pratiquez à un rythme qui vous convient - tous les deux jours, tous les trois jours... Bien sûr, il est bon de pratiquer chaque jour, mais il est encore mieux de comprendre vos tâches à long terme et d’agir en conséquence. Très probablement, vos tâches dépassent le cadre d’un mois, et vous devez agir régulièrement pendant une longue période. J’ai conçu cet intensif de manière à ce que vous puissiez le suivre mois après mois autant de fois que nécessaire, jusqu’à ce que l’objectif que vous vous êtes fixé soit atteint. Cette stratégie est plus efficace que de se donner à fond pendant un mois, puis d’abandonner les pratiques ou de partir dans une autre direction.<br>  <br><strong>6. Consignes de sécurité</strong><br> Je me soucie de votre santé et je vous rappelle que c’est vous qui portez la responsabilité de l’adéquation de l’exécution des asanas, des pranayamas et des méditations que je proposerai à vos possibilités physiques et à votre état psychique. Il est important de comprendre qu’il s’agit de séances en ligne et que je ne peux pas contrôler votre état. Vous pouvez avoir des particularités physiques et psychologiques. Veuillez être attentif à votre état. Si vous sentez qu’une asana que je propose d’exécuter est prématurée pour vous, exécutez-la pas très profondément, à un niveau de compromis, ou remplacez-la entièrement par une autre asana - telle qui sollicite à peu près autant le corps, mais qui est plus simple pour vous.<br>  <br><strong>7. Réponses aux questions</strong><br> Chaque semaine (généralement le samedi), j’anime sur Zoom des consultations en ligne de groupe (webinaires), pendant lesquelles nous échangeons, maintenons la motivation, discutons des difficultés et des questions qui surviennent. Avant chacune de ces consultations, je vous enverrai un e-mail indiquant la date et l’heure de sa tenue, ainsi qu’un lien pour la rejoindre. Ce qui vous intéresse intéressera sûrement aussi beaucoup d’autres personnes. C’est pourquoi il est plus efficace de discuter des questions lors des consultations de groupe. S’il arrive que l’heure de la consultation ne vous convienne pas, dans ce cas envoyez vos questions par e-mail avant son début. Je répondrai à ces questions lors de la consultation, et je vous enverrai un lien vers l’enregistrement afin que vous puissiez le regarder au moment qui vous convient. Les enregistrements des consultations sont conservés pendant une semaine.<br> <br>Je vous souhaite des pratiques fructueuses !</p><p></p><p></p><p>Sergei Zamkovoi</p>","it":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-strength/i3_email-3ec2fc66f836.png\" alt=\"Интенсив «Сила»\" width=\"504\" height=\"119\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Salve, {{name}}!<br> <br>Sono contento che abbiate deciso di lavorare intenzionalmente per un mese con gli stati di forza, determinazione, orientamento agli obiettivi, passionalità... In apparenza sembrano stati naturali, accessibili a chiunque. Tuttavia, nella società agiscono molti copioni, sia incentivanti sia inibitori, che governano il nostro comportamento. Eseguendo pratiche sul tappetino yoga e nella vita, riflettendo, correggendo i propri pensieri e le proprie azioni, nel corso di un mese si possono ottenere risultati importanti, che si manifesteranno sia a livello del corpo (miglioramento della salute), sia a livello dello sfondo psicologico (soddisfazione e felicità).</p><p></p><p></p><p> In questo mese riceverete 30 pratiche volte ad armonizzare il terzo chakra. Leggete attentamente questa lettera per capire cosa e come accadrà. <br> <br><strong>1. L''essenza stessa</strong><br> Non è un corso didattico, ma un praticum intensivo, il cui nucleo sono le pratiche yoga quotidiane. Queste pratiche le ho condotte al mattino in diretta, sincronizzando la direzione di ogni pratica con i ritmi planetari di quel giorno. In questo intensivo ho raccolto le videoregistrazioni delle migliori pratiche, che erano dirette proprio al primo chakra (a volte in interazione con qualche altro chakra), e le ho integrate con pratiche comportamentali (psicologiche). Il risultato è stato una carica potentissima per l''armonizzazione dell''ambito della salute. </p><p></p><p></p><p>Se non avete seguito i miei corsi e non capite cosa c''entri qui una qualche «terza chakra», vi consiglio di abbinare la partecipazione a questo intensivo a un praticum o a un corso in cui vi accompagno gradualmente alla comprensione di ciò di cui ci occupiamo qui. È importante non semplicemente «credermi», ma aprire in voi la comprensione attraverso l''esperienza personale - sia sul tappetino yoga sia nella vita. Allora le pratiche iniziano a funzionare molto più in profondità. Altrimenti otteniamo educazione fisica - poiché questa è la comprensione (esperienza) di base dello yoga che ognuno possiede. </p><p></p><p></p><p>Potete integrare questo intensivo con i seguenti programmi di studio:<br> - Praticum «Mese della forza»: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a> </p><p></p><p>- Corso «Realizza il sogno»: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a> <br>  <br><strong>2. Pratiche yoga</strong><br> Le pratiche yoga che vi attendono sono diverse da ciò che potete trovare in un centro fitness. Presumo che per voi conti il risultato, non la messa in scena. Lavoriamo con gli stati interiori (cioè con le energie), unendo meditazione, pranayama e asana nella misura necessaria per ottenere il risultato desiderato al livello più profondo possibile. La maggior parte delle pratiche inizia con una breve introduzione, necessaria affinché la vostra coscienza passi dalla quotidianità all''onda della pratica, entriate nel corrispondente flusso energetico e si attivi la vostra intenzione interiore. Segue poi la pratica stessa, che nei diversi giorni ha durata e composizione di elementi diverse. Dopo la pratica vi raccomando di restare per un po'' in meditazione, e magari, nello stato di consapevolezza che è emerso, di continuare a eseguire le asana che il vostro corpo chiederà. La durata media delle pratiche è di 30-40 minuti. Ma alcune pratiche sono più brevi, e alcune durano circa un''ora. È importante che durante la pratica nulla vi distragga e vi metta fretta. E ancora molto importante - una volta iniziata la pratica, non interrompetela prima della fine!!! Ogni pratica è una storia viva, che vi conduce lungo un determinato percorso. Interrompendo la pratica, potete ritrovarvi in uno stato meno ricco di risorse di quello in cui eravate all''inizio. Anche se ora queste parole vi sembrano una mistificazione e vuoto esoterismo, ascoltate le mie raccomandazioni. <br>  <br><strong>3. Pratiche comportamentali</strong><br> Ogni giorno, nella lettera insieme alla pratica yoga, vi invierò il «consiglio del giorno». Provate a percepirlo non come un altro pensiero intelligente, simile al quale ne avete già sentiti molti. Non ho l''obiettivo di sorprendervi dicendo qualcosa che non avete ancora sentito. Percepite questo «consiglio» come un compito, come una pratica comportamentale! Eseguite questa pratica nel giorno dato. E credetemi - vi risulterà molto più interessante, e questo intensivo vi porterà molto più beneficio. Alcune di queste pratiche possono sembrarvi più semplici, alcune più difficili. Alcune più pragmatiche, alcune più psicologiche. In ogni caso, non è come se vi avessi proposto di fare 20 squat. Qui lavoriamo con i vostri schemi comportamentali e psicologici. E la chiave del successo sta nel non combattere con voi stessi, nel non provocare ulteriore tensione interiore, ma, come nelle asana, respirare e rilassarvi. Perciò la pratica suona morbida - come «consiglio del giorno» - per non attivare un segnale d''allarme. Leggete, provate su di voi, provate durante la giornata a seguire dolcemente questo consiglio o almeno a ricordarlo, provandolo di nuovo e tornando alla sensazione che lo state seguendo. Adattatevi ai nuovi stati... In alcuni casi una sola pratica del genere può protrarsi per diversi giorni o addirittura mesi, perché ne sentirete l''importanza e inizierete a introdurla nella vostra vita a livello di abitudine, cioè correggendo l''attuale omeostasi del sistema. E, sebbene io non abbia previsto un legame preciso tra le pratiche comportamentali e le pratiche yoga che propongo in una stessa lettera, potete comunque eseguire ogni pratica yoga nello stato che emerge quando percepite voi stessi come seguaci del mio consiglio. Tuttavia, questo non è affatto obbligatorio, poiché ciascuna di queste due pratiche è autosufficiente.<br>  <br><strong>4. Orario delle lezioni</strong><br> Ogni giorno a mezzanotte vi si aprirà una nuova pratica (quella precedente scomparirà, come il giorno passato). Grazie a questo approccio, non si accumulerà una palla di neve di pratiche non eseguite. Nell''arco delle ventiquattro ore potete scegliere qualsiasi momento conveniente per voi e fare pratica. Vi raccomando di praticare al mattino, per vivere la giornata nello stato ottenuto grazie alla pratica, e non andare a dormire. Percepite questo intensivo non come un''illusione informatica, ma come vita reale - in cui tutto ciò che è importante accade OGGI, e la pratica yoga si espande dal tappetino allo spazio della vostra manifestazione in quel mondo che percepite come il più reale!</p><p></p><p></p><p>A proposito, c''è una piccola sfumatura riguardo al momento in cui riceverete la seconda pratica. Se vi siete iscritti prima delle 18:00, riceverete la seconda pratica alla mezzanotte più vicina. Se invece vi siete iscritti dopo le 18:00, riceverete la seconda pratica non alla mezzanotte più vicina, ma a quella successiva. Cioè avrete un margine di tempo nel caso non riusciate a completare la pratica nel giorno dell''iscrizione all''intensivo. <br>  <br><strong>5. Non fatevi violenza</strong><br> Quando acquistate un abbonamento mensile in un centro fitness, capite bene che non dovete per forza andarci ogni giorno? Inoltre, prendendo un ritmo troppo veloce, potete abbandonare le lezioni senza nemmeno arrivare alla fine del mese... Riguardo alle pratiche di questo intensivo vale la stessa regola - non siate avidi! Praticate al ritmo che vi è comodo - a giorni alterni, ogni due... Certo, è bene praticare ogni giorno, ma ancora meglio è capire i propri compiti a lungo termine e agire di conseguenza. Molto probabilmente i vostri compiti vanno oltre un mese, e avete bisogno di agire regolarmente per lungo tempo. Ho concepito questo intensivo in modo che possiate seguirlo mese dopo mese tutte le volte che serve, finché l''obiettivo che vi siete posti non sarà raggiunto. Questa strategia è più efficace che darci dentro per un mese e poi abbandonare le pratiche o lanciarsi in un''altra direzione.<br>  <br><strong>6. Tecnica di sicurezza</strong><br> Mi prendo cura della vostra salute e vi ricordo che solo voi siete responsabili dell''adeguatezza dell''esecuzione delle asana, dei pranayama e delle meditazioni che vi proporrò rispetto alle vostre possibilità fisiche e al vostro stato psichico. È importante capire che queste sono lezioni online e io non posso controllare il vostro stato. Potete avere particolarità fisiche e psicologiche. Per favore, siate attenti al vostro stato. Se sentite che qualche asana che vi propongo di eseguire è per voi prematura, eseguitela non molto profondamente, a un livello di compromesso, oppure sostituitela del tutto con un''altra asana - tale che coinvolga approssimativamente allo stesso modo il corpo, ma sia più semplice per voi.<br>  <br><strong>7. Risposte alle domande</strong><br> Ogni settimana (di solito il sabato) tengo su Zoom consultazioni online di gruppo (webinar), durante le quali comunichiamo, sosteniamo la motivazione, discutiamo le difficoltà e le domande che emergono. Prima di ciascuna di queste consultazioni vi invierò un''email con l''indicazione della data e dell''ora in cui si svolgerà, nonché il link per parteciparvi. Ciò che interessa a voi sarà sicuramente interessante anche per molti altri. Perciò, discutere le domande durante le consultazioni di gruppo è più efficace. Se accadesse che l''orario della consultazione non vi sia comodo, in questo caso inviate le vostre domande via email prima del suo inizio. Risponderò loro durante la consultazione, e vi invierò il link alla registrazione, così potrete guardarla nel momento per voi più comodo. Le registrazioni delle consultazioni vengono conservate per una settimana.<br> <br>Vi auguro pratiche fruttuose!</p><p></p><p></p><p>Sergei Zamkovoi</p>","es":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-strength/i3_email-3ec2fc66f836.png\" alt=\"Интенсив «Сила»\" width=\"504\" height=\"119\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Hola, {{name}}!<br> <br>Me alegra que hayan decidido trabajar durante un mes de forma intencionada con los estados de fuerza, determinación, orientación a objetivos, pasión... Parecería que son estados naturales, accesibles para cualquiera. Sin embargo, en la sociedad actúan multitud de guiones tanto incentivadores como prohibitivos que gobiernan nuestra conducta. Al realizar las prácticas en la esterilla de yoga y en la vida, reflexionando, corrigiendo sus pensamientos y acciones, a lo largo de un mes se pueden obtener resultados importantes que se manifestarán tanto a nivel del cuerpo (sanación) como a nivel del fondo psicológico (satisfacción y felicidad).</p><p></p><p></p><p> Durante este mes recibirán 30 prácticas dirigidas a armonizar el tercer chakra. Lean atentamente esta carta para comprender qué y cómo sucederá. <br> <br><strong>1. La esencia misma</strong><br> Esto no es un curso de formación, sino un taller intensivo cuyo núcleo son las prácticas diarias de yoga. Estas prácticas las realizaba por las mañanas en directo, sincronizando la dirección de cada práctica con los ritmos planetarios de ese día. En este intensivo he reunido grabaciones de vídeo de las mejores prácticas, que estaban dirigidas precisamente al primer chakra (a veces en interacción con algún otro chakra), y las he complementado con prácticas conductuales (psicológicas). Como resultado, se ha obtenido una carga poderosísima para armonizar el ámbito de la salud. </p><p></p><p></p><p>Si no han tomado mis cursos y no entienden qué tiene que ver aquí una cierta «tercera chakra», les recomiendo combinar la realización de este intensivo con un taller práctico o un curso en el que los conduzco suavemente hacia la comprensión de aquello de lo que nos ocupamos aquí. Es importante no simplemente «creerme», sino abrir en ustedes la comprensión a través de la experiencia personal, tanto en la esterilla de yoga como en la vida. Entonces las prácticas empiezan a funcionar mucho más profundamente. De lo contrario, obtenemos educación física, ya que esta es la comprensión básica (experiencia) del yoga que cada uno tiene. </p><p></p><p></p><p>Pueden complementar este intensivo con los siguientes programas de formación:<br> - Taller práctico «Mes de la fuerza»: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a> </p><p></p><p>- Curso «Haz realidad el sueño»: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a> <br>  <br><strong>2. Prácticas de yoga</strong><br> Las prácticas de yoga que le esperan se diferencian de lo que puede encontrar en un centro de fitness. Supongo que para usted es importante el resultado, y no el teatro. Trabajamos con estados internos (es decir, con energías), uniendo meditación, pranayama y asanas en la medida necesaria para obtener el resultado deseado al nivel más profundo posible. La mayoría de las prácticas comienzan con una breve introducción, necesaria para que su conciencia cambie de lo cotidiano a la onda de la práctica, entre en el flujo energético correspondiente y se active su intención interna. Después sigue la práctica en sí, que en distintos días tiene distinta duración y composición de elementos. Después de la práctica, le recomiendo permanecer un tiempo en meditación y, tal vez, en el estado de conciencia que haya surgido, continuar realizando las asanas que su cuerpo le pida. La duración media de las prácticas es de 30-40 minutos. Pero algunas prácticas son más cortas y otras duran cerca de una hora. Es importante que durante la práctica nada le distraiga ni le apresure. Y además es muy importante: una vez comenzada la práctica, ¡no la interrumpa hasta que termine!!! Cada práctica es una historia viva que le conduce por un camino determinado. Si interrumpe la práctica, puede encontrarse en un estado con menos recursos que aquel en el que estaba al comenzarla. Aunque ahora estas palabras le parezcan una mistificación y esoterismo vacío, haga caso a mis recomendaciones. <br>  <br><strong>3. Prácticas conductuales</strong><br> Cada día, en la carta, junto con la práctica de yoga, le enviaré el «consejo del día». Intente percibirlo no como una idea inteligente más, de las cuales ya ha oído muchas. No tengo el objetivo de sorprenderle diciendo algo que aún no haya oído. Perciba este «consejo» como una tarea, ¡como una práctica conductual! Realice esta práctica en el día indicado. Y créame: se sentirá mucho más interesado, y este intensivo le aportará mucho más beneficio. Algunas de estas prácticas pueden parecerle más fáciles, otras más difíciles. Algunas más pragmáticas, otras más psicológicas. En cualquier caso, no es como si le propusiera hacer 20 sentadillas. Aquí trabajamos con sus patrones conductuales y psicológicos. Y la clave del éxito está en no luchar contra uno mismo, no generar una tensión interna adicional, sino, como en las asanas, respirar y relajarse. Por eso la práctica suena suave, como «consejo del día», para no activar una señal de alarma. Léalo, pruébeselo, intente durante el día seguir suavemente este consejo o al menos recordarlo, probándoselo de nuevo y regresando a la sensación de que lo sigue. Adáptese a los nuevos estados... En algunos casos, una sola práctica así puede extenderse durante varios días o incluso meses, porque sentirá su importancia y comenzará a incorporarla a su vida a nivel de hábito, es decir, corrigiendo la homeostasis actual del sistema. Y, aunque no establecí una conexión clara entre las prácticas conductuales y las prácticas de yoga que propongo en una misma carta, aun así puede realizar cada práctica de yoga en el estado que surja cuando se percibe a sí mismo siguiendo mi consejo. Sin embargo, esto no es en absoluto obligatorio, ya que cada una de estas dos prácticas es autosuficiente.<br>  <br><strong>4. Horario de las clases</strong><br> Cada día, a medianoche, se le abrirá una nueva práctica (la anterior desaparecerá, como el día anterior). Gracias a este enfoque, no se le irá acumulando una bola de nieve de prácticas sin hacer. A lo largo del día puede elegir el momento que más le convenga y practicar. Le recomiendo practicar por la mañana, para vivir el día en el estado obtenido como resultado de la práctica, y no irse a dormir. Perciba este intensivo no como una ilusión informática, sino como la vida real, en la que todo lo importante ocurre HOY, y la práctica de yoga se expande desde la esterilla al espacio de su manifestación en el mundo que usted percibe como el más real.</p><p></p><p></p><p>Por cierto, hay un pequeño matiz con la hora de recepción de la segunda práctica. Si se inscribió antes de las 18:00, recibirá la segunda práctica en la próxima medianoche. Si se inscribió después de las 18:00, recibirá la segunda práctica no en la próxima medianoche, sino en la siguiente. Es decir, tendrá un margen de tiempo por si no logra realizar la práctica el día de la inscripción al intensivo. <br>  <br><strong>5. No se fuerce</strong><br> Cuando compra un abono mensual en un centro de fitness, entiende que no es obligatorio ir todos los días, ¿verdad? Además, si adopta un ritmo demasiado rápido, puede abandonar las clases sin haber llegado ni siquiera a fin de mes... Con las prácticas de este intensivo rige la misma regla: ¡no sea codicioso! Practique a un ritmo que le resulte cómodo: un día sí y otro no, cada dos días... Claro que es bueno practicar todos los días, pero aún mejor es comprender sus objetivos a largo plazo y actuar en consecuencia. Lo más probable es que sus objetivos vayan más allá de un mes, y necesite actuar con regularidad durante un tiempo prolongado. Concebí este intensivo para que pueda recorrerlo mes tras mes tantas veces como sea necesario, hasta que se alcance el objetivo que se ha propuesto. Esta estrategia es más eficaz que entregarse a tope durante un mes y luego abandonar las prácticas o lanzarse en otra dirección.<br>  <br><strong>6. Técnica de seguridad</strong><br> Me preocupo por su salud y le recuerdo que solo usted es responsable de la adecuación de la ejecución de las asanas, pranayamas y meditaciones que le propondré a sus posibilidades físicas y a su estado psíquico. Es importante comprender que son clases en línea, y no puedo controlar su estado. Usted puede tener particularidades físicas y psicológicas. Por favor, sea atento a su estado. Si siente que alguna asana que le propongo realizar es prematura para usted, ejecútela no muy profundamente, en un nivel de compromiso, o sustitúyala por completo por otra asana, una que incluya el cuerpo aproximadamente de la misma manera pero que le resulte más sencilla.<br>  <br><strong>7. Respuestas a las preguntas</strong><br> Cada semana (normalmente los sábados) realizo en Zoom consultas grupales en línea (webinars), en las que conversamos, mantenemos la motivación y discutimos las dificultades y preguntas que surgen. Antes de cada una de estas consultas le enviaré una carta con la fecha y la hora de su realización, así como un enlace para unirse a ella. Lo que es interesante para usted seguramente también lo será para muchas otras personas. Por eso, la discusión de preguntas en las consultas grupales es lo más eficaz. Si ocurre que la hora de la consulta le resulta inconveniente, en ese caso envíe sus preguntas por correo electrónico antes de su comienzo. Las responderé en la consulta y le enviaré un enlace a la grabación para que pueda verla en el momento que le resulte cómodo. Las grabaciones de las consultas se conservan durante una semana.<br> <br>¡Le deseo prácticas fructíferas!</p><p></p><p></p><p>Sergei Zamkovoi</p>","pt":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-strength/i3_email-3ec2fc66f836.png\" alt=\"Интенсив «Сила»\" width=\"504\" height=\"119\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Olá, {{name}}!<br> <br>Fico feliz que você tenha se decidido, ao longo de um mês, a trabalhar intencionalmente com os estados de força, determinação, foco em objetivos, passionalidade... Parece que são estados naturais, acessíveis a todos. No entanto, na sociedade atuam muitos cenários tanto incentivadores quanto proibitivos, que governam nosso comportamento. Executando práticas no tapete de yoga e na vida, refletindo, corrigindo seus pensamentos e atos, ao longo de um mês é possível obter resultados importantes, que se manifestarão tanto no nível do corpo (melhora da saúde) quanto no nível do fundo psicológico (satisfação e felicidade).</p><p></p><p></p><p> Durante este mês você receberá 30 práticas voltadas à harmonização do terceiro chakra. Leia atentamente esta carta para entender o que e como acontecerá. <br> <br><strong>1. A própria essência</strong><br> Este não é um curso de estudo, mas um praticum intensivo, cujo núcleo são as práticas diárias de yoga. Eu conduzia essas práticas pela manhã ao vivo, sincronizando a direção de cada prática com os ritmos planetários daquele dia. Neste intensivo, reuni gravações em vídeo das melhores práticas que eram direcionadas justamente ao primeiro chakra (às vezes em interação com algum outro chakra), e as complementei com práticas comportamentais (psicológicas). O resultado foi uma carga poderosíssima para harmonizar a esfera da saúde. </p><p></p><p></p><p>Se você não fez meus cursos e não entende o que tem a ver com isso esse tal “terceiro chakra”, recomendo que você combine a realização deste intensivo com um workshop ou curso no qual eu conduzo gradualmente ao entendimento do que estamos fazendo aqui. É importante não apenas “acreditar” em mim, mas abrir em si mesmo a compreensão por meio da experiência pessoal - tanto no tapete de yoga quanto na vida. Então as práticas começam a funcionar muito mais profundamente. Caso contrário, obtemos educação física - pois esta é a compreensão (experiência) básica do yoga que cada um tem. </p><p></p><p></p><p>Você pode complementar este intensivo com os seguintes programas de estudo:<br> - Workshop «Mês da força»: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a> </p><p></p><p>- Curso «Realize o sonho»: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a> <br>  <br><strong>2. Práticas de yoga</strong><br> As práticas de yoga que você terá pela frente diferem daquilo que você pode encontrar em uma academia de ginástica. Presumo que para você o resultado é importante, e não a teatralidade. Trabalhamos com estados internos (ou seja, com energias), unindo meditação, pranayama e asanas na medida necessária para obter o resultado desejado no nível mais profundo possível. A maioria das práticas começa com uma pequena introdução, necessária para que sua consciência se desligue da cotidianidade e entre na onda da prática, você entre no fluxo energético correspondente e sua intenção interna se ative. Em seguida vem a própria prática, que em dias diferentes tem duração e composição de elementos diferentes. Depois da prática, recomendo que você fique algum tempo em meditação e, talvez, no estado de consciência que surgir, continue executando as asanas que seu corpo pedir. A duração média das práticas é de 30 a 40 minutos. Mas algumas práticas são mais curtas, e algumas duram cerca de uma hora. É importante que durante a prática nada o distraia nem o apresse. E é ainda muito importante - tendo começado a prática, não a interrompa até o final!!! Cada prática é uma história viva que o conduz por um determinado caminho. Se interromper a prática, você pode acabar em um estado com menos recursos do que aquele em que estava no início dela. Mesmo que agora estas palavras lhe pareçam mistificação e esoterismo vazio, escute minhas recomendações. <br>  <br><strong>3. Práticas comportamentais</strong><br> Todos os dias, no e-mail, junto com a prática de yoga, enviarei a você o «conselho do dia». Tente não percebê-lo como mais um pensamento inteligente, semelhante aos que você já ouviu muitas vezes. Não tenho o objetivo de surpreendê-lo dizendo algo que você ainda não ouviu. Perceba esse «conselho» como uma tarefa, como uma prática comportamental! Execute essa prática no dia em questão. E acredite - vai se tornar muito mais interessante para você, e este intensivo lhe trará muito mais benefício. Algumas dessas práticas podem parecer-lhe mais simples, outras mais difíceis. Algumas mais pragmáticas, outras mais psicológicas. Em qualquer caso, não é como se eu tivesse proposto a você agachar 20 vezes. Aqui trabalhamos com seus padrões comportamentais e psicológicos. E a chave do sucesso está em não lutar consigo mesmo, não provocar tensão interna adicional, mas, como nas asanas, respirar e relaxar. Por isso a prática soa suave - como «conselho do dia» - para não provocar o sinal de alarme. Leia, experimente, tente ao longo do dia seguir suavemente esse conselho ou ao menos lembrar dele, experimentando-o de novo e retornando à sensação de que o está seguindo. Adapte-se aos novos estados... Em alguns casos, uma dessas práticas pode se estender por vários dias ou até meses, porque você sentirá sua importância e começará a introduzi-la em sua vida no nível do hábito, ou seja, corrigindo a homeostase atual do sistema. E, embora eu não tenha estabelecido uma ligação clara entre as práticas comportamentais e as práticas de yoga que proponho em um mesmo e-mail, ainda assim você pode executar cada prática de yoga no estado que surgir quando você se percebe seguindo meu conselho. No entanto, isso não é de modo algum obrigatório, pois cada uma dessas duas práticas é autossuficiente.<br>  <br><strong>4. Horário das aulas</strong><br> Todos os dias, à meia-noite, uma nova prática será aberta para você (a anterior desaparecerá, como o dia anterior). Graças a essa abordagem, não se acumulará em você uma bola de neve de práticas não realizadas. Ao longo do dia, você pode escolher o horário que lhe for conveniente e praticar. Recomendo que você pratique pela manhã, para viver o dia no estado obtido como resultado da prática, e não para ir dormir. Perceba este intensivo não como uma ilusão de computador, mas como a vida real - na qual tudo o que é importante acontece HOJE, e a prática de yoga se expande do tapete para o espaço da sua manifestação naquele mundo que você percebe como o mais real!</p><p></p><p></p><p>A propósito, há um pequeno detalhe com o horário de recebimento da segunda prática. Se você se inscreveu antes das 18:00, receberá a segunda prática na próxima meia-noite. Mas se se inscreveu depois das 18:00, receberá a segunda prática não na próxima meia-noite, mas na meia-noite seguinte. Ou seja, você terá uma reserva de tempo caso não consiga realizar a prática no dia da inscrição no intensivo. <br>  <br><strong>5. Não se force</strong><br> Quando você compra uma mensalidade em uma academia, você entende que não precisa ir lá todos os dias, certo? Mais do que isso, se pegar um ritmo rápido demais, você pode abandonar os treinos antes mesmo do fim do mês... Em relação às práticas deste intensivo, vale a mesma regra - não seja ganancioso! Pratique no ritmo que lhe for conveniente - um dia sim, dois não... Claro, é bom praticar todos os dias, mas ainda melhor é entender suas tarefas de longo prazo e agir de acordo. Muito provavelmente, suas tarefas vão além de um mês, e você precisa agir regularmente por um longo tempo. Concebi este intensivo de modo que você possa percorrê-lo mês após mês, quantas vezes for necessário, até que o objetivo que você estabeleceu seja alcançado. Essa estratégia é mais eficaz do que se entregar a fundo por um mês e depois abandonar as práticas ou partir para outra direção.<br>  <br><strong>6. Técnica de segurança</strong><br> Eu me preocupo com sua saúde e lembro que somente você é responsável pela adequação da execução das asanas, pranayamas e meditações que eu proporei às suas possibilidades físicas e ao seu estado psíquico. É importante entender que estas são aulas on-line, e eu não posso controlar seu estado. Você pode ter particularidades físicas e psicológicas. Por favor, esteja atento ao seu estado. Se você sentir que alguma asana que proponho executar é prematura para você, execute-a não muito profundamente, em um nível de meio-termo, ou substitua-a totalmente por outra asana - que envolva o corpo de modo aproximadamente semelhante, mas seja mais simples para você.<br>  <br><strong>7. Respostas às perguntas</strong><br> Toda semana (normalmente aos sábados) realizo no Zoom consultorias on-line em grupo (webinars), nas quais conversamos, mantemos a motivação, discutimos as dificuldades e dúvidas que surgem. Antes de cada consultoria dessas, enviarei a você um e-mail com a data e o horário de sua realização, bem como o link para se juntar a ela. O que é interessante para você certamente também será interessante para muitas outras pessoas. Por isso, discutir as questões nas consultorias em grupo é o mais eficaz. Se acontecer de o horário da consultoria ser inconveniente para você, nesse caso envie suas perguntas por e-mail antes de ela começar. Eu responderei a elas na consultoria e enviarei a você o link da gravação, para que possa assisti-la no horário que lhe for conveniente. As gravações das consultorias ficam salvas por uma semana.<br> <br>Desejo a você práticas frutíferas!</p><p></p><p></p><p>Sergei Zamkovoi</p>","nl":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-strength/i3_email-3ec2fc66f836.png\" alt=\"Интенсив «Сила»\" width=\"504\" height=\"119\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Hallo, {{name}}!<br> <br>Ik ben blij dat je besloten hebt om een maand lang gericht te werken met de toestanden van kracht, vastberadenheid, doelgerichtheid, passionariteit... Het lijken natuurlijke toestanden die voor iedereen toegankelijk zijn. In de samenleving werken echter talrijke zowel stimulerende als verbiedende scenario''s die ons gedrag sturen. Door praktijken op de yogamat en in het leven uit te voeren, na te denken, je gedachten en daden bij te sturen, kun je in een maand belangrijke resultaten behalen, die zich zowel op het niveau van het lichaam (gezondwording) als op het niveau van de psychologische achtergrond (tevredenheid en geluk) manifesteren.</p><p></p><p></p><p> In de loop van deze maand ontvang je 30 praktijken die gericht zijn op het harmoniseren van de derde chakra. Lees deze brief aandachtig, zodat je begrijpt wat er zal gebeuren en hoe.<br> <br><strong>1. De kern</strong><br> Dit is geen leercursus, maar een intensieve praktijk, waarvan de dagelijkse yogapraktijken de kern vormen. Deze praktijken gaf ik ''s ochtends live, waarbij ik de richting van elke praktijk afstemde op de planetaire ritmen van die dag. In dit intensief heb ik video-opnamen verzameld van de beste praktijken die juist op de eerste chakra waren gericht (soms in wisselwerking met een andere chakra), en deze aangevuld met gedragsmatige (psychologische) praktijken. Het resultaat is een uiterst krachtige impuls voor het harmoniseren van het gebied van gezondheid. </p><p></p><p></p><p>Als je mijn cursussen niet hebt gevolgd en niet begrijpt wat die zogenaamde «derde chakra» ermee te maken heeft, raad ik je aan om deze intensive te combineren met een practicum of cursus waarin ik je geleidelijk naar het begrip breng van waar we hier mee bezig zijn. Het is belangrijk om mij niet alleen maar «te geloven», maar in jezelf begrip te openen via persoonlijke ervaring - zowel op de yogamat als in het leven. Dan gaan de praktijken veel dieper werken. Anders krijgen we gymnastiek - want dit is het basisbegrip (de ervaring) van yoga dat iedereen heeft.</p><p></p><p></p><p>Je kunt deze intensive aanvullen met de volgende leerprogramma''s:<br> - Practicum «Maand van kracht»: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a></p><p></p><p>- Cursus «Verwezenlijk je droom»: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br>  <br><strong>2. Yogapraktijken</strong><br> Yogapraktijken die u te wachten staan, verschillen van wat u in een fitnesscentrum kunt tegenkomen. Ik ga ervan uit dat het u om het resultaat gaat, en niet om toneelspel. We werken met innerlijke toestanden (dat wil zeggen met energieën), waarbij ik meditatie, pranayama en asana''s verbind voor zover dat nodig is om het gewenste resultaat op een zo diep mogelijk niveau te bereiken. De meeste praktijken beginnen met een korte inleiding, die nodig is opdat uw bewustzijn van de alledaagsheid overschakelt naar de golf van de praktijk, u in de bijbehorende energetische stroom komt en uw innerlijke intentie wordt geactiveerd. Daarna volgt de praktijk zelf, die op verschillende dagen een verschillende duur en samenstelling van elementen heeft. Na de praktijk raad ik u aan enige tijd in meditatie te blijven, of misschien in de ontstane staat van bewustzijn door te gaan met het uitvoeren van de asana''s die uw lichaam zal vragen. De gemiddelde duur van de praktijken is 30-40 minuten. Maar sommige praktijken zijn korter, en sommige duren ongeveer een uur. Het is belangrijk dat niets u tijdens de praktijk afleidt en dat niets u opjaagt. En heel belangrijk: als u eenmaal aan de praktijk bent begonnen, onderbreek deze dan niet tot het einde!!! Elke praktijk is een levend verhaal dat u langs een bepaald pad leidt. Als u de praktijk onderbreekt, kunt u in een minder veerkrachtige toestand terechtkomen dan aan het begin ervan. Zelfs als deze woorden u nu als mystificatie en lege esoterie voorkomen, luister naar mijn aanbevelingen. <br>  <br><strong>3. Gedragspraktijken</strong><br> Elke dag zal ik u in de brief samen met de yogapraktijk een «advies van de dag» sturen. Probeer het niet te zien als nog een slimme gedachte, waarvan u er al vele malen soortgelijke hebt gehoord. Het is niet mijn doel u te verrassen door iets te zeggen wat u nog niet hebt gehoord. Zie dit «advies» als een opdracht, als een gedragspraktijk! Voer deze praktijk op die dag uit. En geloof me - het zal veel interessanter voor u worden, en dit intensief zal u veel meer nut brengen. Sommige van zulke praktijken kunnen u eenvoudiger lijken, sommige moeilijker. Sommige pragmatischer, sommige psychologischer. In ieder geval is het niet alsof ik u heb voorgesteld twintig keer te hurken. Hier werken we met uw gedragsmatige en psychologische patronen. En de sleutel tot succes is om niet met uzelf te vechten, geen extra innerlijke spanning op te roepen, maar zoals in de asana''s - te ademen en te ontspannen. Daarom klinkt de praktijk zacht - als &quot;advies van de dag&quot; - om geen alarmsignaal op te roepen. Lees het, pas het op uzelf toe, probeer dit advies gedurende de dag zachtjes te volgen of er ten minste aan te denken, het opnieuw toe te passen en terug te keren naar het gevoel dat u het volgt. Pas u aan de nieuwe toestanden aan... In sommige gevallen kan één zo''n praktijk zich over meerdere dagen of zelfs maanden uitstrekken, omdat u het belang ervan zult voelen, en het in uw leven op het niveau van een gewoonte zult gaan invoeren, dat wil zeggen door de huidige homeostase van het systeem bij te stellen. En hoewel ik geen duidelijke verbinding heb aangelegd tussen de gedragspraktijken en de yogapraktijken die ik in één brief aanbied, kunt u toch elke yogapraktijk uitvoeren in de toestand die ontstaat wanneer u zichzelf ziet als iemand die mijn advies volgt. Dat is echter helemaal niet verplicht, omdat elk van deze twee praktijken op zichzelf voldoende is.<br>  <br><strong>4. Lesschema</strong><br> Elke dag om middernacht gaat er een nieuwe praktijk voor u open (de vorige verdwijnt daarbij, zoals de vorige dag). Dankzij deze aanpak zal er bij u geen sneeuwbal van niet-uitgevoerde praktijken ontstaan. Binnen een etmaal kunt u een voor u geschikt tijdstip kiezen en oefenen. Ik raad u aan ''s ochtends te oefenen, zodat u de dag kunt doorbrengen in de toestand die u door de praktijk hebt verkregen, in plaats van naar bed te gaan. Zie dit intensief niet als een computerillusie, maar als het echte leven - waarin alles wat belangrijk is VANDAAG gebeurt, en de yogapraktijk zich van de mat uitbreidt naar de ruimte van uw manifestatie in die wereld die u als de meest werkelijke ervaart!</p><p></p><p></p><p>Trouwens, er is een kleine nuance met betrekking tot de tijd waarop u de tweede praktijk ontvangt. Als u zich vóór 18:00 hebt ingeschreven, ontvangt u de tweede praktijk bij de eerstvolgende middernacht. Als u zich na 18:00 hebt ingeschreven, ontvangt u de tweede praktijk niet bij de eerstvolgende, maar bij de daaropvolgende middernacht. Dat wil zeggen dat u extra tijd hebt voor het geval u er niet aan toe komt de praktijk uit te voeren op de dag van inschrijving voor het intensief. <br>  <br><strong>5. Doe uzelf geen geweld aan</strong><br> Wanneer u een maandabonnement bij een fitnesscentrum koopt, begrijpt u toch dat u er niet elke dag heen hoeft? Sterker nog, als u een te snel tempo aanneemt, kunt u de lessen laten vallen nog voordat u zelfs maar het einde van de maand hebt bereikt... Voor de praktijken van dit intensief geldt dezelfde regel - wees niet hebberig! Oefen in een tempo dat u bevalt - om de dag, om de twee dagen... Natuurlijk is het goed om elke dag te oefenen, maar nog beter is - uw langetermijntaken te begrijpen en dienovereenkomstig te handelen. Waarschijnlijk gaan uw taken verder dan één maand, en moet u langdurig regelmatig in actie komen. Dit intensief heb ik zo bedacht dat u het maand na maand kunt doorlopen, zo vaak als nodig, totdat het door u gestelde doel is bereikt. Deze strategie is effectiever dan één maand er flink tegenaan te gaan en daarna de praktijken te laten vallen of in een andere richting te schieten.<br>  <br><strong>6. Veiligheidstechniek</strong><br> Ik geef om uw gezondheid en herinner u eraan dat alleen u verantwoordelijk bent voor of de uitvoering van de asana''s, pranayama''s en meditaties die ik zal aanbieden adequaat is voor uw lichamelijke mogelijkheden en psychische toestand. Het is belangrijk te begrijpen dat dit online lessen zijn, en dat ik uw toestand niet kan controleren. U kunt lichamelijke en psychologische bijzonderheden hebben. Wees alstublieft aandachtig voor uw eigen toestand. Als u merkt dat een bepaalde asana die ik voorstel uit te voeren voor u voortijdig is, voer haar dan niet erg diep uit, op een compromisniveau, of vervang haar helemaal door een andere asana - een die ongeveer ook het lichaam betrekt, maar eenvoudiger voor u is.<br>  <br><strong>7. Antwoorden op vragen</strong><br> Elke week (meestal op zaterdag) geef ik in Zoom groepsgewijze onlineconsulten (webinars), waarin we met elkaar praten, de motivatie ondersteunen en opkomende moeilijkheden en vragen bespreken. Voor elk zo''n consult stuur ik u een bericht met de datum en tijd waarop het plaatsvindt, evenals een link om eraan deel te nemen. Wat voor u interessant is, zal zeker ook voor velen anderen interessant zijn. Daarom is het bespreken van vragen in groepsconsulten het meest effectief. Als het zo uitkomt dat het tijdstip van het consult u niet uitkomt, stuur uw vragen dan vóór het begin per e-mail. Ik zal ze tijdens het consult beantwoorden, en u stuur ik een link naar de opname, zodat u deze op een voor u geschikt moment kunt bekijken. Opnamen van consulten worden gedurende één week bewaard.<br> <br>Ik wens u vruchtbare praktijken!</p><p></p><p></p><p>Sergei Zamkovoi</p>"}'::jsonb,'{"ru":[{"id":"intensive-strength-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-strength/i3_email-3ec2fc66f836.png","alt":"Интенсив «Сила»","width":"100%","align":"center","naturalWidth":600,"naturalHeight":142,"marginTop":0,"marginBottom":24},{"id":"intensive-strength-1-text","type":"text","html":"<p>Здравствуйте, {{name}}!<br> <br>Я рад, что вы решились в течение месяца целенаправленно поработать с состояниями силы, решительности, целеустремлённости, пассионарности... Вроде бы как это естественные, доступные каждому состояния. Однако, в социуме действует множество как побудительных, так и запретительных сценариев, которые управляют нашим поведением. Выполняя практики на йоговском коврике и в жизни, размышляя, корректируя свои мысли и поступки, в течение месяца можно получить важные результаты, которые проявятся как на уровне тела (оздоравливание), так и на уровне психологического фона (удовлетворённость и счастье).</p><p></p><p></p><p> В течение этого месяца вы получите 30 практик, направленных на гармонизацию третьей чакры. Внимательно прочитайте это письмо, чтобы понимать, что и как будет происходить. <br> <br><strong>1. Самая суть</strong><br> Это не учебный курс, а интенсивный практикум, ядром которого являются ежедневные практики йоги. Данные практики я проводил по утрам в прямом эфире, синхронизируя направление каждой практики с планетными ритмами в тот день. В этом интенсиве я собрал видеозаписи лучших практик, которые были направлены именно на первую чакру (иногда во взаимодействии с какой-нибудь ещё чакрой), дополнил их поведенческими (психологическими) практиками. В результате получился мощнейший заряд для гармонизации сферы здоровья. </p><p></p><p></p><p>Если вы не проходили моих курсов и не понимаете при чём здесь какая-то там «третья чакра», я рекомендую вам совместить прохождение данного интенсива с практикумом или курсом, в котором я плавно подвожу к пониманию того, чем мы здесь занимаемся. Важно не просто «поверить» мне, а открыть в себе понимание через личный опыт - как на йоговском коврике, так и в жизни. Тогда практики начинают работать гораздо глубже. Иначе получаем физкультуру - так как это базовое понимание (опыт) йоги, которое есть у каждого. </p><p></p><p></p><p>Данный интенсив вы можете дополнить следующими учебными программами:<br> - Практикум «Месяц силы»: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a> </p><p></p><p>- Курс «Осуществи мечту»: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a> <br>  <br><strong>2. Практики йоги</strong><br> Практики йоги, которые вас ожидают, отличаются от того, что вы можете встретить в фитнес-центре. Я предполагаю, что вам важен результат, а не лицедейство. Мы работаем с внутренними состояниями (то есть с энергиями), соединяя медитацию, пранаяму и асаны в той мере, в которой это необходимо для получения желаемого результата на максимально глубоком уровне. Большинство практик начинаются с небольшого введения, которое необходимо, чтобы ваше сознание переключилось с обыденности на волну практики, вы вошли в соответствующий энергетический поток и активировалось ваше внутреннее намерение. Далее следует сама практика, которая в разные дни имеет разную длительность и состав элементов. После практики я рекомендую вам некоторое время побыть в медитации, а может быть в возникшем состоянии осознанности продолжить выполнять асаны, которые будет просить ваше тело. Средняя продолжительность практик 30-40 минут. Но некоторые практики короче, а некоторые длятся около часа. Важно, чтобы во время практики вас ничто не отвлекало и не торопило. И ещё очень важно - начав практику, не прерывайтесь до её окончания!!! Каждая практика - это живая история, которая проводит вас по определённому пути. Прервав практику, вы можете оказаться в менее ресурсном состоянии, чем были в её начале. Даже если сейчас эти слова вам кажутся мистификацией и пустой эзотерикой, прислушайтесь к моим рекомендациям. <br>  <br><strong>3. Поведенческие практики</strong><br> Каждый день в письме вместе с практикой йоги я буду присылать вам «совет дня». Попробуйте воспринимать его не как ещё одну умную мысль, подобную которой вы уже много раз слышали. У меня нет цели вас удивить, сказав то, что вы ещё не слышали. Воспринимайте этот «совет» как задание, как поведенческую практику! Выполняйте эту практику в данный день. И поверьте - вам станет гораздо интересней, и этот интенсив принесёт вам гораздо больше пользы. Некоторые такие практики могут казаться вам проще, некоторые сложнее. Некоторые прагматичнее, некоторые более психологическими. В любом случае, это не как если бы я предложил вам 20 раз присесть. Тут мы работаем с вашими поведенческими и психологическими шаблонами. И ключ к успеху в том, чтобы не сражаться с собой, не вызывать дополнительное внутреннее напряжение, а как в асанах - дышать и расслабляться. Поэтому практика звучит мягко - как &quot;совет дня&quot; - чтобы не вызывать сигнал тревоги. Прочитайте, примерьте, попробуйте в течение дня мягко следовать этому совету или хотя бы вспоминать его, вновь примеряя и возвращаясь в ощущение, что вы ему следуете. Адаптируйтесь к новым состояниям... В некоторых случаях одна такая практика может растянуться на несколько дней или даже месяцев, потому что вы ощутите её значимость, и начнёте внедрять её в свою жизнь на уровне привычки, то есть корректируя текущий гомеостаз системы. И, хотя я не закладывал чёткую связь между поведенческими практиками и практиками йоги, которые предлагаю в одном письме, тем не менее вы можете выполнять каждую практику йоги в состоянии, возникшем когда вы воспринимаете себя следующим моему совету. Однако, это вовсе не обязательно, так как каждая из этих двух практик самодостаточна.<br>  <br><strong>4. Расписание занятий</strong><br> Каждый день в полночь вам будет открываться новая практика (прошлая при этом будет исчезать, как прошлый день). Благодаря такому подходу, у вас не будет накапливаться снежный ком невыполненных практик. В течение суток вы можете выбрать любое удобное вам время, и позаниматься. Я рекомендую вам заниматься утром, чтобы в полученном в результате практики состоянии проживать день, а не спать лечь. Воспринимайте этот интенсив не как компьютерную иллюзию, а как реальную жизнь - в которой всё важное происходит СЕГОДНЯ, и практика йоги расширяется с коврика на пространство вашей проявленности в том мире, который вы воспринимаете, как наиболее реальный!</p><p></p><p></p><p>Кстати, есть небольшой нюанс с временем получения второй практики. Если вы записались до 18:00, то вторую практику вы получите в ближайшую полночь. Если же вы записались после 18:00, то вторую практику вы получите не в ближайшую, а в следующую полночь. То есть у вас будет запас времени на случай, если вы не успеете выполнить практику в день записи на интенсив. <br>  <br><strong>5. Не насилуйте себя</strong><br> Когда вы покупаете месячный абонемент в фитнес центр, вы ведь понимаете, что вам не обязательно ходить в него каждый день? Более того, взяв слишком быстрый темп, вы можете забросить занятия не дойдя даже до конца месяца... В отношении практик данного интенсива действует то же правило - не жадничайте! Занимайтесь в удобном вам ритме - через день, через два... Конечно, хорошо заниматься каждый день, но ещё лучше - понимать свои долгосрочные задачи, и действовать соответственно. Скорее всего, ваши задачи выходят за рамки одного месяца, и вам необходимо регулярно действовать длительное время. Данный интенсив я задумал так, чтобы вы могли проходить его месяц за месяцем столько раз, сколько потребуется, пока поставленная вами цель не будет достигнута. Эта стратегия эффективней, чем один месяц втопить, а потом забросить практики или рвануть в другом направлении.<br>  <br><strong>6. Техника безопасности</strong><br> Я забочусь о вашем здоровье и напоминаю, что только вы несёте ответственность за адекватность выполнения асан, пранаям и медитаций, которые я буду предлагать, вашим физическим возможностям и психическому состоянию. Важно понимать, что это онлайн занятия, и я не могу контролировать ваше состояние. У вас могут быть физические и психологические особенности. Пожалуйста, будьте внимательны к своему состоянию. Если вы почувствуете, что какая-то асана, которую я предлагаю выполнить, для вас преждевременна, выполните её не очень глубоко, на компромиссном уровне, или вовсе замените её другой асаной - такой, которая приблизительно также включает тело, но проще для вас.<br>  <br><strong>7. Ответы на вопросы</strong><br> Каждую неделю (обычно по субботам) я провожу в Zoom групповые онлайн-консультации (вебинары), на которых мы общаемся, поддерживаем мотивацию, обсуждаем возникающие трудности и вопросы. Перед каждой такой консультацией я буду высылать вам письмо с указанием даты и времени её проведения, а также ссылкой для того, чтобы к ней присоединиться. То, что интересно вам, наверняка будет интересно и многим другим. Поэтому, обсуждение вопросов на групповых консультациях наиболее эффективно. Если случится так, что время консультации окажется вам неудобным, в этом случае пришлите ваши вопросы имейлом до её начала. Я отвечу на них на консультации, а вам пришлю ссылку на запись, чтобы вы могли посмотреть её в удобное вам время. Записи консультаций сохраняются в течение одной недели.<br> <br>Желаю вам плодотворных практик!</p><p></p><p>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"en":[{"id":"intensive-strength-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-strength/i3_email-3ec2fc66f836.png","alt":"Интенсив «Сила»","width":"100%","align":"center","naturalWidth":600,"naturalHeight":142,"marginTop":0,"marginBottom":24},{"id":"intensive-strength-1-text","type":"text","html":"<p>Hello, {{name}}!<br> <br>I am glad that you have decided to spend a month purposefully working with the states of strength, decisiveness, purposefulness, passionarity... It would seem that these are natural states available to everyone. However, in society there are many both motivating and prohibitive scripts that control our behavior. By performing practices on the yoga mat and in life, reflecting, correcting your thoughts and actions, over the course of a month you can obtain important results that will manifest both on the level of the body (healing) and on the level of psychological background (satisfaction and happiness).</p><p></p><p></p><p>During this month you will receive 30 practices aimed at harmonizing the third chakra. Read this letter carefully so that you understand what will happen and how.<br> <br><strong>1. The very essence</strong><br> This is not a training course, but an intensive workshop, the core of which is daily yoga practices. I conducted these practices in the mornings in live broadcasts, synchronizing the direction of each practice with the planetary rhythms on that day. In this intensive I have gathered video recordings of the best practices that were aimed specifically at the first chakra (sometimes in interaction with some other chakra), and supplemented them with behavioral (psychological) practices. The result is a most powerful charge for harmonizing the sphere of health. </p><p></p><p></p><p>If you have not taken my courses and do not understand what some “third chakra” has to do with it, I recommend that you combine taking this intensive with a workshop or course in which I smoothly lead you to an understanding of what we are doing here. It is important not simply to “believe” me, but to open understanding within yourself through personal experience - both on the yoga mat and in life. Then the practices begin to work much deeper. Otherwise we get physical education - since this is the basic understanding (experience) of yoga that everyone has.</p><p></p><p></p><p>You can supplement this intensive with the following educational programs:<br> - Workshop “A Month of Strength”: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a></p><p></p><p>- Course “Make Your Dream Come True”: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a> <br>  <br><strong>2. Yoga practices</strong><br> The yoga practices that await you differ from what you may encounter in a fitness center. I assume that the result matters to you, not playacting. We work with inner states (that is, with energies), combining meditation, pranayama, and asanas to the extent necessary to obtain the desired result at the deepest possible level. Most practices begin with a short introduction, which is necessary so that your consciousness switches from everydayness to the wave of the practice, you enter the corresponding energy flow, and your inner intention becomes activated. Then comes the practice itself, which on different days has a different duration and composition of elements. After the practice, I recommend that you spend some time in meditation, or perhaps, in the arising state of awareness, continue to perform the asanas that your body will ask for. The average duration of the practices is 30-40 minutes. But some practices are shorter, and some last about an hour. It is important that during the practice nothing distracts you and nothing hurries you. And one more very important thing - having begun the practice, do not interrupt it until it ends!!! Each practice is a living story that takes you along a certain path. If you interrupt the practice, you may end up in a less resourceful state than you were in at its beginning. Even if right now these words seem to you like mystification and empty esotericism, heed my recommendations. <br>  <br><strong>3. Behavioral practices</strong><br> Every day in the email, together with the yoga practice, I will send you a “tip of the day.” Try to perceive it not as yet another clever thought, similar to which you have already heard many times. I have no goal of surprising you by saying something you have not yet heard. Perceive this “tip” as a task, as a behavioral practice! Perform this practice on the given day. And believe me - it will become much more interesting for you, and this intensive will bring you much more benefit. Some such practices may seem easier to you, some harder. Some more pragmatic, some more psychological. In any case, it is not as if I suggested that you do 20 squats. Here we work with your behavioral and psychological patterns. And the key to success is not to fight with yourself, not to create additional inner tension, but, as in asanas, to breathe and relax. That is why the practice sounds soft - like a “tip of the day” - so as not to trigger an alarm signal. Read it, try it on, try during the day to gently follow this tip or at least to remember it, again trying it on and returning to the feeling that you are following it. Adapt to new states... In some cases, one such practice may stretch over several days or even months, because you will feel its significance and begin to introduce it into your life at the level of a habit, that is, adjusting the current homeostasis of the system. And although I did not build in a clear connection between the behavioral practices and the yoga practices that I offer in one email, nevertheless you can perform each yoga practice in the state that arises when you perceive yourself as following my tip. However, this is not at all obligatory, since each of these two practices is self-sufficient.<br>  <br><strong>4. Class schedule</strong><br> Every day at midnight a new practice will open for you (the previous one will disappear, like the previous day). Thanks to this approach, uncompleted practices will not accumulate into a snowball. During the day you can choose any time convenient for you and practice. I recommend that you practice in the morning, so that you live the day in the state obtained as a result of the practice, rather than go to sleep. Perceive this intensive not as a computer illusion, but as real life - in which everything important happens TODAY, and the yoga practice expands from the mat into the space of your manifestation in that world which you perceive as the most real!</p><p></p><p></p><p>By the way, there is a small nuance with the time you receive the second practice. If you signed up before 18:00, then you will receive the second practice at the nearest midnight. If you signed up after 18:00, then you will receive the second practice not at the nearest midnight, but at the following midnight. That is, you will have a reserve of time in case you do not manage to complete the practice on the day you signed up for the intensive. <br>  <br><strong>5. Do not force yourself</strong><br> When you buy a monthly membership at a fitness center, you do understand that you do not have to go there every day, right? Moreover, by taking too fast a pace, you may abandon the classes before you even reach the end of the month... The same rule applies to the practices of this intensive - do not be greedy! Practice at a pace convenient for you - every other day, every two days... Of course, it is good to practice every day, but it is even better to understand your long-term tasks and act accordingly. Most likely, your tasks go beyond one month, and you need to act regularly for a long time. I conceived this intensive so that you could go through it month after month as many times as needed until the goal you have set is achieved. This strategy is more effective than going all out for one month and then abandoning the practices or rushing off in another direction.<br>  <br><strong>6. Safety precautions</strong><br> I care about your health and remind you that only you bear responsibility for the adequacy of performing the asanas, pranayamas, and meditations that I will offer to your physical capabilities and mental state. It is important to understand that these are online classes, and I cannot control your state. You may have physical and psychological particularities. Please be attentive to your state. If you feel that some asana that I suggest performing is premature for you, perform it not very deeply, at a compromise level, or replace it altogether with another asana - one that approximately also engages the body but is easier for you.<br>  <br><strong>7. Answers to questions</strong><br> Every week (usually on Saturdays) I hold group online consultations (webinars) in Zoom, at which we communicate, maintain motivation, and discuss difficulties and questions that arise. Before each such consultation, I will send you an email indicating the date and time of its holding, as well as a link to join it. What is interesting to you will surely also be interesting to many others. Therefore, discussing questions at group consultations is most effective. If it happens that the time of the consultation is inconvenient for you, in that case send your questions by email before it begins. I will answer them at the consultation, and I will send you a link to the recording so that you can watch it at a time convenient for you. Consultation recordings are kept for one week.<br> <br>I wish you fruitful practices!</p><p></p><p></p><p>Sergei Zamkovoi</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"de":[{"id":"intensive-strength-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-strength/i3_email-3ec2fc66f836.png","alt":"Интенсив «Сила»","width":"100%","align":"center","naturalWidth":600,"naturalHeight":142,"marginTop":0,"marginBottom":24},{"id":"intensive-strength-1-text","type":"text","html":"<p>Guten Tag, {{name}}!<br> <br>Ich freue mich, dass Sie sich entschieden haben, einen Monat lang gezielt mit den Zuständen von Kraft, Entschlossenheit, Zielstrebigkeit, Passionarität zu arbeiten … Es scheint, dass dies natürliche, jedem zugängliche Zustände sind. In der Gesellschaft wirken jedoch viele sowohl antreibende als auch verbietende Szenarien, die unser Verhalten steuern. Indem Sie Praktiken auf der Yogamatte und im Leben ausführen, nachdenken, Ihre Gedanken und Handlungen korrigieren, können Sie innerhalb eines Monats wichtige Ergebnisse erzielen, die sich sowohl auf der Ebene des Körpers (Gesundung) als auch auf der Ebene des psychologischen Hintergrunds (Zufriedenheit und Glück) zeigen.</p><p></p><p></p><p> In diesem Monat erhalten Sie 30 Praktiken, die auf die Harmonisierung des dritten Chakras ausgerichtet sind. Lesen Sie diesen Brief sorgfältig, damit Sie verstehen, was und wie geschehen wird. <br> <br><strong>1. Das Wesentliche</strong><br> Das ist kein Lehrkurs, sondern ein intensives Praktikum, dessen Kern tägliche Yoga-Praktiken sind. Diese Praktiken habe ich morgens live durchgeführt und dabei die Ausrichtung jeder Praxis mit den planetaren Rhythmen jenes Tages synchronisiert. In diesem Intensivkurs habe ich Videoaufzeichnungen der besten Praktiken gesammelt, die genau auf das erste Chakra ausgerichtet waren (manchmal in Wechselwirkung mit einem anderen Chakra), und sie um verhaltensbezogene (psychologische) Praktiken ergänzt. Daraus ist eine äußerst kraftvolle Ladung für die Harmonisierung des Bereichs Gesundheit entstanden. </p><p></p><p></p><p>Wenn Sie meine Kurse nicht besucht haben und nicht verstehen, was es mit diesem seltsamen „dritten Chakra“ auf sich hat, empfehle ich Ihnen, den Besuch dieses Intensivkurses mit einem Praktikum oder Kurs zu kombinieren, in dem ich Sie allmählich zum Verständnis dessen hinführe, womit wir uns hier beschäftigen. Wichtig ist, mir nicht einfach zu „glauben“, sondern in sich selbst ein Verständnis durch persönliche Erfahrung zu eröffnen – sowohl auf der Yogamatte als auch im Leben. Dann beginnen die Praktiken viel tiefer zu wirken. Andernfalls erhalten wir bloße Körperertüchtigung – denn das ist das grundlegende Verständnis (die Erfahrung) des Yoga, das jeder hat. </p><p></p><p></p><p>Diesen Intensivkurs können Sie durch folgende Lehrprogramme ergänzen:<br> - Praktikum „Monat der Kraft“: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a> </p><p></p><p>- Kurs „Verwirkliche den Traum“: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a> <br>  <br><strong>2. Yoga-Praktiken</strong><br> Die Yoga-Praktiken, die Sie erwarten, unterscheiden sich von dem, was Sie in einem Fitnesscenter antreffen können. Ich gehe davon aus, dass Ihnen das Ergebnis wichtig ist und nicht die Schauspielerei. Wir arbeiten mit inneren Zuständen (das heißt mit Energien) und verbinden Meditation, Pranayama und Asanas in dem Maße, wie es nötig ist, um das gewünschte Ergebnis auf möglichst tiefer Ebene zu erzielen. Die meisten Praktiken beginnen mit einer kurzen Einführung, die notwendig ist, damit Ihr Bewusstsein von der Alltäglichkeit auf die Welle der Praxis umschaltet, Sie in den entsprechenden energetischen Fluss eintreten und Ihr inneres Vorhaben aktiviert wird. Danach folgt die eigentliche Praxis, die an verschiedenen Tagen eine unterschiedliche Dauer und Zusammensetzung der Elemente hat. Nach der Praxis empfehle ich Ihnen, einige Zeit in Meditation zu verweilen, und vielleicht im entstandenen Zustand der Achtsamkeit weiter Asanas auszuführen, die Ihr Körper erbitten wird. Die durchschnittliche Dauer der Praktiken beträgt 30-40 Minuten. Aber manche Praktiken sind kürzer, und manche dauern etwa eine Stunde. Wichtig ist, dass Sie während der Praxis nichts ablenkt und nichts zur Eile treibt. Und noch sehr wichtig – wenn Sie die Praxis begonnen haben, unterbrechen Sie sie nicht bis zu ihrem Ende!!! Jede Praxis ist eine lebendige Geschichte, die Sie einen bestimmten Weg entlangführt. Wenn Sie die Praxis unterbrechen, können Sie in einem weniger ressourcenreichen Zustand landen, als Sie zu Beginn waren. Auch wenn Ihnen diese Worte jetzt wie Mystifikation und leere Esoterik erscheinen mögen, hören Sie auf meine Empfehlungen. <br>  <br><strong>3. Verhaltenspraktiken</strong><br> Jeden Tag werde ich Ihnen im Brief zusammen mit der Yoga-Praxis einen „Tipp des Tages“ schicken. Versuchen Sie, ihn nicht als einen weiteren klugen Gedanken zu betrachten, von der Art, wie Sie sie schon viele Male gehört haben. Ich habe nicht das Ziel, Sie zu überraschen, indem ich etwas sage, das Sie noch nicht gehört haben. Betrachten Sie diesen „Tipp“ als Aufgabe, als Verhaltenspraxis! Führen Sie diese Praxis an diesem Tag aus. Und glauben Sie mir – es wird Ihnen viel interessanter werden, und dieser Intensivkurs wird Ihnen viel mehr Nutzen bringen. Manche solcher Praktiken mögen Ihnen einfacher erscheinen, manche schwieriger. Manche pragmatischer, manche psychologischer. In jedem Fall ist es nicht so, als hätte ich Ihnen vorgeschlagen, 20 Kniebeugen zu machen. Hier arbeiten wir mit Ihren Verhaltens- und psychologischen Mustern. Und der Schlüssel zum Erfolg liegt darin, nicht mit sich zu kämpfen, keine zusätzliche innere Spannung zu erzeugen, sondern wie in den Asanas zu atmen und sich zu entspannen. Deshalb klingt die Praxis sanft – wie ein „Tipp des Tages“ –, damit kein Alarmsignal ausgelöst wird. Lesen Sie ihn, probieren Sie ihn aus, versuchen Sie im Laufe des Tages, diesem Tipp sanft zu folgen oder ihn wenigstens in Erinnerung zu rufen, ihn erneut anzuprobieren und in das Gefühl zurückzukehren, dass Sie ihm folgen. Passen Sie sich an die neuen Zustände an... In manchen Fällen kann sich eine solche Praxis über mehrere Tage oder sogar Monate erstrecken, weil Sie ihre Bedeutung spüren und beginnen, sie auf der Ebene der Gewohnheit in Ihr Leben einzuführen, das heißt, die aktuelle Homöostase des Systems zu korrigieren. Und obwohl ich keine klare Verbindung zwischen den Verhaltenspraktiken und den Yoga-Praktiken, die ich in einem Brief anbiete, angelegt habe, können Sie dennoch jede Yoga-Praxis in dem Zustand ausführen, der entsteht, wenn Sie sich als jemanden wahrnehmen, der meinem Tipp folgt. Das ist jedoch keineswegs zwingend, da jede dieser beiden Praktiken für sich genügt.<br>  <br><strong>4. Zeitplan der Übungen</strong><br> Jeden Tag um Mitternacht wird Ihnen eine neue Praxis freigeschaltet (die vorherige verschwindet dabei, wie der vergangene Tag). Durch diesen Ansatz wird sich bei Ihnen kein Schneeball unerledigter Praktiken ansammeln. Innerhalb von 24 Stunden können Sie jede Ihnen passende Zeit wählen und praktizieren. Ich empfehle Ihnen, morgens zu praktizieren, um den Tag in dem durch die Praxis entstandenen Zustand zu erleben, statt sich schlafen zu legen. Betrachten Sie diesen Intensivkurs nicht als Computer-Illusion, sondern als reales Leben – in dem alles Wichtige HEUTE geschieht und sich die Yoga-Praxis von der Matte auf den Raum Ihrer Manifestation in der Welt ausdehnt, die Sie als die realste wahrnehmen!</p><p></p><p></p><p>Übrigens gibt es eine kleine Besonderheit mit dem Zeitpunkt, zu dem Sie die zweite Praxis erhalten. Wenn Sie sich vor 18:00 Uhr angemeldet haben, erhalten Sie die zweite Praxis in der nächsten Mitternacht. Wenn Sie sich jedoch nach 18:00 Uhr angemeldet haben, erhalten Sie die zweite Praxis nicht in der nächsten, sondern in der darauffolgenden Mitternacht. Das heißt, Sie haben einen Zeitpuffer für den Fall, dass Sie die Praxis am Tag der Anmeldung zum Intensivkurs nicht mehr schaffen. <br>  <br><strong>5. Zwingen Sie sich nicht</strong><br> Wenn Sie ein Monatsabo in einem Fitnesscenter kaufen, verstehen Sie doch, dass Sie nicht unbedingt jeden Tag hingehen müssen? Mehr noch: Wenn Sie ein zu schnelles Tempo anschlagen, können Sie die Übungen aufgeben, ohne sogar das Ende des Monats erreicht zu haben... Für die Praktiken dieses Intensivkurses gilt dieselbe Regel – seien Sie nicht gierig! Praktizieren Sie in einem Ihnen angenehmen Rhythmus – jeden zweiten Tag, jeden dritten... Natürlich ist es gut, jeden Tag zu praktizieren, aber noch besser ist es, seine langfristigen Aufgaben zu verstehen und entsprechend zu handeln. Höchstwahrscheinlich gehen Ihre Aufgaben über einen Monat hinaus, und Sie müssen über einen längeren Zeitraum regelmäßig handeln. Diesen Intensivkurs habe ich so konzipiert, dass Sie ihn Monat für Monat so oft durchlaufen können, wie es nötig ist, bis das von Ihnen gesetzte Ziel erreicht ist. Diese Strategie ist effektiver, als einen Monat lang Vollgas zu geben und dann die Praktiken aufzugeben oder in eine andere Richtung davonzustürmen.<br>  <br><strong>6. Sicherheitstechnik</strong><br> Ich kümmere mich um Ihre Gesundheit und erinnere daran, dass allein Sie die Verantwortung dafür tragen, dass die Ausführung der Asanas, Pranayamas und Meditationen, die ich anbieten werde, Ihren körperlichen Möglichkeiten und Ihrem psychischen Zustand angemessen ist. Wichtig zu verstehen ist, dass dies Online-Kurse sind und ich Ihren Zustand nicht kontrollieren kann. Bei Ihnen können körperliche und psychologische Besonderheiten vorliegen. Bitte seien Sie aufmerksam gegenüber Ihrem Zustand. Wenn Sie spüren, dass eine bestimmte Asana, die ich zur Ausführung anbiete, für Sie verfrüht ist, führen Sie sie nicht sehr tief aus, auf einem Kompromissniveau, oder ersetzen Sie sie ganz durch eine andere Asana – eine, die den Körper ungefähr ebenfalls einbezieht, aber für Sie einfacher ist.<br>  <br><strong>7. Antworten auf Fragen</strong><br> Jede Woche (normalerweise samstags) führe ich in Zoom Gruppen-Online-Konsultationen (Webinare) durch, in denen wir uns austauschen, die Motivation aufrechterhalten und auftretende Schwierigkeiten und Fragen besprechen. Vor jeder solchen Konsultation werde ich Ihnen eine E-Mail mit Angabe von Datum und Uhrzeit ihrer Durchführung sowie einem Link zum Beitreten schicken. Was für Sie interessant ist, wird sicherlich auch für viele andere interessant sein. Deshalb ist die Besprechung von Fragen in den Gruppenkonsultationen am effektivsten. Sollte es geschehen, dass die Zeit der Konsultation für Sie ungünstig ist, senden Sie in diesem Fall Ihre Fragen vor ihrem Beginn per E-Mail. Ich werde sie in der Konsultation beantworten und Ihnen einen Link zur Aufzeichnung schicken, damit Sie sie zu einer Ihnen passenden Zeit ansehen können. Die Aufzeichnungen der Konsultationen werden eine Woche lang gespeichert.<br> <br>Ich wünsche Ihnen fruchtbare Praktiken!</p><p></p><p></p><p>Sergei Zamkovoi</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"fr":[{"id":"intensive-strength-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-strength/i3_email-3ec2fc66f836.png","alt":"Интенсив «Сила»","width":"100%","align":"center","naturalWidth":600,"naturalHeight":142,"marginTop":0,"marginBottom":24},{"id":"intensive-strength-1-text","type":"text","html":"<p>Bonjour, {{name}} !<br> <br>Je suis heureux que vous ayez décidé, pendant un mois, de travailler de manière ciblée avec les états de force, de résolution, de détermination, de passionnalité... En apparence, ce sont des états naturels, accessibles à chacun. Cependant, dans la société agissent de nombreux scénarios, tant incitatifs que prohibitifs, qui gouvernent notre comportement. En accomplissant les pratiques sur le tapis de yoga et dans la vie, en réfléchissant, en corrigeant vos pensées et vos actes, au cours d’un mois vous pouvez obtenir des résultats importants qui se manifesteront tant au niveau du corps (amélioration de la santé) qu’au niveau du fond psychologique (satisfaction et bonheur).</p><p></p><p></p><p> Au cours de ce mois, vous recevrez 30 pratiques visant à harmoniser le troisième chakra. Lisez attentivement cette lettre pour comprendre ce qui va se passer et comment. <br> <br><strong>1. L’essentiel</strong><br> Ce n’est pas un cours d’apprentissage, mais un atelier intensif dont le cœur est constitué de pratiques quotidiennes de yoga. J’ai mené ces pratiques le matin en direct, en synchronisant l’orientation de chaque pratique avec les rythmes planétaires de ce jour-là. Dans cet intensif, j’ai réuni des enregistrements vidéo des meilleures pratiques qui étaient précisément destinées au premier chakra (parfois en interaction avec un autre chakra), et je les ai complétées par des pratiques comportementales (psychologiques). Il en est résulté une charge extrêmement puissante pour harmoniser le domaine de la santé. </p><p></p><p></p><p>Si vous n’avez pas suivi mes cours et ne comprenez pas ce que vient faire ici une quelconque « troisième chakra », je vous recommande de combiner le passage de cet intensif avec un atelier pratique ou un cours dans lequel j’amène progressivement à comprendre ce que nous faisons ici. Il est important non pas simplement de « me croire », mais d’ouvrir en vous la compréhension par l’expérience personnelle – tant sur le tapis de yoga que dans la vie. Alors les pratiques commencent à agir beaucoup plus profondément. Sinon, nous obtenons de la culture physique – car c’est la compréhension (l’expérience) de base du yoga que chacun possède.</p><p></p><p></p><p>Vous pouvez compléter cet intensif avec les programmes d’apprentissage suivants :<br> - Atelier pratique « Un mois de force » : <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a> </p><p></p><p>- Cours « Réalise ton rêve » : <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a> <br>  <br><strong>2. Pratiques de yoga</strong><br> Les pratiques de yoga qui vous attendent diffèrent de ce que vous pouvez rencontrer dans un centre de fitness. Je suppose que le résultat vous importe, et non le jeu d’acteur. Nous travaillons avec les états intérieurs (c’est-à-dire avec les énergies), en unissant la méditation, le pranayama et les asanas dans la mesure nécessaire pour obtenir le résultat souhaité au niveau le plus profond possible. La plupart des pratiques commencent par une courte introduction, nécessaire pour que votre conscience passe du quotidien à la vague de la pratique, que vous entriez dans le flux énergétique correspondant et que votre intention intérieure s’active. Vient ensuite la pratique elle-même, qui selon les jours a une durée et une composition d’éléments différentes. Après la pratique, je vous recommande de rester quelque temps en méditation, et peut-être, dans l’état de conscience apparu, de continuer à exécuter les asanas que votre corps demandera. La durée moyenne des pratiques est de 30-40 minutes. Mais certaines pratiques sont plus courtes, et d’autres durent environ une heure. Il est important que pendant la pratique rien ne vous distraie ni ne vous presse. Et encore très important - une fois la pratique commencée, ne l’interrompez pas avant sa fin!!! Chaque pratique est une histoire vivante qui vous conduit sur un chemin déterminé. En interrompant la pratique, vous pouvez vous retrouver dans un état moins pourvu en ressources que celui dans lequel vous étiez au début. Même si maintenant ces mots vous semblent une mystification et de l’ésotérisme vide, écoutez mes recommandations. <br>  <br><strong>3. Pratiques comportementales</strong><br> Chaque jour, dans l’e-mail, avec la pratique de yoga, je vous enverrai un « conseil du jour ». Essayez de le percevoir non pas comme une pensée intelligente de plus, semblable à celles que vous avez déjà entendues bien des fois. Je n’ai pas pour but de vous surprendre en disant ce que vous n’avez encore jamais entendu. Percevez ce « conseil » comme une tâche, comme une pratique comportementale ! Accomplissez cette pratique ce jour-là. Et croyez-moi - cela vous paraîtra beaucoup plus intéressant, et cet intensif vous apportera beaucoup plus de bienfaits. Certaines de ces pratiques peuvent vous sembler plus simples, d’autres plus difficiles. Certaines plus pragmatiques, d’autres plus psychologiques. Dans tous les cas, ce n’est pas comme si je vous proposais de faire 20 squats. Ici, nous travaillons avec vos schémas comportementaux et psychologiques. Et la clé du succès est de ne pas lutter contre vous-même, de ne pas provoquer une tension intérieure supplémentaire, mais, comme dans les asanas, de respirer et de vous détendre. C’est pourquoi la pratique se présente doucement - comme un « conseil du jour » - afin de ne pas déclencher de signal d’alarme. Lisez-le, essayez-le, tentez pendant la journée de suivre doucement ce conseil ou du moins de vous en souvenir, en l’essayant à nouveau et en revenant à la sensation que vous le suivez. Adaptez-vous aux nouveaux états... Dans certains cas, une telle pratique peut s’étendre sur plusieurs jours ou même plusieurs mois, parce que vous en ressentirez l’importance et commencerez à l’intégrer dans votre vie au niveau de l’habitude, c’est-à-dire en corrigeant l’homéostasie actuelle du système. Et, bien que je n’aie pas établi de lien précis entre les pratiques comportementales et les pratiques de yoga que je propose dans un même e-mail, vous pouvez néanmoins accomplir chaque pratique de yoga dans l’état apparu lorsque vous vous percevez comme suivant mon conseil. Cependant, ce n’est pas du tout obligatoire, car chacune de ces deux pratiques est autosuffisante.<br>  <br><strong>4. Horaire des séances</strong><br> Chaque jour à minuit, une nouvelle pratique s’ouvrira pour vous (la précédente disparaîtra alors, comme le jour précédent). Grâce à cette approche, les pratiques non accomplies ne s’accumuleront pas en boule de neige. Pendant les vingt-quatre heures, vous pouvez choisir n’importe quel moment qui vous convient et pratiquer. Je vous recommande de pratiquer le matin, afin de vivre la journée dans l’état obtenu grâce à la pratique, et non d’aller vous coucher. Percevez cet intensif non pas comme une illusion informatique, mais comme la vie réelle - dans laquelle tout ce qui est important se produit AUJOURD’HUI, et la pratique du yoga s’étend du tapis à l’espace de votre manifestation dans ce monde que vous percevez comme le plus réel !</p><p></p><p></p><p>À propos, il y a une petite nuance concernant le moment où vous recevez la deuxième pratique. Si votre inscription a eu lieu avant 18:00, vous recevrez la deuxième pratique à la prochaine minuit. Si en revanche votre inscription a eu lieu après 18:00, vous recevrez la deuxième pratique non pas à la prochaine minuit, mais à la minuit suivante. Autrement dit, vous aurez une marge de temps au cas où vous n’auriez pas le temps d’accomplir la pratique le jour de l’inscription à l’intensif. <br>  <br><strong>5. Ne vous forcez pas</strong><br> Lorsque vous achetez un abonnement mensuel dans un centre de fitness, vous comprenez bien que vous n’êtes pas obligé d’y aller chaque jour ? De plus, en prenant un rythme trop rapide, vous risquez d’abandonner les séances avant même d’arriver à la fin du mois... En ce qui concerne les pratiques de cet intensif, la même règle s’applique - ne soyez pas gourmand ! Pratiquez à un rythme qui vous convient - tous les deux jours, tous les trois jours... Bien sûr, il est bon de pratiquer chaque jour, mais il est encore mieux de comprendre vos tâches à long terme et d’agir en conséquence. Très probablement, vos tâches dépassent le cadre d’un mois, et vous devez agir régulièrement pendant une longue période. J’ai conçu cet intensif de manière à ce que vous puissiez le suivre mois après mois autant de fois que nécessaire, jusqu’à ce que l’objectif que vous vous êtes fixé soit atteint. Cette stratégie est plus efficace que de se donner à fond pendant un mois, puis d’abandonner les pratiques ou de partir dans une autre direction.<br>  <br><strong>6. Consignes de sécurité</strong><br> Je me soucie de votre santé et je vous rappelle que c’est vous qui portez la responsabilité de l’adéquation de l’exécution des asanas, des pranayamas et des méditations que je proposerai à vos possibilités physiques et à votre état psychique. Il est important de comprendre qu’il s’agit de séances en ligne et que je ne peux pas contrôler votre état. Vous pouvez avoir des particularités physiques et psychologiques. Veuillez être attentif à votre état. Si vous sentez qu’une asana que je propose d’exécuter est prématurée pour vous, exécutez-la pas très profondément, à un niveau de compromis, ou remplacez-la entièrement par une autre asana - telle qui sollicite à peu près autant le corps, mais qui est plus simple pour vous.<br>  <br><strong>7. Réponses aux questions</strong><br> Chaque semaine (généralement le samedi), j’anime sur Zoom des consultations en ligne de groupe (webinaires), pendant lesquelles nous échangeons, maintenons la motivation, discutons des difficultés et des questions qui surviennent. Avant chacune de ces consultations, je vous enverrai un e-mail indiquant la date et l’heure de sa tenue, ainsi qu’un lien pour la rejoindre. Ce qui vous intéresse intéressera sûrement aussi beaucoup d’autres personnes. C’est pourquoi il est plus efficace de discuter des questions lors des consultations de groupe. S’il arrive que l’heure de la consultation ne vous convienne pas, dans ce cas envoyez vos questions par e-mail avant son début. Je répondrai à ces questions lors de la consultation, et je vous enverrai un lien vers l’enregistrement afin que vous puissiez le regarder au moment qui vous convient. Les enregistrements des consultations sont conservés pendant une semaine.<br> <br>Je vous souhaite des pratiques fructueuses !</p><p></p><p></p><p>Sergei Zamkovoi</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"it":[{"id":"intensive-strength-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-strength/i3_email-3ec2fc66f836.png","alt":"Интенсив «Сила»","width":"100%","align":"center","naturalWidth":600,"naturalHeight":142,"marginTop":0,"marginBottom":24},{"id":"intensive-strength-1-text","type":"text","html":"<p>Salve, {{name}}!<br> <br>Sono contento che abbiate deciso di lavorare intenzionalmente per un mese con gli stati di forza, determinazione, orientamento agli obiettivi, passionalità... In apparenza sembrano stati naturali, accessibili a chiunque. Tuttavia, nella società agiscono molti copioni, sia incentivanti sia inibitori, che governano il nostro comportamento. Eseguendo pratiche sul tappetino yoga e nella vita, riflettendo, correggendo i propri pensieri e le proprie azioni, nel corso di un mese si possono ottenere risultati importanti, che si manifesteranno sia a livello del corpo (miglioramento della salute), sia a livello dello sfondo psicologico (soddisfazione e felicità).</p><p></p><p></p><p> In questo mese riceverete 30 pratiche volte ad armonizzare il terzo chakra. Leggete attentamente questa lettera per capire cosa e come accadrà. <br> <br><strong>1. L''essenza stessa</strong><br> Non è un corso didattico, ma un praticum intensivo, il cui nucleo sono le pratiche yoga quotidiane. Queste pratiche le ho condotte al mattino in diretta, sincronizzando la direzione di ogni pratica con i ritmi planetari di quel giorno. In questo intensivo ho raccolto le videoregistrazioni delle migliori pratiche, che erano dirette proprio al primo chakra (a volte in interazione con qualche altro chakra), e le ho integrate con pratiche comportamentali (psicologiche). Il risultato è stato una carica potentissima per l''armonizzazione dell''ambito della salute. </p><p></p><p></p><p>Se non avete seguito i miei corsi e non capite cosa c''entri qui una qualche «terza chakra», vi consiglio di abbinare la partecipazione a questo intensivo a un praticum o a un corso in cui vi accompagno gradualmente alla comprensione di ciò di cui ci occupiamo qui. È importante non semplicemente «credermi», ma aprire in voi la comprensione attraverso l''esperienza personale - sia sul tappetino yoga sia nella vita. Allora le pratiche iniziano a funzionare molto più in profondità. Altrimenti otteniamo educazione fisica - poiché questa è la comprensione (esperienza) di base dello yoga che ognuno possiede. </p><p></p><p></p><p>Potete integrare questo intensivo con i seguenti programmi di studio:<br> - Praticum «Mese della forza»: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a> </p><p></p><p>- Corso «Realizza il sogno»: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a> <br>  <br><strong>2. Pratiche yoga</strong><br> Le pratiche yoga che vi attendono sono diverse da ciò che potete trovare in un centro fitness. Presumo che per voi conti il risultato, non la messa in scena. Lavoriamo con gli stati interiori (cioè con le energie), unendo meditazione, pranayama e asana nella misura necessaria per ottenere il risultato desiderato al livello più profondo possibile. La maggior parte delle pratiche inizia con una breve introduzione, necessaria affinché la vostra coscienza passi dalla quotidianità all''onda della pratica, entriate nel corrispondente flusso energetico e si attivi la vostra intenzione interiore. Segue poi la pratica stessa, che nei diversi giorni ha durata e composizione di elementi diverse. Dopo la pratica vi raccomando di restare per un po'' in meditazione, e magari, nello stato di consapevolezza che è emerso, di continuare a eseguire le asana che il vostro corpo chiederà. La durata media delle pratiche è di 30-40 minuti. Ma alcune pratiche sono più brevi, e alcune durano circa un''ora. È importante che durante la pratica nulla vi distragga e vi metta fretta. E ancora molto importante - una volta iniziata la pratica, non interrompetela prima della fine!!! Ogni pratica è una storia viva, che vi conduce lungo un determinato percorso. Interrompendo la pratica, potete ritrovarvi in uno stato meno ricco di risorse di quello in cui eravate all''inizio. Anche se ora queste parole vi sembrano una mistificazione e vuoto esoterismo, ascoltate le mie raccomandazioni. <br>  <br><strong>3. Pratiche comportamentali</strong><br> Ogni giorno, nella lettera insieme alla pratica yoga, vi invierò il «consiglio del giorno». Provate a percepirlo non come un altro pensiero intelligente, simile al quale ne avete già sentiti molti. Non ho l''obiettivo di sorprendervi dicendo qualcosa che non avete ancora sentito. Percepite questo «consiglio» come un compito, come una pratica comportamentale! Eseguite questa pratica nel giorno dato. E credetemi - vi risulterà molto più interessante, e questo intensivo vi porterà molto più beneficio. Alcune di queste pratiche possono sembrarvi più semplici, alcune più difficili. Alcune più pragmatiche, alcune più psicologiche. In ogni caso, non è come se vi avessi proposto di fare 20 squat. Qui lavoriamo con i vostri schemi comportamentali e psicologici. E la chiave del successo sta nel non combattere con voi stessi, nel non provocare ulteriore tensione interiore, ma, come nelle asana, respirare e rilassarvi. Perciò la pratica suona morbida - come «consiglio del giorno» - per non attivare un segnale d''allarme. Leggete, provate su di voi, provate durante la giornata a seguire dolcemente questo consiglio o almeno a ricordarlo, provandolo di nuovo e tornando alla sensazione che lo state seguendo. Adattatevi ai nuovi stati... In alcuni casi una sola pratica del genere può protrarsi per diversi giorni o addirittura mesi, perché ne sentirete l''importanza e inizierete a introdurla nella vostra vita a livello di abitudine, cioè correggendo l''attuale omeostasi del sistema. E, sebbene io non abbia previsto un legame preciso tra le pratiche comportamentali e le pratiche yoga che propongo in una stessa lettera, potete comunque eseguire ogni pratica yoga nello stato che emerge quando percepite voi stessi come seguaci del mio consiglio. Tuttavia, questo non è affatto obbligatorio, poiché ciascuna di queste due pratiche è autosufficiente.<br>  <br><strong>4. Orario delle lezioni</strong><br> Ogni giorno a mezzanotte vi si aprirà una nuova pratica (quella precedente scomparirà, come il giorno passato). Grazie a questo approccio, non si accumulerà una palla di neve di pratiche non eseguite. Nell''arco delle ventiquattro ore potete scegliere qualsiasi momento conveniente per voi e fare pratica. Vi raccomando di praticare al mattino, per vivere la giornata nello stato ottenuto grazie alla pratica, e non andare a dormire. Percepite questo intensivo non come un''illusione informatica, ma come vita reale - in cui tutto ciò che è importante accade OGGI, e la pratica yoga si espande dal tappetino allo spazio della vostra manifestazione in quel mondo che percepite come il più reale!</p><p></p><p></p><p>A proposito, c''è una piccola sfumatura riguardo al momento in cui riceverete la seconda pratica. Se vi siete iscritti prima delle 18:00, riceverete la seconda pratica alla mezzanotte più vicina. Se invece vi siete iscritti dopo le 18:00, riceverete la seconda pratica non alla mezzanotte più vicina, ma a quella successiva. Cioè avrete un margine di tempo nel caso non riusciate a completare la pratica nel giorno dell''iscrizione all''intensivo. <br>  <br><strong>5. Non fatevi violenza</strong><br> Quando acquistate un abbonamento mensile in un centro fitness, capite bene che non dovete per forza andarci ogni giorno? Inoltre, prendendo un ritmo troppo veloce, potete abbandonare le lezioni senza nemmeno arrivare alla fine del mese... Riguardo alle pratiche di questo intensivo vale la stessa regola - non siate avidi! Praticate al ritmo che vi è comodo - a giorni alterni, ogni due... Certo, è bene praticare ogni giorno, ma ancora meglio è capire i propri compiti a lungo termine e agire di conseguenza. Molto probabilmente i vostri compiti vanno oltre un mese, e avete bisogno di agire regolarmente per lungo tempo. Ho concepito questo intensivo in modo che possiate seguirlo mese dopo mese tutte le volte che serve, finché l''obiettivo che vi siete posti non sarà raggiunto. Questa strategia è più efficace che darci dentro per un mese e poi abbandonare le pratiche o lanciarsi in un''altra direzione.<br>  <br><strong>6. Tecnica di sicurezza</strong><br> Mi prendo cura della vostra salute e vi ricordo che solo voi siete responsabili dell''adeguatezza dell''esecuzione delle asana, dei pranayama e delle meditazioni che vi proporrò rispetto alle vostre possibilità fisiche e al vostro stato psichico. È importante capire che queste sono lezioni online e io non posso controllare il vostro stato. Potete avere particolarità fisiche e psicologiche. Per favore, siate attenti al vostro stato. Se sentite che qualche asana che vi propongo di eseguire è per voi prematura, eseguitela non molto profondamente, a un livello di compromesso, oppure sostituitela del tutto con un''altra asana - tale che coinvolga approssimativamente allo stesso modo il corpo, ma sia più semplice per voi.<br>  <br><strong>7. Risposte alle domande</strong><br> Ogni settimana (di solito il sabato) tengo su Zoom consultazioni online di gruppo (webinar), durante le quali comunichiamo, sosteniamo la motivazione, discutiamo le difficoltà e le domande che emergono. Prima di ciascuna di queste consultazioni vi invierò un''email con l''indicazione della data e dell''ora in cui si svolgerà, nonché il link per parteciparvi. Ciò che interessa a voi sarà sicuramente interessante anche per molti altri. Perciò, discutere le domande durante le consultazioni di gruppo è più efficace. Se accadesse che l''orario della consultazione non vi sia comodo, in questo caso inviate le vostre domande via email prima del suo inizio. Risponderò loro durante la consultazione, e vi invierò il link alla registrazione, così potrete guardarla nel momento per voi più comodo. Le registrazioni delle consultazioni vengono conservate per una settimana.<br> <br>Vi auguro pratiche fruttuose!</p><p></p><p></p><p>Sergei Zamkovoi</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"es":[{"id":"intensive-strength-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-strength/i3_email-3ec2fc66f836.png","alt":"Интенсив «Сила»","width":"100%","align":"center","naturalWidth":600,"naturalHeight":142,"marginTop":0,"marginBottom":24},{"id":"intensive-strength-1-text","type":"text","html":"<p>Hola, {{name}}!<br> <br>Me alegra que hayan decidido trabajar durante un mes de forma intencionada con los estados de fuerza, determinación, orientación a objetivos, pasión... Parecería que son estados naturales, accesibles para cualquiera. Sin embargo, en la sociedad actúan multitud de guiones tanto incentivadores como prohibitivos que gobiernan nuestra conducta. Al realizar las prácticas en la esterilla de yoga y en la vida, reflexionando, corrigiendo sus pensamientos y acciones, a lo largo de un mes se pueden obtener resultados importantes que se manifestarán tanto a nivel del cuerpo (sanación) como a nivel del fondo psicológico (satisfacción y felicidad).</p><p></p><p></p><p> Durante este mes recibirán 30 prácticas dirigidas a armonizar el tercer chakra. Lean atentamente esta carta para comprender qué y cómo sucederá. <br> <br><strong>1. La esencia misma</strong><br> Esto no es un curso de formación, sino un taller intensivo cuyo núcleo son las prácticas diarias de yoga. Estas prácticas las realizaba por las mañanas en directo, sincronizando la dirección de cada práctica con los ritmos planetarios de ese día. En este intensivo he reunido grabaciones de vídeo de las mejores prácticas, que estaban dirigidas precisamente al primer chakra (a veces en interacción con algún otro chakra), y las he complementado con prácticas conductuales (psicológicas). Como resultado, se ha obtenido una carga poderosísima para armonizar el ámbito de la salud. </p><p></p><p></p><p>Si no han tomado mis cursos y no entienden qué tiene que ver aquí una cierta «tercera chakra», les recomiendo combinar la realización de este intensivo con un taller práctico o un curso en el que los conduzco suavemente hacia la comprensión de aquello de lo que nos ocupamos aquí. Es importante no simplemente «creerme», sino abrir en ustedes la comprensión a través de la experiencia personal, tanto en la esterilla de yoga como en la vida. Entonces las prácticas empiezan a funcionar mucho más profundamente. De lo contrario, obtenemos educación física, ya que esta es la comprensión básica (experiencia) del yoga que cada uno tiene. </p><p></p><p></p><p>Pueden complementar este intensivo con los siguientes programas de formación:<br> - Taller práctico «Mes de la fuerza»: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a> </p><p></p><p>- Curso «Haz realidad el sueño»: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a> <br>  <br><strong>2. Prácticas de yoga</strong><br> Las prácticas de yoga que le esperan se diferencian de lo que puede encontrar en un centro de fitness. Supongo que para usted es importante el resultado, y no el teatro. Trabajamos con estados internos (es decir, con energías), uniendo meditación, pranayama y asanas en la medida necesaria para obtener el resultado deseado al nivel más profundo posible. La mayoría de las prácticas comienzan con una breve introducción, necesaria para que su conciencia cambie de lo cotidiano a la onda de la práctica, entre en el flujo energético correspondiente y se active su intención interna. Después sigue la práctica en sí, que en distintos días tiene distinta duración y composición de elementos. Después de la práctica, le recomiendo permanecer un tiempo en meditación y, tal vez, en el estado de conciencia que haya surgido, continuar realizando las asanas que su cuerpo le pida. La duración media de las prácticas es de 30-40 minutos. Pero algunas prácticas son más cortas y otras duran cerca de una hora. Es importante que durante la práctica nada le distraiga ni le apresure. Y además es muy importante: una vez comenzada la práctica, ¡no la interrumpa hasta que termine!!! Cada práctica es una historia viva que le conduce por un camino determinado. Si interrumpe la práctica, puede encontrarse en un estado con menos recursos que aquel en el que estaba al comenzarla. Aunque ahora estas palabras le parezcan una mistificación y esoterismo vacío, haga caso a mis recomendaciones. <br>  <br><strong>3. Prácticas conductuales</strong><br> Cada día, en la carta, junto con la práctica de yoga, le enviaré el «consejo del día». Intente percibirlo no como una idea inteligente más, de las cuales ya ha oído muchas. No tengo el objetivo de sorprenderle diciendo algo que aún no haya oído. Perciba este «consejo» como una tarea, ¡como una práctica conductual! Realice esta práctica en el día indicado. Y créame: se sentirá mucho más interesado, y este intensivo le aportará mucho más beneficio. Algunas de estas prácticas pueden parecerle más fáciles, otras más difíciles. Algunas más pragmáticas, otras más psicológicas. En cualquier caso, no es como si le propusiera hacer 20 sentadillas. Aquí trabajamos con sus patrones conductuales y psicológicos. Y la clave del éxito está en no luchar contra uno mismo, no generar una tensión interna adicional, sino, como en las asanas, respirar y relajarse. Por eso la práctica suena suave, como «consejo del día», para no activar una señal de alarma. Léalo, pruébeselo, intente durante el día seguir suavemente este consejo o al menos recordarlo, probándoselo de nuevo y regresando a la sensación de que lo sigue. Adáptese a los nuevos estados... En algunos casos, una sola práctica así puede extenderse durante varios días o incluso meses, porque sentirá su importancia y comenzará a incorporarla a su vida a nivel de hábito, es decir, corrigiendo la homeostasis actual del sistema. Y, aunque no establecí una conexión clara entre las prácticas conductuales y las prácticas de yoga que propongo en una misma carta, aun así puede realizar cada práctica de yoga en el estado que surja cuando se percibe a sí mismo siguiendo mi consejo. Sin embargo, esto no es en absoluto obligatorio, ya que cada una de estas dos prácticas es autosuficiente.<br>  <br><strong>4. Horario de las clases</strong><br> Cada día, a medianoche, se le abrirá una nueva práctica (la anterior desaparecerá, como el día anterior). Gracias a este enfoque, no se le irá acumulando una bola de nieve de prácticas sin hacer. A lo largo del día puede elegir el momento que más le convenga y practicar. Le recomiendo practicar por la mañana, para vivir el día en el estado obtenido como resultado de la práctica, y no irse a dormir. Perciba este intensivo no como una ilusión informática, sino como la vida real, en la que todo lo importante ocurre HOY, y la práctica de yoga se expande desde la esterilla al espacio de su manifestación en el mundo que usted percibe como el más real.</p><p></p><p></p><p>Por cierto, hay un pequeño matiz con la hora de recepción de la segunda práctica. Si se inscribió antes de las 18:00, recibirá la segunda práctica en la próxima medianoche. Si se inscribió después de las 18:00, recibirá la segunda práctica no en la próxima medianoche, sino en la siguiente. Es decir, tendrá un margen de tiempo por si no logra realizar la práctica el día de la inscripción al intensivo. <br>  <br><strong>5. No se fuerce</strong><br> Cuando compra un abono mensual en un centro de fitness, entiende que no es obligatorio ir todos los días, ¿verdad? Además, si adopta un ritmo demasiado rápido, puede abandonar las clases sin haber llegado ni siquiera a fin de mes... Con las prácticas de este intensivo rige la misma regla: ¡no sea codicioso! Practique a un ritmo que le resulte cómodo: un día sí y otro no, cada dos días... Claro que es bueno practicar todos los días, pero aún mejor es comprender sus objetivos a largo plazo y actuar en consecuencia. Lo más probable es que sus objetivos vayan más allá de un mes, y necesite actuar con regularidad durante un tiempo prolongado. Concebí este intensivo para que pueda recorrerlo mes tras mes tantas veces como sea necesario, hasta que se alcance el objetivo que se ha propuesto. Esta estrategia es más eficaz que entregarse a tope durante un mes y luego abandonar las prácticas o lanzarse en otra dirección.<br>  <br><strong>6. Técnica de seguridad</strong><br> Me preocupo por su salud y le recuerdo que solo usted es responsable de la adecuación de la ejecución de las asanas, pranayamas y meditaciones que le propondré a sus posibilidades físicas y a su estado psíquico. Es importante comprender que son clases en línea, y no puedo controlar su estado. Usted puede tener particularidades físicas y psicológicas. Por favor, sea atento a su estado. Si siente que alguna asana que le propongo realizar es prematura para usted, ejecútela no muy profundamente, en un nivel de compromiso, o sustitúyala por completo por otra asana, una que incluya el cuerpo aproximadamente de la misma manera pero que le resulte más sencilla.<br>  <br><strong>7. Respuestas a las preguntas</strong><br> Cada semana (normalmente los sábados) realizo en Zoom consultas grupales en línea (webinars), en las que conversamos, mantenemos la motivación y discutimos las dificultades y preguntas que surgen. Antes de cada una de estas consultas le enviaré una carta con la fecha y la hora de su realización, así como un enlace para unirse a ella. Lo que es interesante para usted seguramente también lo será para muchas otras personas. Por eso, la discusión de preguntas en las consultas grupales es lo más eficaz. Si ocurre que la hora de la consulta le resulta inconveniente, en ese caso envíe sus preguntas por correo electrónico antes de su comienzo. Las responderé en la consulta y le enviaré un enlace a la grabación para que pueda verla en el momento que le resulte cómodo. Las grabaciones de las consultas se conservan durante una semana.<br> <br>¡Le deseo prácticas fructíferas!</p><p></p><p></p><p>Sergei Zamkovoi</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"pt":[{"id":"intensive-strength-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-strength/i3_email-3ec2fc66f836.png","alt":"Интенсив «Сила»","width":"100%","align":"center","naturalWidth":600,"naturalHeight":142,"marginTop":0,"marginBottom":24},{"id":"intensive-strength-1-text","type":"text","html":"<p>Olá, {{name}}!<br> <br>Fico feliz que você tenha se decidido, ao longo de um mês, a trabalhar intencionalmente com os estados de força, determinação, foco em objetivos, passionalidade... Parece que são estados naturais, acessíveis a todos. No entanto, na sociedade atuam muitos cenários tanto incentivadores quanto proibitivos, que governam nosso comportamento. Executando práticas no tapete de yoga e na vida, refletindo, corrigindo seus pensamentos e atos, ao longo de um mês é possível obter resultados importantes, que se manifestarão tanto no nível do corpo (melhora da saúde) quanto no nível do fundo psicológico (satisfação e felicidade).</p><p></p><p></p><p> Durante este mês você receberá 30 práticas voltadas à harmonização do terceiro chakra. Leia atentamente esta carta para entender o que e como acontecerá. <br> <br><strong>1. A própria essência</strong><br> Este não é um curso de estudo, mas um praticum intensivo, cujo núcleo são as práticas diárias de yoga. Eu conduzia essas práticas pela manhã ao vivo, sincronizando a direção de cada prática com os ritmos planetários daquele dia. Neste intensivo, reuni gravações em vídeo das melhores práticas que eram direcionadas justamente ao primeiro chakra (às vezes em interação com algum outro chakra), e as complementei com práticas comportamentais (psicológicas). O resultado foi uma carga poderosíssima para harmonizar a esfera da saúde. </p><p></p><p></p><p>Se você não fez meus cursos e não entende o que tem a ver com isso esse tal “terceiro chakra”, recomendo que você combine a realização deste intensivo com um workshop ou curso no qual eu conduzo gradualmente ao entendimento do que estamos fazendo aqui. É importante não apenas “acreditar” em mim, mas abrir em si mesmo a compreensão por meio da experiência pessoal - tanto no tapete de yoga quanto na vida. Então as práticas começam a funcionar muito mais profundamente. Caso contrário, obtemos educação física - pois esta é a compreensão (experiência) básica do yoga que cada um tem. </p><p></p><p></p><p>Você pode complementar este intensivo com os seguintes programas de estudo:<br> - Workshop «Mês da força»: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a> </p><p></p><p>- Curso «Realize o sonho»: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a> <br>  <br><strong>2. Práticas de yoga</strong><br> As práticas de yoga que você terá pela frente diferem daquilo que você pode encontrar em uma academia de ginástica. Presumo que para você o resultado é importante, e não a teatralidade. Trabalhamos com estados internos (ou seja, com energias), unindo meditação, pranayama e asanas na medida necessária para obter o resultado desejado no nível mais profundo possível. A maioria das práticas começa com uma pequena introdução, necessária para que sua consciência se desligue da cotidianidade e entre na onda da prática, você entre no fluxo energético correspondente e sua intenção interna se ative. Em seguida vem a própria prática, que em dias diferentes tem duração e composição de elementos diferentes. Depois da prática, recomendo que você fique algum tempo em meditação e, talvez, no estado de consciência que surgir, continue executando as asanas que seu corpo pedir. A duração média das práticas é de 30 a 40 minutos. Mas algumas práticas são mais curtas, e algumas duram cerca de uma hora. É importante que durante a prática nada o distraia nem o apresse. E é ainda muito importante - tendo começado a prática, não a interrompa até o final!!! Cada prática é uma história viva que o conduz por um determinado caminho. Se interromper a prática, você pode acabar em um estado com menos recursos do que aquele em que estava no início dela. Mesmo que agora estas palavras lhe pareçam mistificação e esoterismo vazio, escute minhas recomendações. <br>  <br><strong>3. Práticas comportamentais</strong><br> Todos os dias, no e-mail, junto com a prática de yoga, enviarei a você o «conselho do dia». Tente não percebê-lo como mais um pensamento inteligente, semelhante aos que você já ouviu muitas vezes. Não tenho o objetivo de surpreendê-lo dizendo algo que você ainda não ouviu. Perceba esse «conselho» como uma tarefa, como uma prática comportamental! Execute essa prática no dia em questão. E acredite - vai se tornar muito mais interessante para você, e este intensivo lhe trará muito mais benefício. Algumas dessas práticas podem parecer-lhe mais simples, outras mais difíceis. Algumas mais pragmáticas, outras mais psicológicas. Em qualquer caso, não é como se eu tivesse proposto a você agachar 20 vezes. Aqui trabalhamos com seus padrões comportamentais e psicológicos. E a chave do sucesso está em não lutar consigo mesmo, não provocar tensão interna adicional, mas, como nas asanas, respirar e relaxar. Por isso a prática soa suave - como «conselho do dia» - para não provocar o sinal de alarme. Leia, experimente, tente ao longo do dia seguir suavemente esse conselho ou ao menos lembrar dele, experimentando-o de novo e retornando à sensação de que o está seguindo. Adapte-se aos novos estados... Em alguns casos, uma dessas práticas pode se estender por vários dias ou até meses, porque você sentirá sua importância e começará a introduzi-la em sua vida no nível do hábito, ou seja, corrigindo a homeostase atual do sistema. E, embora eu não tenha estabelecido uma ligação clara entre as práticas comportamentais e as práticas de yoga que proponho em um mesmo e-mail, ainda assim você pode executar cada prática de yoga no estado que surgir quando você se percebe seguindo meu conselho. No entanto, isso não é de modo algum obrigatório, pois cada uma dessas duas práticas é autossuficiente.<br>  <br><strong>4. Horário das aulas</strong><br> Todos os dias, à meia-noite, uma nova prática será aberta para você (a anterior desaparecerá, como o dia anterior). Graças a essa abordagem, não se acumulará em você uma bola de neve de práticas não realizadas. Ao longo do dia, você pode escolher o horário que lhe for conveniente e praticar. Recomendo que você pratique pela manhã, para viver o dia no estado obtido como resultado da prática, e não para ir dormir. Perceba este intensivo não como uma ilusão de computador, mas como a vida real - na qual tudo o que é importante acontece HOJE, e a prática de yoga se expande do tapete para o espaço da sua manifestação naquele mundo que você percebe como o mais real!</p><p></p><p></p><p>A propósito, há um pequeno detalhe com o horário de recebimento da segunda prática. Se você se inscreveu antes das 18:00, receberá a segunda prática na próxima meia-noite. Mas se se inscreveu depois das 18:00, receberá a segunda prática não na próxima meia-noite, mas na meia-noite seguinte. Ou seja, você terá uma reserva de tempo caso não consiga realizar a prática no dia da inscrição no intensivo. <br>  <br><strong>5. Não se force</strong><br> Quando você compra uma mensalidade em uma academia, você entende que não precisa ir lá todos os dias, certo? Mais do que isso, se pegar um ritmo rápido demais, você pode abandonar os treinos antes mesmo do fim do mês... Em relação às práticas deste intensivo, vale a mesma regra - não seja ganancioso! Pratique no ritmo que lhe for conveniente - um dia sim, dois não... Claro, é bom praticar todos os dias, mas ainda melhor é entender suas tarefas de longo prazo e agir de acordo. Muito provavelmente, suas tarefas vão além de um mês, e você precisa agir regularmente por um longo tempo. Concebi este intensivo de modo que você possa percorrê-lo mês após mês, quantas vezes for necessário, até que o objetivo que você estabeleceu seja alcançado. Essa estratégia é mais eficaz do que se entregar a fundo por um mês e depois abandonar as práticas ou partir para outra direção.<br>  <br><strong>6. Técnica de segurança</strong><br> Eu me preocupo com sua saúde e lembro que somente você é responsável pela adequação da execução das asanas, pranayamas e meditações que eu proporei às suas possibilidades físicas e ao seu estado psíquico. É importante entender que estas são aulas on-line, e eu não posso controlar seu estado. Você pode ter particularidades físicas e psicológicas. Por favor, esteja atento ao seu estado. Se você sentir que alguma asana que proponho executar é prematura para você, execute-a não muito profundamente, em um nível de meio-termo, ou substitua-a totalmente por outra asana - que envolva o corpo de modo aproximadamente semelhante, mas seja mais simples para você.<br>  <br><strong>7. Respostas às perguntas</strong><br> Toda semana (normalmente aos sábados) realizo no Zoom consultorias on-line em grupo (webinars), nas quais conversamos, mantemos a motivação, discutimos as dificuldades e dúvidas que surgem. Antes de cada consultoria dessas, enviarei a você um e-mail com a data e o horário de sua realização, bem como o link para se juntar a ela. O que é interessante para você certamente também será interessante para muitas outras pessoas. Por isso, discutir as questões nas consultorias em grupo é o mais eficaz. Se acontecer de o horário da consultoria ser inconveniente para você, nesse caso envie suas perguntas por e-mail antes de ela começar. Eu responderei a elas na consultoria e enviarei a você o link da gravação, para que possa assisti-la no horário que lhe for conveniente. As gravações das consultorias ficam salvas por uma semana.<br> <br>Desejo a você práticas frutíferas!</p><p></p><p></p><p>Sergei Zamkovoi</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"nl":[{"id":"intensive-strength-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-strength/i3_email-3ec2fc66f836.png","alt":"Интенсив «Сила»","width":"100%","align":"center","naturalWidth":600,"naturalHeight":142,"marginTop":0,"marginBottom":24},{"id":"intensive-strength-1-text","type":"text","html":"<p>Hallo, {{name}}!<br> <br>Ik ben blij dat je besloten hebt om een maand lang gericht te werken met de toestanden van kracht, vastberadenheid, doelgerichtheid, passionariteit... Het lijken natuurlijke toestanden die voor iedereen toegankelijk zijn. In de samenleving werken echter talrijke zowel stimulerende als verbiedende scenario''s die ons gedrag sturen. Door praktijken op de yogamat en in het leven uit te voeren, na te denken, je gedachten en daden bij te sturen, kun je in een maand belangrijke resultaten behalen, die zich zowel op het niveau van het lichaam (gezondwording) als op het niveau van de psychologische achtergrond (tevredenheid en geluk) manifesteren.</p><p></p><p></p><p> In de loop van deze maand ontvang je 30 praktijken die gericht zijn op het harmoniseren van de derde chakra. Lees deze brief aandachtig, zodat je begrijpt wat er zal gebeuren en hoe.<br> <br><strong>1. De kern</strong><br> Dit is geen leercursus, maar een intensieve praktijk, waarvan de dagelijkse yogapraktijken de kern vormen. Deze praktijken gaf ik ''s ochtends live, waarbij ik de richting van elke praktijk afstemde op de planetaire ritmen van die dag. In dit intensief heb ik video-opnamen verzameld van de beste praktijken die juist op de eerste chakra waren gericht (soms in wisselwerking met een andere chakra), en deze aangevuld met gedragsmatige (psychologische) praktijken. Het resultaat is een uiterst krachtige impuls voor het harmoniseren van het gebied van gezondheid. </p><p></p><p></p><p>Als je mijn cursussen niet hebt gevolgd en niet begrijpt wat die zogenaamde «derde chakra» ermee te maken heeft, raad ik je aan om deze intensive te combineren met een practicum of cursus waarin ik je geleidelijk naar het begrip breng van waar we hier mee bezig zijn. Het is belangrijk om mij niet alleen maar «te geloven», maar in jezelf begrip te openen via persoonlijke ervaring - zowel op de yogamat als in het leven. Dan gaan de praktijken veel dieper werken. Anders krijgen we gymnastiek - want dit is het basisbegrip (de ervaring) van yoga dat iedereen heeft.</p><p></p><p></p><p>Je kunt deze intensive aanvullen met de volgende leerprogramma''s:<br> - Practicum «Maand van kracht»: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a></p><p></p><p>- Cursus «Verwezenlijk je droom»: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br>  <br><strong>2. Yogapraktijken</strong><br> Yogapraktijken die u te wachten staan, verschillen van wat u in een fitnesscentrum kunt tegenkomen. Ik ga ervan uit dat het u om het resultaat gaat, en niet om toneelspel. We werken met innerlijke toestanden (dat wil zeggen met energieën), waarbij ik meditatie, pranayama en asana''s verbind voor zover dat nodig is om het gewenste resultaat op een zo diep mogelijk niveau te bereiken. De meeste praktijken beginnen met een korte inleiding, die nodig is opdat uw bewustzijn van de alledaagsheid overschakelt naar de golf van de praktijk, u in de bijbehorende energetische stroom komt en uw innerlijke intentie wordt geactiveerd. Daarna volgt de praktijk zelf, die op verschillende dagen een verschillende duur en samenstelling van elementen heeft. Na de praktijk raad ik u aan enige tijd in meditatie te blijven, of misschien in de ontstane staat van bewustzijn door te gaan met het uitvoeren van de asana''s die uw lichaam zal vragen. De gemiddelde duur van de praktijken is 30-40 minuten. Maar sommige praktijken zijn korter, en sommige duren ongeveer een uur. Het is belangrijk dat niets u tijdens de praktijk afleidt en dat niets u opjaagt. En heel belangrijk: als u eenmaal aan de praktijk bent begonnen, onderbreek deze dan niet tot het einde!!! Elke praktijk is een levend verhaal dat u langs een bepaald pad leidt. Als u de praktijk onderbreekt, kunt u in een minder veerkrachtige toestand terechtkomen dan aan het begin ervan. Zelfs als deze woorden u nu als mystificatie en lege esoterie voorkomen, luister naar mijn aanbevelingen. <br>  <br><strong>3. Gedragspraktijken</strong><br> Elke dag zal ik u in de brief samen met de yogapraktijk een «advies van de dag» sturen. Probeer het niet te zien als nog een slimme gedachte, waarvan u er al vele malen soortgelijke hebt gehoord. Het is niet mijn doel u te verrassen door iets te zeggen wat u nog niet hebt gehoord. Zie dit «advies» als een opdracht, als een gedragspraktijk! Voer deze praktijk op die dag uit. En geloof me - het zal veel interessanter voor u worden, en dit intensief zal u veel meer nut brengen. Sommige van zulke praktijken kunnen u eenvoudiger lijken, sommige moeilijker. Sommige pragmatischer, sommige psychologischer. In ieder geval is het niet alsof ik u heb voorgesteld twintig keer te hurken. Hier werken we met uw gedragsmatige en psychologische patronen. En de sleutel tot succes is om niet met uzelf te vechten, geen extra innerlijke spanning op te roepen, maar zoals in de asana''s - te ademen en te ontspannen. Daarom klinkt de praktijk zacht - als &quot;advies van de dag&quot; - om geen alarmsignaal op te roepen. Lees het, pas het op uzelf toe, probeer dit advies gedurende de dag zachtjes te volgen of er ten minste aan te denken, het opnieuw toe te passen en terug te keren naar het gevoel dat u het volgt. Pas u aan de nieuwe toestanden aan... In sommige gevallen kan één zo''n praktijk zich over meerdere dagen of zelfs maanden uitstrekken, omdat u het belang ervan zult voelen, en het in uw leven op het niveau van een gewoonte zult gaan invoeren, dat wil zeggen door de huidige homeostase van het systeem bij te stellen. En hoewel ik geen duidelijke verbinding heb aangelegd tussen de gedragspraktijken en de yogapraktijken die ik in één brief aanbied, kunt u toch elke yogapraktijk uitvoeren in de toestand die ontstaat wanneer u zichzelf ziet als iemand die mijn advies volgt. Dat is echter helemaal niet verplicht, omdat elk van deze twee praktijken op zichzelf voldoende is.<br>  <br><strong>4. Lesschema</strong><br> Elke dag om middernacht gaat er een nieuwe praktijk voor u open (de vorige verdwijnt daarbij, zoals de vorige dag). Dankzij deze aanpak zal er bij u geen sneeuwbal van niet-uitgevoerde praktijken ontstaan. Binnen een etmaal kunt u een voor u geschikt tijdstip kiezen en oefenen. Ik raad u aan ''s ochtends te oefenen, zodat u de dag kunt doorbrengen in de toestand die u door de praktijk hebt verkregen, in plaats van naar bed te gaan. Zie dit intensief niet als een computerillusie, maar als het echte leven - waarin alles wat belangrijk is VANDAAG gebeurt, en de yogapraktijk zich van de mat uitbreidt naar de ruimte van uw manifestatie in die wereld die u als de meest werkelijke ervaart!</p><p></p><p></p><p>Trouwens, er is een kleine nuance met betrekking tot de tijd waarop u de tweede praktijk ontvangt. Als u zich vóór 18:00 hebt ingeschreven, ontvangt u de tweede praktijk bij de eerstvolgende middernacht. Als u zich na 18:00 hebt ingeschreven, ontvangt u de tweede praktijk niet bij de eerstvolgende, maar bij de daaropvolgende middernacht. Dat wil zeggen dat u extra tijd hebt voor het geval u er niet aan toe komt de praktijk uit te voeren op de dag van inschrijving voor het intensief. <br>  <br><strong>5. Doe uzelf geen geweld aan</strong><br> Wanneer u een maandabonnement bij een fitnesscentrum koopt, begrijpt u toch dat u er niet elke dag heen hoeft? Sterker nog, als u een te snel tempo aanneemt, kunt u de lessen laten vallen nog voordat u zelfs maar het einde van de maand hebt bereikt... Voor de praktijken van dit intensief geldt dezelfde regel - wees niet hebberig! Oefen in een tempo dat u bevalt - om de dag, om de twee dagen... Natuurlijk is het goed om elke dag te oefenen, maar nog beter is - uw langetermijntaken te begrijpen en dienovereenkomstig te handelen. Waarschijnlijk gaan uw taken verder dan één maand, en moet u langdurig regelmatig in actie komen. Dit intensief heb ik zo bedacht dat u het maand na maand kunt doorlopen, zo vaak als nodig, totdat het door u gestelde doel is bereikt. Deze strategie is effectiever dan één maand er flink tegenaan te gaan en daarna de praktijken te laten vallen of in een andere richting te schieten.<br>  <br><strong>6. Veiligheidstechniek</strong><br> Ik geef om uw gezondheid en herinner u eraan dat alleen u verantwoordelijk bent voor of de uitvoering van de asana''s, pranayama''s en meditaties die ik zal aanbieden adequaat is voor uw lichamelijke mogelijkheden en psychische toestand. Het is belangrijk te begrijpen dat dit online lessen zijn, en dat ik uw toestand niet kan controleren. U kunt lichamelijke en psychologische bijzonderheden hebben. Wees alstublieft aandachtig voor uw eigen toestand. Als u merkt dat een bepaalde asana die ik voorstel uit te voeren voor u voortijdig is, voer haar dan niet erg diep uit, op een compromisniveau, of vervang haar helemaal door een andere asana - een die ongeveer ook het lichaam betrekt, maar eenvoudiger voor u is.<br>  <br><strong>7. Antwoorden op vragen</strong><br> Elke week (meestal op zaterdag) geef ik in Zoom groepsgewijze onlineconsulten (webinars), waarin we met elkaar praten, de motivatie ondersteunen en opkomende moeilijkheden en vragen bespreken. Voor elk zo''n consult stuur ik u een bericht met de datum en tijd waarop het plaatsvindt, evenals een link om eraan deel te nemen. Wat voor u interessant is, zal zeker ook voor velen anderen interessant zijn. Daarom is het bespreken van vragen in groepsconsulten het meest effectief. Als het zo uitkomt dat het tijdstip van het consult u niet uitkomt, stuur uw vragen dan vóór het begin per e-mail. Ik zal ze tijdens het consult beantwoorden, en u stuur ik een link naar de opname, zodat u deze op een voor u geschikt moment kunt bekijken. Opnamen van consulten worden gedurende één week bewaard.<br> <br>Ik wens u vruchtbare praktijken!</p><p></p><p></p><p>Sergei Zamkovoi</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do update set subject=excluded.subject,subject_i18n=excluded.subject_i18n,html_body=excluded.html_body,html_body_i18n=excluded.html_body_i18n,blocks_i18n=excluded.blocks_i18n;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('288dba34-5b16-5038-a114-7fdd2f66b418','7e7632e2-2733-597f-8534-d452861c4787','Заключительное письмо',2,0,'{Интенсив Сила} Что дальше?','{"ru":"{Интенсив Сила} Что дальше?","en":"{The “Strength” Intensive} What next?","de":"{Intensivkurs „Kraft“} Wie geht es weiter?","fr":"{Intensif « Force »} Et ensuite ?","it":"{Intensivo «Forza»} Cosa viene dopo?","es":"{Intensivo «Fuerza»} ¿Qué sigue?","pt":"{Intensivo «Força»} O que vem a seguir?","nl":"{Intensive «Kracht»} Wat nu?"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-strength/i3_email-3ec2fc66f836.png" alt="Интенсив «Сила»" width="504" height="119" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!<br> <br>Вот и подошёл к концу месяц практик, направленных на гармонизацию третьей чакры. Я надеюсь, что вы регулярно занимались, и получили плоды в виде ощущения расширения жизненного пространства, своей ответственности за жизнь, большей решительности, личной силы, обнаружения новых ресурсов, и так далее. Возможно, даже в плане здоровья что-то изменилось в лучшую сторону… И сейчас я предлагаю вам не терять волну и продолжить практики! В течение многих лет вы укрепляли определенный образ мыслей, ценностей, привычек, психологических клише, и сейчас вы лишь начали от всего этого освобождаться, шаг за шагом открывая кто же вы есть на самом деле. Продолжение движения в этом направлении, безусловно, даст вам более глубокие результаты.</p><p></p><p> Чтобы вновь записаться на этот интенсив, перейдите по ссылке - <a href="https://zamkovoi.yoga/i3">https://zamkovoi.yoga/i3</a> <br> <br>Если же вы чувствуете, что хотите сменить направление, то ознакомьтесь с другими моими практикумами и курсами. <br> <br>ПРАКТИКУМЫ:<br> - Месяц здоровья: <a href="https://zamkovoi.yoga/m1">https://zamkovoi.yoga/m1</a><br> - Месяц наслаждений: <a href="https://zamkovoi.yoga/m2">https://zamkovoi.yoga/m2</a><br> - Месяц силы: <a href="https://zamkovoi.yoga/m3">https://zamkovoi.yoga/m3</a><br> - Месяц любви: <a href="https://zamkovoi.yoga/m4">https://zamkovoi.yoga/m4</a><br> - Месяц свободы: <a href="https://zamkovoi.yoga/m5">https://zamkovoi.yoga/m5</a><br> - Месяц мудрости: <a href="https://zamkovoi.yoga/m6">https://zamkovoi.yoga/m6</a><br> - Месяц святости: <a href="https://zamkovoi.yoga/m7">https://zamkovoi.yoga/m7</a><br> <br>КУРСЫ:<br> - Йога и здоровье: <a href="https://zamkovoi.yoga/yoga1">https://zamkovoi.yoga/yoga1</a><br> - Йога и женственность: <a href="https://zamkovoi.yoga/yoga2">https://zamkovoi.yoga/yoga2</a><br> - Тантра - мистерия взаимоотношений: <a href="https://zamkovoi.yoga/tantra12">https://zamkovoi.yoga/tantra12</a><br> - Осуществи мечту: <a href="https://zamkovoi.yoga/yoga3">https://zamkovoi.yoga/yoga3</a><br> - Планета любви: <a href="https://zamkovoi.yoga/yoga4">https://zamkovoi.yoga/yoga4</a><br> - Источник творческой силы: <a href="https://zamkovoi.yoga/yoga5">https://zamkovoi.yoga/yoga5</a><br> - 36 шагов йоги: <a href="https://zamkovoi.yoga/yoga36">https://zamkovoi.yoga/yoga36</a><br> - Путь души: <a href="https://zamkovoi.yoga/yogas">https://zamkovoi.yoga/yogas</a><br> <br>Всех благ!<br> Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-strength/i3_email-3ec2fc66f836.png\" alt=\"Интенсив «Сила»\" width=\"504\" height=\"119\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!<br> <br>Вот и подошёл к концу месяц практик, направленных на гармонизацию третьей чакры. Я надеюсь, что вы регулярно занимались, и получили плоды в виде ощущения расширения жизненного пространства, своей ответственности за жизнь, большей решительности, личной силы, обнаружения новых ресурсов, и так далее. Возможно, даже в плане здоровья что-то изменилось в лучшую сторону… И сейчас я предлагаю вам не терять волну и продолжить практики! В течение многих лет вы укрепляли определенный образ мыслей, ценностей, привычек, психологических клише, и сейчас вы лишь начали от всего этого освобождаться, шаг за шагом открывая кто же вы есть на самом деле. Продолжение движения в этом направлении, безусловно, даст вам более глубокие результаты.</p><p></p><p> Чтобы вновь записаться на этот интенсив, перейдите по ссылке - <a href=\"https://zamkovoi.yoga/i3\">https://zamkovoi.yoga/i3</a> <br> <br>Если же вы чувствуете, что хотите сменить направление, то ознакомьтесь с другими моими практикумами и курсами. <br> <br>ПРАКТИКУМЫ:<br> - Месяц здоровья: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Месяц наслаждений: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Месяц силы: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Месяц любви: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Месяц свободы: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Месяц мудрости: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Месяц святости: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>КУРСЫ:<br> - Йога и здоровье: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Йога и женственность: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Тантра - мистерия взаимоотношений: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Осуществи мечту: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Планета любви: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Источник творческой силы: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 шагов йоги: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Путь души: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>Всех благ!<br> Сергей Замковой</p>","en":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-strength/i3_email-3ec2fc66f836.png\" alt=\"Интенсив «Сила»\" width=\"504\" height=\"119\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Hello, {{name}}!<br> <br>So the month of practices aimed at harmonizing the third chakra has come to an end. I hope that you practiced regularly and received fruits in the form of a feeling of expanding life space, your responsibility for life, greater decisiveness, personal strength, discovery of new resources, and so on. Perhaps even in terms of health something has changed for the better… And now I suggest that you not lose the wave and continue the practices! For many years you strengthened a certain way of thinking, values, habits, psychological clichés, and now you have only begun to free yourself from all of that, step by step discovering who you really are. Continuing to move in this direction will, of course, give you deeper results.</p><p></p><p>To sign up for this intensive again, follow the link - <a href=\"https://zamkovoi.yoga/i3\">https://zamkovoi.yoga/i3</a> <br> <br>If you feel that you want to change direction, then take a look at my other workshops and courses. <br> <br>WORKSHOPS:<br> - Month of Health: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Month of Pleasures: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Month of Strength: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Month of Love: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Month of Freedom: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Month of Wisdom: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Month of Holiness: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>COURSES:<br> - Yoga and Health: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga and Femininity: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - the mystery of relationships: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Fulfill the Dream: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Planet of Love: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Source of Creative Power: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 Steps of Yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Path of the Soul: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>All the best!</p><p></p><p>Sergei Zamkovoi</p>","de":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-strength/i3_email-3ec2fc66f836.png\" alt=\"Интенсив «Сила»\" width=\"504\" height=\"119\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Guten Tag, {{name}}!<br> <br>Nun ist der Monat der Praktiken, die auf die Harmonisierung des dritten Chakras ausgerichtet sind, zu Ende gegangen. Ich hoffe, dass Sie regelmäßig geübt haben und die Früchte in Form des Gefühls eines erweiterten Lebensraums, Ihrer Verantwortung für das Leben, größerer Entschlossenheit, persönlicher Kraft, der Entdeckung neuer Ressourcen und so weiter erhalten haben. Vielleicht hat sich sogar gesundheitlich etwas zum Besseren verändert … Und jetzt schlage ich Ihnen vor, die Welle nicht zu verlieren und mit den Praktiken fortzufahren! Viele Jahre lang haben Sie eine bestimmte Denkweise, Werte, Gewohnheiten und psychologische Klischees gefestigt, und jetzt haben Sie gerade erst begonnen, sich von all dem zu befreien und Schritt für Schritt zu entdecken, wer Sie wirklich sind. Die Fortsetzung der Bewegung in diese Richtung wird Ihnen zweifellos tiefergehende Ergebnisse bringen.</p><p></p><p> Um sich erneut für diesen Intensivkurs anzumelden, folgen Sie dem Link - <a href=\"https://zamkovoi.yoga/i3\">https://zamkovoi.yoga/i3</a> <br> <br>Wenn Sie jedoch das Gefühl haben, die Richtung wechseln zu wollen, dann machen Sie sich mit meinen anderen Praktika und Kursen vertraut. <br> <br>PRAKTIKA:<br> - Monat der Gesundheit: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Monat der Genüsse: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Monat der Kraft: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Monat der Liebe: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Monat der Freiheit: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Monat der Weisheit: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Monat der Heiligkeit: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>KURSE:<br> - Yoga und Gesundheit: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga und Weiblichkeit: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - Mysterium der Beziehungen: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Verwirkliche den Traum: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Planet der Liebe: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Quelle schöpferischer Kraft: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 Schritte des Yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Weg der Seele: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>Alles Gute!</p><p></p><p>Sergei Zamkovoi</p>","fr":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-strength/i3_email-3ec2fc66f836.png\" alt=\"Интенсив «Сила»\" width=\"504\" height=\"119\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Bonjour, {{name}} !<br> <br>Voici donc arrivé à son terme le mois de pratiques visant à harmoniser le troisième chakra. J’espère que vous avez pratiqué régulièrement et que vous avez obtenu des fruits sous forme de sensation d’expansion de l’espace de vie, de votre responsabilité pour la vie, d’une plus grande détermination, d’une force personnelle, de la découverte de nouvelles ressources, etc. Peut-être que même sur le plan de la santé quelque chose a changé en mieux… Et maintenant je vous propose de ne pas perdre la vague et de poursuivre les pratiques ! Pendant de nombreuses années, vous avez renforcé une certaine manière de penser, des valeurs, des habitudes, des clichés psychologiques, et maintenant vous avez seulement commencé à vous en libérer, en découvrant pas à pas qui vous êtes réellement. La poursuite du mouvement dans cette direction vous donnera, bien sûr, des résultats plus profonds.</p><p></p><p> Pour vous réinscrire à cet intensif, suivez le lien - <a href=\"https://zamkovoi.yoga/i3\">https://zamkovoi.yoga/i3</a> <br> <br>Si toutefois vous sentez que vous voulez changer de direction, alors prenez connaissance de mes autres ateliers et cours. <br> <br>ATELIERS :<br> - Mois de la santé : <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Mois des plaisirs : <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Mois de la force : <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Mois de l’amour : <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Mois de la liberté : <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Mois de la sagesse : <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Mois de la sainteté : <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>COURS :<br> - Yoga et santé: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga et féminité: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - mystère des relations: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Réalise ton rêve: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Planète de l''amour: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Source de force créatrice: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 pas de yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Chemin de l''âme: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>Toutes les bénédictions !</p><p></p><p>Sergei Zamkovoi</p>","it":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-strength/i3_email-3ec2fc66f836.png\" alt=\"Интенсив «Сила»\" width=\"504\" height=\"119\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Salve, {{name}}!<br> <br>Ecco che è giunto al termine il mese di pratiche volte ad armonizzare il terzo chakra. Spero che vi siate esercitati regolarmente e abbiate ottenuto frutti sotto forma di una sensazione di espansione dello spazio vitale, della vostra responsabilità per la vita, di maggiore determinazione, forza personale, scoperta di nuove risorse e così via. Forse, anche sul piano della salute qualcosa è cambiato in meglio… E ora vi propongo di non perdere l''onda e di continuare le pratiche! Per molti anni avete rafforzato un certo modo di pensare, valori, abitudini, cliché psicologici, e ora avete solo iniziato a liberarvene, scoprendo passo dopo passo chi siete davvero. La continuazione del movimento in questa direzione, senza dubbio, vi darà risultati più profondi.</p><p></p><p> Per iscrivervi di nuovo a questo intensivo, seguite il link - <a href=\"https://zamkovoi.yoga/i3\">https://zamkovoi.yoga/i3</a> <br> <br>Se invece sentite di voler cambiare direzione, allora date un''occhiata agli altri miei praticum e corsi. <br> <br>PRATICUM:<br> - Mese della salute: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Mese dei piaceri: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Mese della forza: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Mese dell''amore: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Mese della libertà: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Mese della saggezza: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Mese della santità: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>CORSI:<br> - Yoga e salute: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga e femminilità: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - mistero delle relazioni: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Realizza il sogno: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Pianeta dell''amore: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Fonte di forza creativa: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 passi di yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Il cammino dell''anima: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>Ogni bene!</p><p></p><p>Sergei Zamkovoi</p>","es":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-strength/i3_email-3ec2fc66f836.png\" alt=\"Интенсив «Сила»\" width=\"504\" height=\"119\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Hola, {{name}}!<br> <br>He aquí que ha llegado a su fin el mes de prácticas dirigidas a armonizar el tercer chakra. Espero que hayan practicado con regularidad y hayan obtenido frutos en forma de una sensación de expansión del espacio vital, de su propia responsabilidad por la vida, de mayor determinación, fuerza personal, descubrimiento de nuevos recursos, y así sucesivamente. Quizá, incluso en el plano de la salud, algo haya cambiado para mejor… Y ahora les propongo no perder la ola y continuar las prácticas. Durante muchos años han reforzado una determinada forma de pensar, valores, hábitos, clichés psicológicos, y ahora solo han comenzado a liberarse de todo ello, abriendo paso a paso quiénes son en realidad. La continuación del movimiento en esta dirección, sin duda, les dará resultados más profundos.</p><p></p><p> Para inscribirse de nuevo en este intensivo, sigan el enlace - <a href=\"https://zamkovoi.yoga/i3\">https://zamkovoi.yoga/i3</a> <br> <br>Si siente que quiere cambiar de dirección, eche un vistazo a mis otros talleres y cursos. <br> <br>TALLERES:<br> - Mes de la salud: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Mes de los placeres: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Mes de la fuerza: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Mes del amor: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Mes de la libertad: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Mes de la sabiduría: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Mes de la santidad: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>CURSOS:<br> - Yoga y salud: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga y feminidad: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - misterio de las relaciones: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Haz realidad tu sueño: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Planeta del amor: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Fuente de la fuerza creativa: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 pasos del yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Camino del alma: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>¡Todo lo mejor!</p><p></p><p>Sergei Zamkovoi</p>","pt":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-strength/i3_email-3ec2fc66f836.png\" alt=\"Интенсив «Сила»\" width=\"504\" height=\"119\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Olá, {{name}}!<br> <br>Eis que chegou ao fim o mês de práticas voltadas à harmonização do terceiro chakra. Espero que você tenha praticado regularmente e obtido frutos na forma de sensação de expansão do espaço vital, de sua responsabilidade pela vida, de maior determinação, força pessoal, descoberta de novos recursos, e assim por diante. Talvez até no plano da saúde algo tenha mudado para melhor… E agora eu proponho que você não perca a onda e continue as práticas! Durante muitos anos você fortaleceu um determinado modo de pensar, valores, hábitos, clichês psicológicos, e agora você apenas começou a se libertar de tudo isso, passo a passo descobrindo quem você é de verdade. A continuação do movimento nessa direção, sem dúvida, lhe dará resultados mais profundos.</p><p></p><p> Para se inscrever novamente neste intensivo, acesse o link - <a href=\"https://zamkovoi.yoga/i3\">https://zamkovoi.yoga/i3</a> <br> <br>Se, porém, você sente que quer mudar de direção, conheça meus outros praticuns e cursos. <br> <br>PRATICUNS:<br> - Mês da saúde: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Mês dos prazeres: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Mês da força: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Mês do amor: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Mês da liberdade: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Mês da sabedoria: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Mês da santidade: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>CURSOS:<br> - Yoga e saúde: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga e feminilidade: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - mistério das relações: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Realize o sonho: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Planeta do amor: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Fonte da força criativa: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 passos de yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Caminho da alma: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>Tudo de bom!</p><p></p><p>Sergei Zamkovoi</p>","nl":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-strength/i3_email-3ec2fc66f836.png\" alt=\"Интенсив «Сила»\" width=\"504\" height=\"119\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Hallo, {{name}}!<br> <br>Zo is de maand van praktijken gericht op het harmoniseren van de derde chakra ten einde gekomen. Ik hoop dat je regelmatig hebt geoefend en vruchten hebt geoogst in de vorm van een gevoel van uitbreiding van je levensruimte, je verantwoordelijkheid voor het leven, grotere vastberadenheid, persoonlijke kracht, het ontdekken van nieuwe hulpbronnen, enzovoort. Misschien is er zelfs op het gebied van gezondheid iets ten goede veranderd… En nu nodig ik je uit om de golf niet te verliezen en de praktijken voort te zetten! Jarenlang heb je een bepaald gedachtegoed, waarden, gewoonten en psychologische clichés versterkt, en nu ben je pas begonnen je daarvan te bevrijden, stap voor stap ontdekkend wie je werkelijk bent. Als je in deze richting doorgaat, zal dat je ongetwijfeld diepere resultaten opleveren.</p><p></p><p> Om je opnieuw voor deze intensive in te schrijven, ga je naar de link - <a href=\"https://zamkovoi.yoga/i3\">https://zamkovoi.yoga/i3</a><br> <br>Als u echter voelt dat u van richting wilt veranderen, maak dan kennis met mijn andere praktijken en cursussen. <br> <br>PRAKTIJKEN:<br> - Maand van gezondheid: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Maand van genot: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Maand van kracht: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Maand van liefde: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Maand van vrijheid: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Maand van wijsheid: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Maand van heiligheid: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>CURSUSSEN:<br> - Yoga en gezondheid: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga en vrouwelijkheid: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - mysterie van relaties: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Verwezenlijk je droom: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Planeet van de liefde: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Bron van creatieve kracht: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 stappen van yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Pad van de ziel: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>Alle goeds!</p><p></p><p>Sergei Zamkovoi</p>"}'::jsonb,'{"ru":[{"id":"intensive-strength-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-strength/i3_email-3ec2fc66f836.png","alt":"Интенсив «Сила»","width":"100%","align":"center","naturalWidth":600,"naturalHeight":142,"marginTop":0,"marginBottom":24},{"id":"intensive-strength-2-text","type":"text","html":"<p>Здравствуйте, {{name}}!<br> <br>Вот и подошёл к концу месяц практик, направленных на гармонизацию третьей чакры. Я надеюсь, что вы регулярно занимались, и получили плоды в виде ощущения расширения жизненного пространства, своей ответственности за жизнь, большей решительности, личной силы, обнаружения новых ресурсов, и так далее. Возможно, даже в плане здоровья что-то изменилось в лучшую сторону… И сейчас я предлагаю вам не терять волну и продолжить практики! В течение многих лет вы укрепляли определенный образ мыслей, ценностей, привычек, психологических клише, и сейчас вы лишь начали от всего этого освобождаться, шаг за шагом открывая кто же вы есть на самом деле. Продолжение движения в этом направлении, безусловно, даст вам более глубокие результаты.</p><p></p><p> Чтобы вновь записаться на этот интенсив, перейдите по ссылке - <a href=\"https://zamkovoi.yoga/i3\">https://zamkovoi.yoga/i3</a> <br> <br>Если же вы чувствуете, что хотите сменить направление, то ознакомьтесь с другими моими практикумами и курсами. <br> <br>ПРАКТИКУМЫ:<br> - Месяц здоровья: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Месяц наслаждений: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Месяц силы: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Месяц любви: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Месяц свободы: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Месяц мудрости: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Месяц святости: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>КУРСЫ:<br> - Йога и здоровье: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Йога и женственность: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Тантра - мистерия взаимоотношений: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Осуществи мечту: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Планета любви: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Источник творческой силы: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 шагов йоги: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Путь души: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>Всех благ!<br> Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"en":[{"id":"intensive-strength-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-strength/i3_email-3ec2fc66f836.png","alt":"Интенсив «Сила»","width":"100%","align":"center","naturalWidth":600,"naturalHeight":142,"marginTop":0,"marginBottom":24},{"id":"intensive-strength-2-text","type":"text","html":"<p>Hello, {{name}}!<br> <br>So the month of practices aimed at harmonizing the third chakra has come to an end. I hope that you practiced regularly and received fruits in the form of a feeling of expanding life space, your responsibility for life, greater decisiveness, personal strength, discovery of new resources, and so on. Perhaps even in terms of health something has changed for the better… And now I suggest that you not lose the wave and continue the practices! For many years you strengthened a certain way of thinking, values, habits, psychological clichés, and now you have only begun to free yourself from all of that, step by step discovering who you really are. Continuing to move in this direction will, of course, give you deeper results.</p><p></p><p>To sign up for this intensive again, follow the link - <a href=\"https://zamkovoi.yoga/i3\">https://zamkovoi.yoga/i3</a> <br> <br>If you feel that you want to change direction, then take a look at my other workshops and courses. <br> <br>WORKSHOPS:<br> - Month of Health: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Month of Pleasures: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Month of Strength: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Month of Love: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Month of Freedom: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Month of Wisdom: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Month of Holiness: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>COURSES:<br> - Yoga and Health: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga and Femininity: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - the mystery of relationships: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Fulfill the Dream: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Planet of Love: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Source of Creative Power: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 Steps of Yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Path of the Soul: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>All the best!</p><p></p><p>Sergei Zamkovoi</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"de":[{"id":"intensive-strength-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-strength/i3_email-3ec2fc66f836.png","alt":"Интенсив «Сила»","width":"100%","align":"center","naturalWidth":600,"naturalHeight":142,"marginTop":0,"marginBottom":24},{"id":"intensive-strength-2-text","type":"text","html":"<p>Guten Tag, {{name}}!<br> <br>Nun ist der Monat der Praktiken, die auf die Harmonisierung des dritten Chakras ausgerichtet sind, zu Ende gegangen. Ich hoffe, dass Sie regelmäßig geübt haben und die Früchte in Form des Gefühls eines erweiterten Lebensraums, Ihrer Verantwortung für das Leben, größerer Entschlossenheit, persönlicher Kraft, der Entdeckung neuer Ressourcen und so weiter erhalten haben. Vielleicht hat sich sogar gesundheitlich etwas zum Besseren verändert … Und jetzt schlage ich Ihnen vor, die Welle nicht zu verlieren und mit den Praktiken fortzufahren! Viele Jahre lang haben Sie eine bestimmte Denkweise, Werte, Gewohnheiten und psychologische Klischees gefestigt, und jetzt haben Sie gerade erst begonnen, sich von all dem zu befreien und Schritt für Schritt zu entdecken, wer Sie wirklich sind. Die Fortsetzung der Bewegung in diese Richtung wird Ihnen zweifellos tiefergehende Ergebnisse bringen.</p><p></p><p> Um sich erneut für diesen Intensivkurs anzumelden, folgen Sie dem Link - <a href=\"https://zamkovoi.yoga/i3\">https://zamkovoi.yoga/i3</a> <br> <br>Wenn Sie jedoch das Gefühl haben, die Richtung wechseln zu wollen, dann machen Sie sich mit meinen anderen Praktika und Kursen vertraut. <br> <br>PRAKTIKA:<br> - Monat der Gesundheit: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Monat der Genüsse: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Monat der Kraft: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Monat der Liebe: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Monat der Freiheit: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Monat der Weisheit: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Monat der Heiligkeit: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>KURSE:<br> - Yoga und Gesundheit: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga und Weiblichkeit: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - Mysterium der Beziehungen: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Verwirkliche den Traum: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Planet der Liebe: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Quelle schöpferischer Kraft: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 Schritte des Yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Weg der Seele: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>Alles Gute!</p><p></p><p>Sergei Zamkovoi</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"fr":[{"id":"intensive-strength-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-strength/i3_email-3ec2fc66f836.png","alt":"Интенсив «Сила»","width":"100%","align":"center","naturalWidth":600,"naturalHeight":142,"marginTop":0,"marginBottom":24},{"id":"intensive-strength-2-text","type":"text","html":"<p>Bonjour, {{name}} !<br> <br>Voici donc arrivé à son terme le mois de pratiques visant à harmoniser le troisième chakra. J’espère que vous avez pratiqué régulièrement et que vous avez obtenu des fruits sous forme de sensation d’expansion de l’espace de vie, de votre responsabilité pour la vie, d’une plus grande détermination, d’une force personnelle, de la découverte de nouvelles ressources, etc. Peut-être que même sur le plan de la santé quelque chose a changé en mieux… Et maintenant je vous propose de ne pas perdre la vague et de poursuivre les pratiques ! Pendant de nombreuses années, vous avez renforcé une certaine manière de penser, des valeurs, des habitudes, des clichés psychologiques, et maintenant vous avez seulement commencé à vous en libérer, en découvrant pas à pas qui vous êtes réellement. La poursuite du mouvement dans cette direction vous donnera, bien sûr, des résultats plus profonds.</p><p></p><p> Pour vous réinscrire à cet intensif, suivez le lien - <a href=\"https://zamkovoi.yoga/i3\">https://zamkovoi.yoga/i3</a> <br> <br>Si toutefois vous sentez que vous voulez changer de direction, alors prenez connaissance de mes autres ateliers et cours. <br> <br>ATELIERS :<br> - Mois de la santé : <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Mois des plaisirs : <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Mois de la force : <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Mois de l’amour : <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Mois de la liberté : <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Mois de la sagesse : <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Mois de la sainteté : <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>COURS :<br> - Yoga et santé: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga et féminité: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - mystère des relations: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Réalise ton rêve: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Planète de l''amour: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Source de force créatrice: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 pas de yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Chemin de l''âme: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>Toutes les bénédictions !</p><p></p><p>Sergei Zamkovoi</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"it":[{"id":"intensive-strength-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-strength/i3_email-3ec2fc66f836.png","alt":"Интенсив «Сила»","width":"100%","align":"center","naturalWidth":600,"naturalHeight":142,"marginTop":0,"marginBottom":24},{"id":"intensive-strength-2-text","type":"text","html":"<p>Salve, {{name}}!<br> <br>Ecco che è giunto al termine il mese di pratiche volte ad armonizzare il terzo chakra. Spero che vi siate esercitati regolarmente e abbiate ottenuto frutti sotto forma di una sensazione di espansione dello spazio vitale, della vostra responsabilità per la vita, di maggiore determinazione, forza personale, scoperta di nuove risorse e così via. Forse, anche sul piano della salute qualcosa è cambiato in meglio… E ora vi propongo di non perdere l''onda e di continuare le pratiche! Per molti anni avete rafforzato un certo modo di pensare, valori, abitudini, cliché psicologici, e ora avete solo iniziato a liberarvene, scoprendo passo dopo passo chi siete davvero. La continuazione del movimento in questa direzione, senza dubbio, vi darà risultati più profondi.</p><p></p><p> Per iscrivervi di nuovo a questo intensivo, seguite il link - <a href=\"https://zamkovoi.yoga/i3\">https://zamkovoi.yoga/i3</a> <br> <br>Se invece sentite di voler cambiare direzione, allora date un''occhiata agli altri miei praticum e corsi. <br> <br>PRATICUM:<br> - Mese della salute: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Mese dei piaceri: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Mese della forza: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Mese dell''amore: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Mese della libertà: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Mese della saggezza: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Mese della santità: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>CORSI:<br> - Yoga e salute: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga e femminilità: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - mistero delle relazioni: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Realizza il sogno: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Pianeta dell''amore: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Fonte di forza creativa: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 passi di yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Il cammino dell''anima: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>Ogni bene!</p><p></p><p>Sergei Zamkovoi</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"es":[{"id":"intensive-strength-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-strength/i3_email-3ec2fc66f836.png","alt":"Интенсив «Сила»","width":"100%","align":"center","naturalWidth":600,"naturalHeight":142,"marginTop":0,"marginBottom":24},{"id":"intensive-strength-2-text","type":"text","html":"<p>Hola, {{name}}!<br> <br>He aquí que ha llegado a su fin el mes de prácticas dirigidas a armonizar el tercer chakra. Espero que hayan practicado con regularidad y hayan obtenido frutos en forma de una sensación de expansión del espacio vital, de su propia responsabilidad por la vida, de mayor determinación, fuerza personal, descubrimiento de nuevos recursos, y así sucesivamente. Quizá, incluso en el plano de la salud, algo haya cambiado para mejor… Y ahora les propongo no perder la ola y continuar las prácticas. Durante muchos años han reforzado una determinada forma de pensar, valores, hábitos, clichés psicológicos, y ahora solo han comenzado a liberarse de todo ello, abriendo paso a paso quiénes son en realidad. La continuación del movimiento en esta dirección, sin duda, les dará resultados más profundos.</p><p></p><p> Para inscribirse de nuevo en este intensivo, sigan el enlace - <a href=\"https://zamkovoi.yoga/i3\">https://zamkovoi.yoga/i3</a> <br> <br>Si siente que quiere cambiar de dirección, eche un vistazo a mis otros talleres y cursos. <br> <br>TALLERES:<br> - Mes de la salud: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Mes de los placeres: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Mes de la fuerza: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Mes del amor: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Mes de la libertad: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Mes de la sabiduría: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Mes de la santidad: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>CURSOS:<br> - Yoga y salud: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga y feminidad: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - misterio de las relaciones: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Haz realidad tu sueño: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Planeta del amor: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Fuente de la fuerza creativa: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 pasos del yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Camino del alma: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>¡Todo lo mejor!</p><p></p><p>Sergei Zamkovoi</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"pt":[{"id":"intensive-strength-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-strength/i3_email-3ec2fc66f836.png","alt":"Интенсив «Сила»","width":"100%","align":"center","naturalWidth":600,"naturalHeight":142,"marginTop":0,"marginBottom":24},{"id":"intensive-strength-2-text","type":"text","html":"<p>Olá, {{name}}!<br> <br>Eis que chegou ao fim o mês de práticas voltadas à harmonização do terceiro chakra. Espero que você tenha praticado regularmente e obtido frutos na forma de sensação de expansão do espaço vital, de sua responsabilidade pela vida, de maior determinação, força pessoal, descoberta de novos recursos, e assim por diante. Talvez até no plano da saúde algo tenha mudado para melhor… E agora eu proponho que você não perca a onda e continue as práticas! Durante muitos anos você fortaleceu um determinado modo de pensar, valores, hábitos, clichês psicológicos, e agora você apenas começou a se libertar de tudo isso, passo a passo descobrindo quem você é de verdade. A continuação do movimento nessa direção, sem dúvida, lhe dará resultados mais profundos.</p><p></p><p> Para se inscrever novamente neste intensivo, acesse o link - <a href=\"https://zamkovoi.yoga/i3\">https://zamkovoi.yoga/i3</a> <br> <br>Se, porém, você sente que quer mudar de direção, conheça meus outros praticuns e cursos. <br> <br>PRATICUNS:<br> - Mês da saúde: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Mês dos prazeres: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Mês da força: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Mês do amor: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Mês da liberdade: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Mês da sabedoria: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Mês da santidade: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>CURSOS:<br> - Yoga e saúde: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga e feminilidade: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - mistério das relações: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Realize o sonho: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Planeta do amor: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Fonte da força criativa: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 passos de yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Caminho da alma: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>Tudo de bom!</p><p></p><p>Sergei Zamkovoi</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"nl":[{"id":"intensive-strength-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-strength/i3_email-3ec2fc66f836.png","alt":"Интенсив «Сила»","width":"100%","align":"center","naturalWidth":600,"naturalHeight":142,"marginTop":0,"marginBottom":24},{"id":"intensive-strength-2-text","type":"text","html":"<p>Hallo, {{name}}!<br> <br>Zo is de maand van praktijken gericht op het harmoniseren van de derde chakra ten einde gekomen. Ik hoop dat je regelmatig hebt geoefend en vruchten hebt geoogst in de vorm van een gevoel van uitbreiding van je levensruimte, je verantwoordelijkheid voor het leven, grotere vastberadenheid, persoonlijke kracht, het ontdekken van nieuwe hulpbronnen, enzovoort. Misschien is er zelfs op het gebied van gezondheid iets ten goede veranderd… En nu nodig ik je uit om de golf niet te verliezen en de praktijken voort te zetten! Jarenlang heb je een bepaald gedachtegoed, waarden, gewoonten en psychologische clichés versterkt, en nu ben je pas begonnen je daarvan te bevrijden, stap voor stap ontdekkend wie je werkelijk bent. Als je in deze richting doorgaat, zal dat je ongetwijfeld diepere resultaten opleveren.</p><p></p><p> Om je opnieuw voor deze intensive in te schrijven, ga je naar de link - <a href=\"https://zamkovoi.yoga/i3\">https://zamkovoi.yoga/i3</a><br> <br>Als u echter voelt dat u van richting wilt veranderen, maak dan kennis met mijn andere praktijken en cursussen. <br> <br>PRAKTIJKEN:<br> - Maand van gezondheid: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Maand van genot: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Maand van kracht: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Maand van liefde: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Maand van vrijheid: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Maand van wijsheid: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Maand van heiligheid: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>CURSUSSEN:<br> - Yoga en gezondheid: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga en vrouwelijkheid: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - mysterie van relaties: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Verwezenlijk je droom: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Planeet van de liefde: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Bron van creatieve kracht: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 stappen van yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Pad van de ziel: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>Alle goeds!</p><p></p><p>Sergei Zamkovoi</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do update set subject=excluded.subject,subject_i18n=excluded.subject_i18n,html_body=excluded.html_body,html_body_i18n=excluded.html_body_i18n,blocks_i18n=excluded.blocks_i18n;
insert into public.courses(slug,title,title_i18n,kind,landing_url,access_days,day_card_extra_days,webinar_extra_days,automation_id,intro_email_step_id,completion_email_step_id,source_hash) values('intensive-strength','Интенсив «Сила»','{"ru":"Интенсив «Сила»","en":"The “Strength” Intensive","de":"Intensivkurs „Kraft“","fr":"Intensif « Force »","it":"Intensivo «Forza»","es":"Intensivo «Fuerza»","pt":"Intensivo «Força»","nl":"Intensive «Kracht»"}'::jsonb,'intensive','',1,1,1,'7e7632e2-2733-597f-8534-d452861c4787','969d65d6-7d75-5b24-a939-025ee15acf64','288dba34-5b16-5038-a114-7fdd2f66b418','e5fa391bb884f2e446ee7e92edba4e8ec4a6b44d506551ee5fa1677c1f8abe90') on conflict(slug) do update set source_hash=excluded.source_hash;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-strength-01','intensive-strength',1,0,'День: 1','[{"type":"video","vimeoId":"1141951353"},{"type":"text","markdown":"### Совет дня:\n\nПримите полную ответственность за свою жизнь и за всё, что вас как-либо касается. Перестаньте искать виновных в своих неудачах или причины успеха во внешних обстоятельствах. Ваша жизнь - это на 100% ваша зона ответственности. Даже когда  происходит то, что от вас явно не зависит (ливень, например) - ваша реакция, действие и результат - являются именно вашими! Только из этой точки начинается подлинное управление своей реальностью."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1141951353"},{"type":"text","markdown":"### Tip of the day:\n\nTake full responsibility for your life and for everything that concerns you in any way. Stop looking for those to blame for your failures or the causes of success in external circumstances. Your life is 100% your area of responsibility. Even when something happens that clearly does not depend on you (a downpour, for example) - your reaction, action and result are precisely yours! Only from this point does true management of your reality begin."}],"de":[{"type":"video","vimeoId":"1141951353"},{"type":"text","markdown":"### Tipp des Tages:\n\nÜbernehmen Sie die volle Verantwortung für Ihr Leben und für alles, was Sie irgendwie betrifft. Hören Sie auf, Schuldige für Ihre Misserfolge oder die Ursachen Ihres Erfolgs in äußeren Umständen zu suchen. Ihr Leben ist zu 100 % Ihre Verantwortungszone. Selbst wenn etwas geschieht, das offensichtlich nicht von Ihnen abhängt (zum Beispiel ein Platzregen) – Ihre Reaktion, Ihr Handeln und Ihr Ergebnis sind genau Ihre! Nur von diesem Punkt aus beginnt die echte Steuerung Ihrer Realität."}],"fr":[{"type":"video","vimeoId":"1141951353"},{"type":"text","markdown":"### Conseil du jour :\n\nPrenez l’entière responsabilité de votre vie et de tout ce qui vous concerne de quelque manière que ce soit. Cessez de chercher les coupables de vos échecs ou les causes de votre réussite dans les circonstances extérieures. Votre vie est à 100 % votre zone de responsabilité. Même lorsque se produit ce qui ne dépend manifestement pas de vous (une averse, par exemple), votre réaction, votre action et votre résultat sont bien les vôtres ! C’est seulement à partir de ce point que commence la véritable maîtrise de votre réalité."}],"it":[{"type":"video","vimeoId":"1141951353"},{"type":"text","markdown":"### Consiglio del giorno:\n\nPrendete piena responsabilità della vostra vita e di tutto ciò che vi riguarda in qualunque modo. Smettete di cercare i colpevoli dei vostri fallimenti o le cause del successo nelle circostanze esterne. La vostra vita è al 100% la vostra area di responsabilità. Anche quando  accade qualcosa che chiaramente non dipende da voi (un acquazzone, per esempio) - la vostra reazione, l''azione e il risultato sono proprio vostri! Solo da questo punto inizia la vera gestione della propria realtà."}],"es":[{"type":"video","vimeoId":"1141951353"},{"type":"text","markdown":"### Consejo del día:\n\nAsuman la responsabilidad total por su vida y por todo lo que les concierne de cualquier manera. Dejen de buscar culpables de sus fracasos o causas del éxito en las circunstancias externas. Su vida es al 100% su zona de responsabilidad. Incluso cuando ocurre algo que claramente no depende de ustedes (un aguacero, por ejemplo), su reacción, su acción y el resultado son precisamente suyos. Solo desde este punto comienza la verdadera gestión de su realidad."}],"pt":[{"type":"video","vimeoId":"1141951353"},{"type":"text","markdown":"### Dica do dia:\n\nAssuma total responsabilidade pela sua vida e por tudo o que de alguma forma lhe diz respeito. Pare de procurar culpados por seus fracassos ou causas do sucesso em circunstâncias externas. Sua vida é 100% sua área de responsabilidade. Mesmo quando acontece aquilo que claramente não depende de você (uma chuva torrencial, por exemplo) - sua reação, ação e resultado - são precisamente seus! Só a partir desse ponto começa a verdadeira gestão da sua realidade."}],"nl":[{"type":"video","vimeoId":"1141951353"},{"type":"text","markdown":"### Tip van de dag:\n\nNeem volledige verantwoordelijkheid voor je leven en voor alles wat jou op enigerlei wijze aangaat. Stop met het zoeken naar schuldigen voor je mislukkingen of naar oorzaken van succes in externe omstandigheden. Je leven is voor 100% jouw verantwoordelijkheidsgebied. Zelfs wanneer er iets gebeurt dat duidelijk niet van jou afhangt (een stortbui, bijvoorbeeld) - je reactie, handeling en resultaat zijn precies de jouwe! Alleen vanuit dit punt begint het echte besturen van je realiteit."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-strength-02','intensive-strength',2,1,'День: 2','[{"type":"video","vimeoId":"1149782417"},{"type":"text","markdown":"### Совет дня:\n\nВзращивайте внутренний огонь, но избегайте пожара! Энергия - это топливо. Направленная на цель, она становится движущей силой. Распыленная на гнев, тревогу и раздражение, она сжигает вас изнутри. Не только психические структуры, но и ЖКТ в опасности. Проблемы со здоровьем ЖКТ с очевидностью указывают на то, что вы управляете энергией деструктивно - разрушая свою жизнь, а не созидая. Учитесь концентрировать энергию на позитивном действии, а не на разрушительных эмоциональных вспышках."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1149782417"},{"type":"text","markdown":"### Tip of the day:\n\nCultivate the inner fire, but avoid a fire! Energy is fuel. Directed toward a goal, it becomes a driving force. Dispersed into anger, anxiety and irritation, it burns you from within. Not only psychic structures but also the gastrointestinal tract are in danger. Problems with GIT health clearly indicate that you are managing energy destructively - destroying your life rather than creating. Learn to concentrate energy on positive action, and not on destructive emotional outbursts."}],"de":[{"type":"video","vimeoId":"1149782417"},{"type":"text","markdown":"### Tipp des Tages:\n\nNähren Sie das innere Feuer, aber vermeiden Sie einen Brand! Energie ist Treibstoff. Auf ein Ziel gerichtet, wird sie zur treibenden Kraft. Auf Zorn, Angst und Verärgerung verteilt, verbrennt sie Sie von innen. Nicht nur die psychischen Strukturen, sondern auch der Magen-Darm-Trakt sind in Gefahr. Gesundheitsprobleme des Magen-Darm-Trakts weisen offensichtlich darauf hin, dass Sie Energie destruktiv steuern – indem Sie Ihr Leben zerstören, statt es aufzubauen. Lernen Sie, Energie auf positives Handeln zu konzentrieren und nicht auf destruktive emotionale Ausbrüche."}],"fr":[{"type":"video","vimeoId":"1149782417"},{"type":"text","markdown":"### Conseil du jour :\n\nCultivez le feu intérieur, mais évitez l’incendie ! L’énergie est un carburant. Dirigée vers un but, elle devient une force motrice. Dispersée dans la colère, l’anxiété et l’irritation, elle vous brûle de l’intérieur. Non seulement les structures psychiques, mais aussi l’appareil digestif sont en danger. Les problèmes de santé de l’appareil digestif indiquent avec évidence que vous gérez l’énergie de manière destructrice – en détruisant votre vie au lieu de la construire. Apprenez à concentrer l’énergie sur une action positive, et non sur des explosions émotionnelles destructrices."}],"it":[{"type":"video","vimeoId":"1149782417"},{"type":"text","markdown":"### Consiglio del giorno:\n\nColtivate il fuoco interiore, ma evitate l''incendio! L''energia è combustibile. Diretta verso un obiettivo, diventa forza motrice. Dispersa in rabbia, ansia e irritazione, vi brucia dall''interno. Non solo le strutture psichiche, ma anche l''apparato gastrointestinale è in pericolo. I problemi di salute dell''apparato gastrointestinale indicano con evidenza che gestite l''energia in modo distruttivo - distruggendo la vostra vita invece di crearla. Imparate a concentrare l''energia su un''azione positiva, e non su scoppi emotivi distruttivi."}],"es":[{"type":"video","vimeoId":"1149782417"},{"type":"text","markdown":"### Consejo del día:\n\nCultiven el fuego interno, ¡pero eviten el incendio! La energía es combustible. Dirigida hacia un objetivo, se convierte en fuerza motriz. Dispersa en ira, ansiedad e irritación, los quema por dentro. No solo las estructuras psíquicas, sino también el tracto gastrointestinal están en peligro. Los problemas de salud del tracto gastrointestinal indican con evidencia que gestionan la energía de forma destructiva: destruyendo su vida en lugar de construirla. Aprendan a concentrar la energía en una acción positiva y no en estallidos emocionales destructivos."}],"pt":[{"type":"video","vimeoId":"1149782417"},{"type":"text","markdown":"### Dica do dia:\n\nCultive o fogo interior, mas evite o incêndio! A energia é combustível. Direcionada a um objetivo, ela se torna força motriz. Dispersa em raiva, ansiedade e irritação, ela queima você por dentro. Não apenas as estruturas psíquicas, mas também o trato gastrointestinal estão em perigo. Problemas de saúde do trato gastrointestinal indicam com evidência que você gerencia a energia de forma destrutiva - destruindo sua vida, e não criando. Aprenda a concentrar a energia em ação positiva, e não em explosões emocionais destrutivas."}],"nl":[{"type":"video","vimeoId":"1149782417"},{"type":"text","markdown":"### Tip van de dag:\n\nKweek het innerlijke vuur, maar vermijd een brand! Energie is brandstof. Gericht op een doel wordt ze een drijvende kracht. Verspreid over woede, angst en irritatie verbrandt ze je van binnenuit. Niet alleen de psychische structuren, maar ook het maag-darmkanaal lopen gevaar. Gezondheidsproblemen van het maag-darmkanaal wijzen er duidelijk op dat je energie destructief beheert - je leven afbrekend in plaats van opbouwend. Leer energie te concentreren op positieve actie, en niet op destructieve emotionele uitbarstingen."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-strength-03','intensive-strength',3,1,'День: 3','[{"type":"video","vimeoId":"1149279297"},{"type":"text","markdown":"### Совет дня:\n\nПринимайте решения быстро! Пока вы колеблетесь, вы тратите энергию впустую, теряете авторитет в гразах окружающих, теряете вес в собственных глазах, упускаете момент. Принять решение - значит отсечь все остальные варианты и направить все ресурсы в одно русло. Даже неверное решение, за которым следует действие, обучение, корректировка, лучше, чем стагнация в бездействии с пережёвыванием сомнений."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1149279297"},{"type":"text","markdown":"### Tip of the day:\n\nMake decisions quickly! While you hesitate, you waste energy, lose authority in the eyes of others, lose weight in your own eyes, and miss the moment. To make a decision means to cut off all other options and direct all resources into one channel. Even a wrong decision followed by action, learning, correction, is better than stagnation in inaction with chewing over doubts."}],"de":[{"type":"video","vimeoId":"1149279297"},{"type":"text","markdown":"### Tipp des Tages:\n\nTreffen Sie Entscheidungen schnell! Während Sie zögern, verschwenden Sie Energie, verlieren Autorität in den Augen der Menschen um Sie herum, verlieren Gewicht in Ihren eigenen Augen, verpassen den Moment. Eine Entscheidung zu treffen bedeutet, alle anderen Optionen abzuschneiden und alle Ressourcen in ein einziges Bett zu lenken. Selbst eine falsche Entscheidung, auf die Handeln, Lernen und Korrektur folgen, ist besser als Stagnation im Nichtstun mit dem Wiederkäuen von Zweifeln."}],"fr":[{"type":"video","vimeoId":"1149279297"},{"type":"text","markdown":"### Conseil du jour :\n\nPrenez des décisions rapidement ! Tant que vous hésitez, vous gaspillez votre énergie, vous perdez de l’autorité aux yeux des autres, vous perdez de l’importance à vos propres yeux, vous manquez le moment. Prendre une décision, c’est retrancher toutes les autres options et diriger toutes les ressources dans un seul lit. Même une décision erronée, suivie d’une action, d’un apprentissage et d’un ajustement, vaut mieux que la stagnation dans l’inaction avec la rumination des doutes."}],"it":[{"type":"video","vimeoId":"1149279297"},{"type":"text","markdown":"### Consiglio del giorno:\n\nPrendete decisioni rapidamente! Finché esitate, spendete energia invano, perdete autorevolezza agli occhi degli altri, perdete peso ai vostri stessi occhi, lasciate sfuggire il momento. Prendere una decisione significa tagliare fuori tutte le altre opzioni e dirigere tutte le risorse in un unico canale. Anche una decisione sbagliata, seguita da azione, apprendimento, correzione, è migliore della stagnazione nell''inazione con il rimuginare i dubbi."}],"es":[{"type":"video","vimeoId":"1149279297"},{"type":"text","markdown":"### Consejo del día:\n\n¡Tomen decisiones rápidamente! Mientras dudan, gastan energía en vano, pierden autoridad a los ojos de los demás, pierden peso ante sus propios ojos, dejan pasar el momento. Tomar una decisión significa cortar todas las demás opciones y dirigir todos los recursos a un solo cauce. Incluso una decisión equivocada, seguida de acción, aprendizaje y corrección, es mejor que la estancación en la inacción rumiando dudas."}],"pt":[{"type":"video","vimeoId":"1149279297"},{"type":"text","markdown":"### Dica do dia:\n\nTome decisões rapidamente! Enquanto você hesita, gasta energia em vão, perde autoridade aos olhos dos outros, perde peso aos seus próprios olhos, perde o momento. Tomar uma decisão significa cortar todas as outras opções e direcionar todos os recursos para um único canal. Mesmo uma decisão errada, seguida de ação, aprendizado, correção, é melhor do que a estagnação na inação remoendo dúvidas."}],"nl":[{"type":"video","vimeoId":"1149279297"},{"type":"text","markdown":"### Tip van de dag:\n\nNeem snel beslissingen! Terwijl je aarzelt, verspil je energie, verlies je autoriteit in de ogen van anderen, verlies je gewicht in je eigen ogen en laat je het moment voorbijgaan. Een beslissing nemen betekent alle andere opties afsnijden en alle middelen in één bedding richten. Zelfs een verkeerde beslissing, gevolgd door actie, leren en bijsturen, is beter dan stagnatie in passiviteit met het herkauwen van twijfels."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-strength-04','intensive-strength',4,1,'День: 4','[{"type":"video","vimeoId":"1124397637"},{"type":"text","markdown":"### Совет дня:\n\nОбозначьте свои границы чётко и спокойно. Ваши границы - это не стены, чтобы отгородиться от мира, а понятные правила взаимодействия с вами. Они заявляются не криком и агрессией, а уверенным и последовательным поведением. Когда вы чётко знаете, где заканчиваетесь вы и начинается другой человек, вы перестаёте тратить энергию на защиту и обиды."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1124397637"},{"type":"text","markdown":"### Tip of the day:\n\nDefine your boundaries clearly and calmly. Your boundaries are not walls to fence yourself off from the world, but clear rules for interacting with you. They are declared not by shouting and aggression, but by confident and consistent behavior. When you clearly know where you end and another person begins, you stop spending energy on defense and resentments."}],"de":[{"type":"video","vimeoId":"1124397637"},{"type":"text","markdown":"### Tipp des Tages:\n\nMarkieren Sie Ihre Grenzen klar und ruhig. Ihre Grenzen sind keine Mauern, um sich von der Welt abzuschotten, sondern verständliche Regeln für die Interaktion mit Ihnen. Sie werden nicht durch Schreien und Aggression erklärt, sondern durch selbstsicheres und konsequentes Verhalten. Wenn Sie klar wissen, wo Sie enden und ein anderer Mensch beginnt, hören Sie auf, Energie für Verteidigung und Kränkungen zu verschwenden."}],"fr":[{"type":"video","vimeoId":"1124397637"},{"type":"text","markdown":"### Conseil du jour :\n\nDéfinissez vos limites clairement et calmement. Vos limites ne sont pas des murs pour vous isoler du monde, mais des règles claires d’interaction avec vous. Elles s’affirment non par le cri et l’agression, mais par un comportement assuré et cohérent. Lorsque vous savez clairement où vous vous terminez et où commence l’autre personne, vous cessez de dépenser votre énergie en défense et en ressentiment."}],"it":[{"type":"video","vimeoId":"1124397637"},{"type":"text","markdown":"### Consiglio del giorno:\n\nDefinite i vostri confini con chiarezza e calma. I vostri confini non sono mura per isolarsi dal mondo, ma regole chiare di interazione con voi. Si affermano non con urla e aggressività, ma con un comportamento sicuro e coerente. Quando sapete chiaramente dove finite voi e dove inizia un''altra persona, smettete di spendere energia in difesa e risentimenti."}],"es":[{"type":"video","vimeoId":"1124397637"},{"type":"text","markdown":"### Consejo del día:\n\nDefinan sus límites con claridad y calma. Sus límites no son muros para aislarse del mundo, sino reglas claras de interacción con ustedes. No se declaran con gritos y agresividad, sino con una conducta segura y coherente. Cuando saben con claridad dónde terminan ustedes y dónde empieza otra persona, dejan de gastar energía en defensa y resentimientos."}],"pt":[{"type":"video","vimeoId":"1124397637"},{"type":"text","markdown":"### Dica do dia:\n\nDefina seus limites de forma clara e tranquila. Seus limites não são muros para se isolar do mundo, mas regras compreensíveis de interação com você. Eles são declarados não por grito e agressão, mas por comportamento confiante e consistente. Quando você sabe claramente onde você termina e onde outra pessoa começa, você deixa de gastar energia com defesa e mágoas."}],"nl":[{"type":"video","vimeoId":"1124397637"},{"type":"text","markdown":"### Tip van de dag:\n\nGeef je grenzen duidelijk en rustig aan. Je grenzen zijn geen muren om je van de wereld af te sluiten, maar duidelijke regels voor de omgang met jou. Ze worden niet aangegeven met geschreeuw en agressie, maar met zelfverzekerd en consistent gedrag. Wanneer je duidelijk weet waar jij ophoudt en de ander begint, stop je met energie te verspillen aan verdediging en gekwetstheid."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-strength-05','intensive-strength',5,1,'День: 5','[{"type":"video","vimeoId":"1152831012"},{"type":"text","markdown":"### Совет дня:\n\nУправляйте своим телом. Тело - это первая территория, над которой вы имеете власть. Регулярные физические нагрузки, дисциплина в питании и режиме дня - это не просто забота о здоровье, но также ежедневная тренировка вашей воли и способности управлять \"реальностью\"."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1152831012"},{"type":"text","markdown":"### Tip of the day:\n\nManage your body. The body is the first territory over which you have power. Regular physical activity, discipline in nutrition and daily routine are not simply care for health, but also a daily training of your will and ability to manage “reality”."}],"de":[{"type":"video","vimeoId":"1152831012"},{"type":"text","markdown":"### Tipp des Tages:\n\nSteuern Sie Ihren Körper. Der Körper ist das erste Territorium, über das Sie Macht haben. Regelmäßige körperliche Belastung, Disziplin bei Ernährung und Tagesablauf sind nicht nur Gesundheitspflege, sondern auch ein tägliches Training Ihres Willens und Ihrer Fähigkeit, die „Realität“ zu steuern."}],"fr":[{"type":"video","vimeoId":"1152831012"},{"type":"text","markdown":"### Conseil du jour :\n\nMaîtrisez votre corps. Le corps est le premier territoire sur lequel vous avez pouvoir. Des activités physiques régulières, la discipline dans l’alimentation et le rythme quotidien ne sont pas seulement un soin de la santé, mais aussi un entraînement quotidien de votre volonté et de votre capacité à maîtriser la « réalité »."}],"it":[{"type":"video","vimeoId":"1152831012"},{"type":"text","markdown":"### Consiglio del giorno:\n\nGestite il vostro corpo. Il corpo è il primo territorio su cui avete potere. Regolari attività fisiche, disciplina nell''alimentazione e nella routine quotidiana - non sono solo cura della salute, ma anche allenamento quotidiano della vostra volontà e della capacità di gestire la \"realtà\"."}],"es":[{"type":"video","vimeoId":"1152831012"},{"type":"text","markdown":"### Consejo del día:\n\nGestionen su cuerpo. El cuerpo es el primer territorio sobre el que tienen poder. Las cargas físicas regulares, la disciplina en la alimentación y en la rutina diaria no son solo cuidado de la salud, sino también un entrenamiento diario de su voluntad y de la capacidad de gestionar la \"realidad\"."}],"pt":[{"type":"video","vimeoId":"1152831012"},{"type":"text","markdown":"### Dica do dia:\n\nGerencie seu corpo. O corpo é o primeiro território sobre o qual você tem poder. Atividades físicas regulares, disciplina na alimentação e na rotina diária não são apenas cuidado com a saúde, mas também um treinamento diário da sua vontade e da capacidade de gerenciar a “realidade”."}],"nl":[{"type":"video","vimeoId":"1152831012"},{"type":"text","markdown":"### Tip van de dag:\n\nBeheer je lichaam. Het lichaam is het eerste territorium waarover je macht hebt. Regelmatige lichaamsbeweging, discipline in voeding en dagindeling - dat is niet alleen zorg voor gezondheid, maar ook een dagelijkse training van je wil en je vermogen om «realiteit» te beheren."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-strength-06','intensive-strength',6,1,'День: 6','[{"type":"video","vimeoId":"1153577879"},{"type":"text","markdown":"### Совет дня:\n\nСоедините слово и дело. Ваше слово должно обрести вес. Если вы сказали - то вы обязательно и сделали! Это создаёт вам репутацию в глазах окружающих и, что важнее, формирует ваш внутренний стержень. Особенно важны ваши обещания. Не давайте пустых обещаний ни себе, ни другим. Избегайте двусмысленностей, когда может возникнуть ощущение, что вы пообещали то, что на самом деле выполнять не собираетесь. В современном обществе прививается идея, что обманывать (лохов) - это нормально и таков путь к успеху. Но чувствуйте тонкую разницу между обманом и хитростью. Не совершайте действий, которые приводят к карме, которую вы себе не желаете."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1153577879"},{"type":"text","markdown":"### Tip of the day:\n\nUnite word and deed. Your word must gain weight. If you said it, then you definitely did it! This creates a reputation for you in the eyes of others and, more importantly, forms your inner core. Your promises are especially important. Do not make empty promises either to yourself or to others. Avoid ambiguities when a feeling may arise that you promised something you actually do not intend to do. In modern society, the idea is instilled that deceiving (suckers) is normal and that this is the path to success. But feel the subtle difference between deception and cunning. Do not perform actions that lead to karma you do not wish for yourself."}],"de":[{"type":"video","vimeoId":"1153577879"},{"type":"text","markdown":"### Tipp des Tages:\n\nVerbinden Sie Wort und Tat. Ihr Wort muss Gewicht erlangen. Wenn Sie etwas gesagt haben, dann haben Sie es unbedingt auch getan! Das verschafft Ihnen eine Reputation in den Augen der Menschen um Sie herum und, was wichtiger ist, formt Ihren inneren Kern. Besonders wichtig sind Ihre Versprechen. Geben Sie weder sich selbst noch anderen leere Versprechen. Vermeiden Sie Zweideutigkeiten, wenn der Eindruck entstehen kann, Sie hätten etwas versprochen, das Sie in Wirklichkeit nicht zu erfüllen beabsichtigen. In der modernen Gesellschaft wird die Idee vermittelt, dass es normal sei, (Trottel) zu betrügen, und dass dies der Weg zum Erfolg sei. Aber spüren Sie den feinen Unterschied zwischen Betrug und List. Begehen Sie keine Handlungen, die zu Karma führen, das Sie sich selbst nicht wünschen."}],"fr":[{"type":"video","vimeoId":"1153577879"},{"type":"text","markdown":"### Conseil du jour :\n\nUnissez la parole et l’action. Votre parole doit acquérir du poids. Si vous avez dit quelque chose, alors vous l’avez obligatoirement fait ! Cela vous crée une réputation aux yeux des autres et, plus important encore, forme votre axe intérieur. Vos promesses sont particulièrement importantes. Ne faites pas de promesses vaines, ni à vous-même ni aux autres. Évitez les ambiguïtés lorsqu’une impression peut naître que vous avez promis ce que, en réalité, vous n’avez pas l’intention d’accomplir. Dans la société moderne, l’idée est inculquée que tromper (les naïfs) est normal et que tel est le chemin vers le succès. Mais ressentez la fine différence entre la tromperie et la ruse. N’accomplissez pas d’actions qui conduisent au karma que vous ne souhaitez pas pour vous-même."}],"it":[{"type":"video","vimeoId":"1153577879"},{"type":"text","markdown":"### Consiglio del giorno:\n\nUnite parola e azione. La vostra parola deve acquisire peso. Se avete detto - allora avete certamente anche fatto! Questo vi crea una reputazione agli occhi degli altri e, cosa più importante, forma la vostra struttura interiore. Le vostre promesse sono particolarmente importanti. Non fate promesse vuote né a voi stessi né agli altri. Evitate ambiguità in cui possa nascere l''impressione che abbiate promesso ciò che in realtà non intendete mantenere. Nella società moderna si inculca l''idea che imbrogliare (gli sprovveduti) - sia normale e che questa sia la via al successo. Ma sentite la sottile differenza tra inganno e astuzia. Non compite azioni che portano a un karma che non desiderate per voi stessi."}],"es":[{"type":"video","vimeoId":"1153577879"},{"type":"text","markdown":"### Consejo del día:\n\nUnan la palabra y el hecho. Su palabra debe adquirir peso. Si dijeron algo, ¡entonces sin falta también lo hicieron! Esto les crea reputación a los ojos de los demás y, lo que es más importante, forma su núcleo interno. Sus promesas son especialmente importantes. No den promesas vacías ni a sí mismos ni a los demás. Eviten las ambigüedades cuando pueda surgir la sensación de que prometieron algo que en realidad no tienen intención de cumplir. En la sociedad moderna se inculca la idea de que engañar (a los tontos) es normal y que ese es el camino al éxito. Pero sientan la sutil diferencia entre el engaño y la astucia. No realicen acciones que conduzcan a un karma que no desean para ustedes."}],"pt":[{"type":"video","vimeoId":"1153577879"},{"type":"text","markdown":"### Dica do dia:\n\nUna palavra e ação. Sua palavra deve ganhar peso. Se você disse - então você certamente também fez! Isso cria sua reputação aos olhos dos outros e, o que é mais importante, forma seu núcleo interior. Suas promessas são especialmente importantes. Não faça promessas vazias nem a si mesmo nem aos outros. Evite ambiguidades, quando pode surgir a sensação de que você prometeu algo que na verdade não pretendia cumprir. Na sociedade moderna é incutida a ideia de que enganar (os otários) é normal e que esse é o caminho para o sucesso. Mas sinta a sutil diferença entre engano e astúcia. Não cometa ações que levem ao carma que você não deseja para si."}],"nl":[{"type":"video","vimeoId":"1153577879"},{"type":"text","markdown":"### Tip van de dag:\n\nVerbind woord en daad. Je woord moet gewicht krijgen. Als je het gezegd hebt, heb je het ook beslist gedaan! Dat schept een reputatie in de ogen van anderen en, belangrijker, het vormt je innerlijke ruggengraat. Je beloften zijn bijzonder belangrijk. Geef geen loze beloften, niet aan jezelf en niet aan anderen. Vermijd dubbelzinnigheden waarbij de indruk kan ontstaan dat je iets hebt beloofd dat je eigenlijk niet van plan bent na te komen. In de moderne samenleving wordt het idee ingeprent dat bedriegen (van sukkels) normaal is en dat dat de weg naar succes is. Maar voel het subtiele verschil tussen bedrog en slimheid. Onderneem geen daden die leiden tot karma dat je voor jezelf niet wenst."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-strength-07','intensive-strength',7,1,'День: 7','[{"type":"video","vimeoId":"1139216354"},{"type":"text","markdown":"### Совет дня:\n\nСоздавайте союзы, основанные на взаимной выгоде и уважении.В одиночку можно идти быстро, но вместе - дальше. Ищите союзников, чьи цели и ценности совпадают с вашими. Сильные союзы строятся не на дружбе, а на общем интересе и способности усиливать друг друга."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1139216354"},{"type":"text","markdown":"### Tip of the day:\n\nCreate alliances based on mutual benefit and respect. Alone you can go fast, but together you can go farther. Seek allies whose goals and values coincide with yours. Strong alliances are built not on friendship, but on common interest and the ability to strengthen each other."}],"de":[{"type":"video","vimeoId":"1139216354"},{"type":"text","markdown":"### Tipp des Tages:\n\nSchaffen Sie Allianzen, die auf gegenseitigem Nutzen und Respekt beruhen. Allein kann man schnell gehen, aber gemeinsam – weiter. Suchen Sie Verbündete, deren Ziele und Werte mit Ihren übereinstimmen. Starke Allianzen bauen nicht auf Freundschaft, sondern auf gemeinsamen Interessen und der Fähigkeit, einander zu stärken."}],"fr":[{"type":"video","vimeoId":"1139216354"},{"type":"text","markdown":"### Conseil du jour :\n\nCréez des alliances fondées sur l’intérêt mutuel et le respect. Seul, on peut aller vite, mais ensemble, on va plus loin. Cherchez des alliés dont les buts et les valeurs coïncident avec les vôtres. Les alliances fortes ne se construisent pas sur l’amitié, mais sur l’intérêt commun et la capacité à se renforcer mutuellement."}],"it":[{"type":"video","vimeoId":"1139216354"},{"type":"text","markdown":"### Consiglio del giorno:\n\nCreate alleanze basate sul vantaggio reciproco e sul rispetto. Da soli si può andare veloci, ma insieme - più lontano. Cercate alleati i cui obiettivi e valori coincidano con i vostri. Le alleanze forti si costruiscono non sull''amicizia, ma sull''interesse comune e sulla capacità di rafforzarsi a vicenda."}],"es":[{"type":"video","vimeoId":"1139216354"},{"type":"text","markdown":"### Consejo del día:\n\nCreen alianzas basadas en el beneficio mutuo y el respeto.En solitario se puede ir rápido, pero juntos se llega más lejos. Busquen aliados cuyos objetivos y valores coincidan con los suyos. Las alianzas fuertes no se construyen sobre la amistad, sino sobre el interés común y la capacidad de potenciarse mutuamente."}],"pt":[{"type":"video","vimeoId":"1139216354"},{"type":"text","markdown":"### Dica do dia:\n\nCrie alianças baseadas em benefício mútuo e respeito. Sozinho pode-se ir rápido, mas juntos - mais longe. Procure aliados cujos objetivos e valores coincidam com os seus. Alianças fortes não se constroem sobre amizade, mas sobre interesse comum e capacidade de fortalecer uns aos outros."}],"nl":[{"type":"video","vimeoId":"1139216354"},{"type":"text","markdown":"### Tip van de dag:\n\nSluit allianties die gebaseerd zijn op wederzijds voordeel en respect. Alleen kun je snel gaan, maar samen kom je verder. Zoek bondgenoten wier doelen en waarden overeenkomen met de jouwe. Sterke allianties worden niet op vriendschap gebouwd, maar op gemeenschappelijk belang en het vermogen om elkaar te versterken."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-strength-08','intensive-strength',8,1,'День: 8','[{"type":"video","vimeoId":"1140656950"},{"type":"text","markdown":"### Совет дня:\n\nПреобразуйте любые свои эмоции в топливо. Страх, гнев, зависть - всё это мощные источники энергии. Не подавляйте их, а учитесь трансформировать. Страх может стать топливом для смелости, гнев - для решительного действия, зависть - для постановки более амбициозных целей."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1140656950"},{"type":"text","markdown":"### Tip of the day:\n\nConvert any of your emotions into fuel. Fear, anger, envy - all of these are powerful sources of energy. Do not suppress them, but learn to transform them. Fear can become fuel for courage, anger for decisive action, envy for setting more ambitious goals."}],"de":[{"type":"video","vimeoId":"1140656950"},{"type":"text","markdown":"### Tipp des Tages:\n\nVerwandeln Sie alle Ihre Emotionen in Treibstoff. Angst, Zorn, Neid – all das sind mächtige Energiequellen. Unterdrücken Sie sie nicht, sondern lernen Sie, sie zu transformieren. Angst kann zum Treibstoff für Mut werden, Zorn für entschlossenes Handeln, Neid für das Setzen ehrgeizigerer Ziele."}],"fr":[{"type":"video","vimeoId":"1140656950"},{"type":"text","markdown":"### Conseil du jour :\n\nTransformez toutes vos émotions en carburant. La peur, la colère, l’envie – tout cela sont de puissantes sources d’énergie. Ne les réprimez pas, mais apprenez à les transformer. La peur peut devenir un carburant pour le courage, la colère – pour une action décisive, l’envie – pour se fixer des objectifs plus ambitieux."}],"it":[{"type":"video","vimeoId":"1140656950"},{"type":"text","markdown":"### Consiglio del giorno:\n\nTrasformate qualsiasi vostra emozione in combustibile. Paura, rabbia, invidia - tutte queste sono potenti fonti di energia. Non sopprimetele, ma imparate a trasformarle. La paura può diventare combustibile per il coraggio, la rabbia - per un''azione decisa, l''invidia - per porsi obiettivi più ambiziosi."}],"es":[{"type":"video","vimeoId":"1140656950"},{"type":"text","markdown":"### Consejo del día:\n\nTransformen cualquiera de sus emociones en combustible. El miedo, la ira, la envidia: todo ello son poderosas fuentes de energía. No las repriman, sino aprendan a transformarlas. El miedo puede convertirse en combustible para la valentía, la ira en combustible para una acción decidida, la envidia en combustible para plantear objetivos más ambiciosos."}],"pt":[{"type":"video","vimeoId":"1140656950"},{"type":"text","markdown":"### Dica do dia:\n\nTransforme quaisquer de suas emoções em combustível. Medo, raiva, inveja - tudo isso são poderosas fontes de energia. Não as reprima, mas aprenda a transformá-las. O medo pode se tornar combustível para a coragem, a raiva - para a ação decidida, a inveja - para estabelecer metas mais ambiciosas."}],"nl":[{"type":"video","vimeoId":"1140656950"},{"type":"text","markdown":"### Tip van de dag:\n\nZet al je emoties om in brandstof. Angst, woede, afgunst - het zijn allemaal krachtige energiebronnen. Onderdruk ze niet, maar leer ze te transformeren. Angst kan brandstof worden voor moed, woede voor vastberaden handelen, afgunst voor het stellen van ambitieuzere doelen."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-strength-09','intensive-strength',9,1,'День: 9','[{"type":"video","vimeoId":"1146530344"},{"type":"text","markdown":"### Совет дня:\n\nОсвойте искусство говорить «нет». Твёрдое и спокойное «нет» чужим ожиданиям - это «да» вашим собственным целям и приоритетам. Отказывая в том, что вам не подходит, вы сохраняете свои ресурсы - время, энергию, внимание - для главного. Делайте это без чувства вины, как простой акт управления своей жизнью."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1146530344"},{"type":"text","markdown":"### Tip of the day:\n\nMaster the art of saying “no”. A firm and calm “no” to others’ expectations is a “yes” to your own goals and priorities. By refusing what does not suit you, you preserve your resources - time, energy, attention - for what is important. Do this without a sense of guilt, as a simple act of managing your life."}],"de":[{"type":"video","vimeoId":"1146530344"},{"type":"text","markdown":"### Tipp des Tages:\n\nMeistern Sie die Kunst, „nein“ zu sagen. Ein festes und ruhiges „nein“ zu den Erwartungen anderer ist ein „ja“ zu Ihren eigenen Zielen und Prioritäten. Indem Sie ablehnen, was Ihnen nicht passt, bewahren Sie Ihre Ressourcen – Zeit, Energie, Aufmerksamkeit – für das Wesentliche. Tun Sie dies ohne Schuldgefühl, als einfachen Akt der Steuerung Ihres Lebens."}],"fr":[{"type":"video","vimeoId":"1146530344"},{"type":"text","markdown":"### Conseil du jour :\n\nMaîtrisez l’art de dire « non ». Un « non » ferme et calme aux attentes des autres est un « oui » à vos propres buts et priorités. En refusant ce qui ne vous convient pas, vous préservez vos ressources – temps, énergie, attention – pour l’essentiel. Faites-le sans sentiment de culpabilité, comme un simple acte de gestion de votre vie."}],"it":[{"type":"video","vimeoId":"1146530344"},{"type":"text","markdown":"### Consiglio del giorno:\n\nPadroneggiate l''arte di dire «no». Un «no» fermo e calmo alle aspettative altrui è un «sì» ai vostri obiettivi e priorità. Rifiutando ciò che non vi si addice, conservate le vostre risorse - tempo, energia, attenzione - per ciò che è importante. Fatelo senza senso di colpa, come un semplice atto di gestione della propria vita."}],"es":[{"type":"video","vimeoId":"1146530344"},{"type":"text","markdown":"### Consejo del día:\n\nDomien el arte de decir «no». Un «no» firme y tranquilo a las expectativas ajenas es un «sí» a sus propios objetivos y prioridades. Al negarse a lo que no les conviene, conservan sus recursos (tiempo, energía, atención) para lo principal. Háganlo sin sentimiento de culpa, como un simple acto de gestión de su vida."}],"pt":[{"type":"video","vimeoId":"1146530344"},{"type":"text","markdown":"### Dica do dia:\n\nDomine a arte de dizer “não”. Um “não” firme e tranquilo às expectativas alheias é um “sim” aos seus próprios objetivos e prioridades. Ao recusar o que não lhe convém, você preserva seus recursos - tempo, energia, atenção - para o principal. Faça isso sem sentimento de culpa, como um simples ato de gestão da sua vida."}],"nl":[{"type":"video","vimeoId":"1146530344"},{"type":"text","markdown":"### Tip van de dag:\n\nBeheers de kunst om «nee» te zeggen. Een stevig en rustig «nee» tegen andermans verwachtingen is een «ja» tegen je eigen doelen en prioriteiten. Door te weigeren wat niet bij je past, behoud je je middelen - tijd, energie, aandacht - voor het belangrijkste. Doe dit zonder schuldgevoel, als een eenvoudige daad van het beheren van je leven."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-strength-10','intensive-strength',10,1,'День: 10','[{"type":"video","vimeoId":"1121571478"},{"type":"text","markdown":"### Совет дня:\n\nЦените ошибки как навигаторов. Ошибка - это не провал, а ценная обратная связь от реальности. Она показывает, что именно не работает, и позволяет скорректировать курс. Боязнь ошибок парализует волю; готовность их совершать и учиться на них - ускоряет движение к цели в разы."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1121571478"},{"type":"text","markdown":"### Tip of the day:\n\nValue mistakes as navigators. A mistake is not a failure but valuable feedback from reality. It shows what exactly is not working and allows you to correct course. Fear of mistakes paralyzes the will; readiness to make them and learn from them accelerates movement toward the goal many times over."}],"de":[{"type":"video","vimeoId":"1121571478"},{"type":"text","markdown":"### Tipp des Tages:\n\nSchätzen Sie Fehler als Navigatoren. Ein Fehler ist kein Scheitern, sondern wertvolles Feedback von der Realität. Er zeigt, was genau nicht funktioniert, und ermöglicht es, den Kurs zu korrigieren. Die Angst vor Fehlern lähmt den Willen; die Bereitschaft, sie zu machen und aus ihnen zu lernen, beschleunigt die Bewegung zum Ziel um ein Vielfaches."}],"fr":[{"type":"video","vimeoId":"1121571478"},{"type":"text","markdown":"### Conseil du jour :\n\nAppréciez les erreurs comme des navigateurs. Une erreur n’est pas un échec, mais un précieux retour d’information de la réalité. Elle montre ce qui précisément ne fonctionne pas et permet de corriger le cap. La peur des erreurs paralyse la volonté ; la disposition à en commettre et à en tirer des leçons accélère plusieurs fois le mouvement vers le but."}],"it":[{"type":"video","vimeoId":"1121571478"},{"type":"text","markdown":"### Consiglio del giorno:\n\nValorizzate gli errori come navigatori. Un errore non è un fallimento, ma un prezioso feedback dalla realtà. Esso mostra che cosa esattamente non funziona e permette di correggere la rotta. La paura degli errori paralizza la volontà; la disponibilità a commetterli e a imparare da essi - accelera di molto il movimento verso l''obiettivo."}],"es":[{"type":"video","vimeoId":"1121571478"},{"type":"text","markdown":"### Consejo del día:\n\nValoren los errores como navegantes. Un error no es un fracaso, sino una valiosa retroalimentación de la realidad. Muestra qué exactamente no funciona y permite corregir el rumbo. El miedo a los errores paraliza la voluntad; la disposición a cometerlos y aprender de ellos acelera muchas veces el movimiento hacia el objetivo."}],"pt":[{"type":"video","vimeoId":"1121571478"},{"type":"text","markdown":"### Dica do dia:\n\nValorize os erros como navegadores. O erro não é um fracasso, mas um valioso feedback da realidade. Ele mostra o que exatamente não funciona e permite corrigir o rumo. O medo de erros paralisa a vontade; a disposição de cometê-los e aprender com eles acelera em muito o movimento em direção ao objetivo."}],"nl":[{"type":"video","vimeoId":"1121571478"},{"type":"text","markdown":"### Tip van de dag:\n\nWaardeer fouten als navigatie-instrumenten. Een fout is geen mislukking, maar waardevolle feedback van de realiteit. Ze laat zien wat precies niet werkt en stelt je in staat de koers bij te sturen. Angst voor fouten verlamt de wil; bereidheid om ze te maken en ervan te leren versnelt de beweging naar het doel vele malen."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-strength-11','intensive-strength',11,1,'День: 11','[{"type":"video","vimeoId":"1111204587"},{"type":"text","markdown":"### Совет дня:\n\nРазвивайте волю как мышцу - через усилие. Воля тренируется преодолением. Каждый раз, когда вы делаете то, что нужно, вместо того, что хочется в моменте, ваш внутренний стержень становится крепче. Начинайте с малого - и постепенно увеличивайте нагрузку."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1111204587"},{"type":"text","markdown":"### Tip of the day:\n\nDevelop will like a muscle - through effort. Will is trained by overcoming. Every time you do what is needed instead of what you want in the moment, your inner core becomes stronger. Start with small things - and gradually increase the load."}],"de":[{"type":"video","vimeoId":"1111204587"},{"type":"text","markdown":"### Tipp des Tages:\n\nEntwickeln Sie den Willen wie einen Muskel – durch Anstrengung. Der Wille wird durch Überwindung trainiert. Jedes Mal, wenn Sie tun, was nötig ist, statt dessen, wonach Ihnen im Moment ist, wird Ihr innerer Kern stärker. Beginnen Sie mit Kleinem – und steigern Sie die Belastung allmählich."}],"fr":[{"type":"video","vimeoId":"1111204587"},{"type":"text","markdown":"### Conseil du jour :\n\nDéveloppez la volonté comme un muscle – par l’effort. La volonté s’entraîne par le dépassement. Chaque fois que vous faites ce qui est nécessaire au lieu de ce que vous voulez sur le moment, votre axe intérieur devient plus solide. Commencez par de petites choses – et augmentez progressivement la charge."}],"it":[{"type":"video","vimeoId":"1111204587"},{"type":"text","markdown":"### Consiglio del giorno:\n\nSviluppate la volontà come un muscolo - attraverso lo sforzo. La volontà si allena superando ostacoli. Ogni volta che fate ciò che è necessario invece di ciò che desiderate nel momento, la vostra struttura interiore diventa più forte. Iniziate dal poco - e aumentate gradualmente il carico."}],"es":[{"type":"video","vimeoId":"1111204587"},{"type":"text","markdown":"### Consejo del día:\n\nDesarrollen la voluntad como un músculo: mediante el esfuerzo. La voluntad se entrena con la superación. Cada vez que hacen lo que hace falta en lugar de lo que les apetece en el momento, su núcleo interno se vuelve más fuerte. Empiecen por lo pequeño y aumenten gradualmente la carga."}],"pt":[{"type":"video","vimeoId":"1111204587"},{"type":"text","markdown":"### Dica do dia:\n\nDesenvolva a vontade como um músculo - por meio do esforço. A vontade é treinada pela superação. Cada vez que você faz o que é necessário, em vez do que quer no momento, seu núcleo interior se torna mais forte. Comece com pouco - e aumente gradualmente a carga."}],"nl":[{"type":"video","vimeoId":"1111204587"},{"type":"text","markdown":"### Tip van de dag:\n\nOntwikkel je wil als een spier - door inspanning. De wil wordt getraind door obstakels te overwinnen. Elke keer wanneer je doet wat nodig is in plaats van wat je op dat moment wilt, wordt je innerlijke ruggengraat sterker. Begin klein - en verhoog geleidelijk de belasting."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-strength-12','intensive-strength',12,1,'День: 12','[{"type":"video","vimeoId":"1117344766"},{"type":"text","markdown":"### Совет дня:\n\nУважайте противника и учитесь у него. В любом конфликте, споре или конкуренции ваш оппонент - это ваш лучший учитель. Он безжалостно подсвечивает ваши слабые места. Сохраняйте холодную голову, изучайте его стратегию и используйте это знание для собственного роста."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1117344766"},{"type":"text","markdown":"### Tip of the day:\n\nRespect the opponent and learn from him. In any conflict, dispute or competition, your opponent is your best teacher. He ruthlessly highlights your weak spots. Keep a cool head, study his strategy and use this knowledge for your own growth."}],"de":[{"type":"video","vimeoId":"1117344766"},{"type":"text","markdown":"### Tipp des Tages:\n\nRespektieren Sie den Gegner und lernen Sie von ihm. In jedem Konflikt, Streit oder Wettbewerb ist Ihr Opponent Ihr bester Lehrer. Er beleuchtet gnadenlos Ihre Schwachstellen. Bewahren Sie einen kühlen Kopf, studieren Sie seine Strategie und nutzen Sie dieses Wissen für Ihr eigenes Wachstum."}],"fr":[{"type":"video","vimeoId":"1117344766"},{"type":"text","markdown":"### Conseil du jour :\n\nRespectez l’adversaire et apprenez de lui. Dans tout conflit, débat ou concurrence, votre opposant est votre meilleur professeur. Il met impitoyablement en lumière vos points faibles. Gardez la tête froide, étudiez sa stratégie et utilisez cette connaissance pour votre propre croissance."}],"it":[{"type":"video","vimeoId":"1117344766"},{"type":"text","markdown":"### Consiglio del giorno:\n\nRispettate l''avversario e imparate da lui. In qualsiasi conflitto, disputa o competizione il vostro oppositore è il vostro miglior insegnante. Egli illumina senza pietà i vostri punti deboli. Mantenete la mente fredda, studiate la sua strategia e usate questa conoscenza per la vostra crescita."}],"es":[{"type":"video","vimeoId":"1117344766"},{"type":"text","markdown":"### Consejo del día:\n\nRespeten al adversario y aprendan de él. En cualquier conflicto, discusión o competencia, su oponente es su mejor maestro. Ilumina sin piedad sus puntos débiles. Mantengan la cabeza fría, estudien su estrategia y usen ese conocimiento para su propio crecimiento."}],"pt":[{"type":"video","vimeoId":"1117344766"},{"type":"text","markdown":"### Dica do dia:\n\nRespeite o adversário e aprenda com ele. Em qualquer conflito, discussão ou competição, seu oponente é seu melhor professor. Ele ilumina impiedosamente seus pontos fracos. Mantenha a cabeça fria, estude sua estratégia e use esse conhecimento para seu próprio crescimento."}],"nl":[{"type":"video","vimeoId":"1117344766"},{"type":"text","markdown":"### Tip van de dag:\n\nRespecteer de tegenstander en leer van hem. In elk conflict, debat of elke competitie is je tegenstander je beste leraar. Hij belicht genadeloos je zwakke plekken. Houd een koel hoofd, bestudeer zijn strategie en gebruik die kennis voor je eigen groei."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-strength-13','intensive-strength',13,1,'День: 13','[{"type":"video","vimeoId":"1114786790"},{"type":"text","markdown":"### Совет дня:\n\nЗавершайте начатое. Каждое незавершённое дело - это утечка энергии и подрыв веры в себя. Доводите проекты до логического конца, даже если результат оказался не таким, как вы ожидали. Цикл должен быть замкнут, чтобы освободить жизненное пространство для новых начинаний."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1114786790"},{"type":"text","markdown":"### Tip of the day:\n\nFinish what you start. Every unfinished task is a leak of energy and an undermining of faith in yourself. Bring projects to their logical end, even if the result turned out not as you expected. The cycle must be closed in order to free life space for new beginnings."}],"de":[{"type":"video","vimeoId":"1114786790"},{"type":"text","markdown":"### Tipp des Tages:\n\nBeenden Sie, was Sie begonnen haben. Jede unvollendete Sache ist ein Energieleck und untergräbt den Glauben an sich selbst. Bringen Sie Projekte zu einem logischen Ende, auch wenn das Ergebnis nicht so ausgefallen ist, wie Sie erwartet haben. Der Zyklus muss geschlossen werden, um Lebensraum für neue Vorhaben freizusetzen."}],"fr":[{"type":"video","vimeoId":"1114786790"},{"type":"text","markdown":"### Conseil du jour :\n\nAchevez ce que vous avez commencé. Chaque affaire inachevée est une fuite d’énergie et une atteinte à la confiance en vous. Menez les projets jusqu’à leur conclusion logique, même si le résultat s’est révélé différent de ce que vous attendiez. Le cycle doit être clos afin de libérer de l’espace de vie pour de nouveaux commencements."}],"it":[{"type":"video","vimeoId":"1114786790"},{"type":"text","markdown":"### Consiglio del giorno:\n\nPortate a termine ciò che avete iniziato. Ogni questione incompiuta è una perdita di energia e un indebolimento della fiducia in sé. Portate i progetti fino alla loro conclusione logica, anche se il risultato si è rivelato diverso da come vi aspettavate. Il ciclo deve essere chiuso per liberare spazio vitale per nuovi inizi."}],"es":[{"type":"video","vimeoId":"1114786790"},{"type":"text","markdown":"### Consejo del día:\n\nTerminen lo que han empezado. Cada asunto inconcluso es una fuga de energía y un socavamiento de la fe en sí mismos. Lleven los proyectos hasta su final lógico, incluso si el resultado no fue como esperaban. El ciclo debe cerrarse para liberar espacio vital para nuevos comienzos."}],"pt":[{"type":"video","vimeoId":"1114786790"},{"type":"text","markdown":"### Dica do dia:\n\nTermine o que começou. Cada assunto inacabado é um vazamento de energia e um abalo da fé em si mesmo. Leve os projetos até o fim lógico, mesmo que o resultado tenha sido diferente do que você esperava. O ciclo deve ser fechado, para liberar espaço vital para novos começos."}],"nl":[{"type":"video","vimeoId":"1114786790"},{"type":"text","markdown":"### Tip van de dag:\n\nMaak af waaraan je begonnen bent. Elke onvoltooide zaak is een energielek en ondermijnt je zelfvertrouwen. Breng projecten tot een logisch einde, zelfs als het resultaat anders is uitgevallen dan je verwachtte. De cyclus moet worden gesloten om levensruimte vrij te maken voor nieuwe initiatieven."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-strength-14','intensive-strength',14,1,'День: 14','[{"type":"video","vimeoId":"1123785841"},{"type":"text","markdown":"### Совет дня:\n\nБерите ответственность за тех, кто идёт за вами. Если вы взяли на себя роль лидера, вы отвечаете не только за результат, но и за своих людей. Защищайте их, создавайте условия для их роста, будьте для них предсказуемой и надёжной опорой. Их сила становится вашей силой."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1123785841"},{"type":"text","markdown":"### Tip of the day:\n\nTake responsibility for those who follow you. If you have taken on the role of leader, you are responsible not only for the result, but also for your people. Protect them, create conditions for their growth, be a predictable and reliable support for them. Their strength becomes your strength."}],"de":[{"type":"video","vimeoId":"1123785841"},{"type":"text","markdown":"### Tipp des Tages:\n\nÜbernehmen Sie Verantwortung für diejenigen, die Ihnen folgen. Wenn Sie die Rolle eines Leaders übernommen haben, sind Sie nicht nur für das Ergebnis, sondern auch für Ihre Menschen verantwortlich. Beschützen Sie sie, schaffen Sie Bedingungen für ihr Wachstum, seien Sie für sie eine vorhersehbare und verlässliche Stütze. Ihre Kraft wird zu Ihrer Kraft."}],"fr":[{"type":"video","vimeoId":"1123785841"},{"type":"text","markdown":"### Conseil du jour :\n\nPrenez la responsabilité de ceux qui marchent derrière vous. Si vous avez assumé le rôle de leader, vous répondez non seulement du résultat, mais aussi de vos gens. Protégez-les, créez les conditions de leur croissance, soyez pour eux un soutien prévisible et fiable. Leur force devient votre force."}],"it":[{"type":"video","vimeoId":"1123785841"},{"type":"text","markdown":"### Consiglio del giorno:\n\nAssumete la responsabilità per coloro che camminano dietro di voi. Se avete assunto il ruolo di leader, siete responsabili non solo del risultato, ma anche delle vostre persone. Proteggetele, create condizioni per la loro crescita, siate per loro un punto di riferimento prevedibile e affidabile. La loro forza diventa la vostra forza."}],"es":[{"type":"video","vimeoId":"1123785841"},{"type":"text","markdown":"### Consejo del día:\n\nAsuman la responsabilidad por quienes van detrás de ustedes. Si han asumido el papel de líder, responden no solo por el resultado, sino también por su gente. Protéjanlos, creen condiciones para su crecimiento, sean para ellos un apoyo predecible y fiable. Su fuerza se convierte en su fuerza."}],"pt":[{"type":"video","vimeoId":"1123785841"},{"type":"text","markdown":"### Dica do dia:\n\nAssuma a responsabilidade por aqueles que seguem você. Se você assumiu o papel de líder, você responde não apenas pelo resultado, mas também pelas suas pessoas. Proteja-as, crie condições para o crescimento delas, seja para elas um apoio previsível e confiável. A força delas se torna sua força."}],"nl":[{"type":"video","vimeoId":"1123785841"},{"type":"text","markdown":"### Tip van de dag:\n\nNeem verantwoordelijkheid voor hen die je volgen. Als je de rol van leider op je hebt genomen, ben je niet alleen verantwoordelijk voor het resultaat, maar ook voor je mensen. Bescherm hen, creëer voorwaarden voor hun groei, wees voor hen een voorspelbare en betrouwbare steun. Hun kracht wordt jouw kracht."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-strength-15','intensive-strength',15,1,'День: 15','[{"type":"video","vimeoId":"1132397580"},{"type":"text","markdown":"### Совет дня:\n\nИдите на просчитанный риск. Избегать рисков - значит отказаться от роста. Сильный человек не бросается в авантюры, но и не прячется от неизвестности. Он оценивает возможные потери, соотносит их с потенциальной выгодой и делает осознанный шаг вперёд."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1132397580"},{"type":"text","markdown":"### Tip of the day:\n\nTake a calculated risk. To avoid risks means to refuse growth. A strong person does not rush into risky ventures, but also does not hide from the unknown. He evaluates possible losses, correlates them with potential benefit and takes a conscious step forward."}],"de":[{"type":"video","vimeoId":"1132397580"},{"type":"text","markdown":"### Tipp des Tages:\n\nGehen Sie ein kalkuliertes Risiko ein. Risiken zu vermeiden bedeutet, auf Wachstum zu verzichten. Ein starker Mensch stürzt sich nicht in Abenteuer, aber er versteckt sich auch nicht vor dem Unbekannten. Er bewertet mögliche Verluste, setzt sie ins Verhältnis zum potenziellen Nutzen und macht einen bewussten Schritt nach vorn."}],"fr":[{"type":"video","vimeoId":"1132397580"},{"type":"text","markdown":"### Conseil du jour :\n\nPrenez des risques calculés. Éviter les risques, c’est renoncer à la croissance. Un homme fort ne se jette pas dans des aventures hasardeuses, mais ne se cache pas non plus devant l’inconnu. Il évalue les pertes possibles, les rapporte au bénéfice potentiel et fait un pas conscient en avant."}],"it":[{"type":"video","vimeoId":"1132397580"},{"type":"text","markdown":"### Consiglio del giorno:\n\nCorrete rischi calcolati. Evitare i rischi significa rinunciare alla crescita. Una persona forte non si getta in avventure, ma non si nasconde neppure dall''incognita. Valuta le possibili perdite, le mette in rapporto con il potenziale guadagno e compie un passo consapevole in avanti."}],"es":[{"type":"video","vimeoId":"1132397580"},{"type":"text","markdown":"### Consejo del día:\n\nAcepten el riesgo calculado. Evitar riesgos significa renunciar al crecimiento. Una persona fuerte no se lanza a aventuras, pero tampoco se esconde de lo desconocido. Evalúa las posibles pérdidas, las compara con el beneficio potencial y da un paso consciente hacia adelante."}],"pt":[{"type":"video","vimeoId":"1132397580"},{"type":"text","markdown":"### Dica do dia:\n\nCorra um risco calculado. Evitar riscos significa renunciar ao crescimento. Uma pessoa forte não se lança em aventuras, mas também não se esconde do desconhecido. Ela avalia as possíveis perdas, relaciona-as com o benefício potencial e dá um passo consciente à frente."}],"nl":[{"type":"video","vimeoId":"1132397580"},{"type":"text","markdown":"### Tip van de dag:\n\nNeem een berekend risico. Risico''s vermijden betekent groei opgeven. Een sterk mens stort zich niet in avonturen, maar verstopt zich ook niet voor het onbekende. Hij weegt mogelijke verliezen af, zet ze tegenover het potentiële voordeel en zet een bewuste stap vooruit."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-strength-16','intensive-strength',16,1,'День: 16','[{"type":"video","vimeoId":"1126715199"},{"type":"text","markdown":"### Совет дня:\n\nДержите удар, не теряя центра. Внешнее давление, критика и атаки неизбежны на пути к значимой цели. Ваша задача - научиться встречать их, не вовлекаясь эмоционально. Представьте, что вы - скала, о которую разбиваются волны: они шумят, но не могут сдвинуть вас с места."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1126715199"},{"type":"text","markdown":"### Tip of the day:\n\nTake the blow without losing your center. External pressure, criticism and attacks are inevitable on the path to a meaningful goal. Your task is to learn to meet them without becoming emotionally involved. Imagine that you are a rock against which waves break: they make noise, but they cannot move you from your place."}],"de":[{"type":"video","vimeoId":"1126715199"},{"type":"text","markdown":"### Tipp des Tages:\n\nHalten Sie den Schlägen stand, ohne Ihr Zentrum zu verlieren. Äußerer Druck, Kritik und Angriffe sind auf dem Weg zu einem bedeutenden Ziel unvermeidlich. Ihre Aufgabe ist es, zu lernen, ihnen zu begegnen, ohne sich emotional hineinziehen zu lassen. Stellen Sie sich vor, Sie seien ein Fels, an dem die Wellen zerschellen: Sie lärmen, können Sie aber nicht von der Stelle bewegen."}],"fr":[{"type":"video","vimeoId":"1126715199"},{"type":"text","markdown":"### Conseil du jour :\n\nEncaissez les coups sans perdre votre centre. La pression extérieure, la critique et les attaques sont inévitables sur le chemin vers un but important. Votre tâche est d’apprendre à les accueillir sans vous impliquer émotionnellement. Imaginez que vous êtes un rocher contre lequel se brisent les vagues : elles font du bruit, mais ne peuvent pas vous déplacer."}],"it":[{"type":"video","vimeoId":"1126715199"},{"type":"text","markdown":"### Consiglio del giorno:\n\nIncasate i colpi senza perdere il centro. Pressione esterna, critiche e attacchi sono inevitabili sul cammino verso un obiettivo significativo. Il vostro compito è imparare a incontrarli senza coinvolgervi emotivamente. Immaginate di essere una roccia contro cui si infrangono le onde: esse fanno rumore, ma non possono spostarvi dal vostro posto."}],"es":[{"type":"video","vimeoId":"1126715199"},{"type":"text","markdown":"### Consejo del día:\n\nSostengan el golpe sin perder el centro. La presión externa, las críticas y los ataques son inevitables en el camino hacia un objetivo significativo. Su tarea es aprender a recibirlos sin involucrarse emocionalmente. Imaginen que son una roca contra la que se rompen las olas: hacen ruido, pero no pueden moverlos de su sitio."}],"pt":[{"type":"video","vimeoId":"1126715199"},{"type":"text","markdown":"### Dica do dia:\n\nSuporte o impacto sem perder o centro. Pressão externa, críticas e ataques são inevitáveis no caminho para um objetivo significativo. Sua tarefa é aprender a encontrá-los sem se envolver emocionalmente. Imagine que você é uma rocha contra a qual as ondas se quebram: elas fazem barulho, mas não conseguem movê-lo do lugar."}],"nl":[{"type":"video","vimeoId":"1126715199"},{"type":"text","markdown":"### Tip van de dag:\n\nWeersta de klappen zonder je centrum te verliezen. Externe druk, kritiek en aanvallen zijn onvermijdelijk op weg naar een betekenisvol doel. Je taak is te leren ze tegemoet te treden zonder je emotioneel te laten meeslepen. Stel je voor dat je een rots bent waarop de golven stukbreken: ze maken lawaai, maar kunnen je niet van je plaats krijgen."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-strength-17','intensive-strength',17,1,'День: 17','[{"type":"video","vimeoId":"1132594141"},{"type":"text","markdown":"### Совет дня:\n\nСлужите высшему. Служение - это не унижение, а высшая форма проявления силы. Когда вы крепко стоите на ногах и имеете достаточно ресурсов (знаний, энергии, влияния), вы можете служить своей семье, своей компании, своей стране или идее. Это служение не отнимает, а преумножает вашу силу."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1132594141"},{"type":"text","markdown":"### Tip of the day:\n\nServe the highest. Service is not humiliation, but the highest form of manifesting strength. When you stand firmly on your feet and have enough resources (knowledge, energy, influence), you can serve your family, your company, your country or an idea. This service does not take away but multiplies your strength."}],"de":[{"type":"video","vimeoId":"1132594141"},{"type":"text","markdown":"### Tipp des Tages:\n\nDienen Sie dem Höheren. Dienst ist keine Erniedrigung, sondern die höchste Form der Manifestation von Kraft. Wenn Sie fest auf eigenen Beinen stehen und genügend Ressourcen haben (Wissen, Energie, Einfluss), können Sie Ihrer Familie, Ihrem Unternehmen, Ihrem Land oder einer Idee dienen. Dieser Dienst nimmt Ihre Kraft nicht weg, sondern vermehrt sie."}],"fr":[{"type":"video","vimeoId":"1132594141"},{"type":"text","markdown":"### Conseil du jour :\n\nServez le supérieur. Le service n’est pas un abaissement, mais la forme suprême de manifestation de la force. Lorsque vous tenez fermement sur vos jambes et disposez de suffisamment de ressources (connaissances, énergie, influence), vous pouvez servir votre famille, votre entreprise, votre pays ou une idée. Ce service ne retire pas votre force, il la multiplie."}],"it":[{"type":"video","vimeoId":"1132594141"},{"type":"text","markdown":"### Consiglio del giorno:\n\nServite ciò che è più alto. Il servizio non è un''umiliazione, ma la forma più alta di manifestazione della forza. Quando state saldamente in piedi e avete risorse sufficienti (conoscenze, energia, influenza), potete servire la vostra famiglia, la vostra azienda, il vostro paese o un''idea. Questo servizio non vi toglie, ma moltiplica la vostra forza."}],"es":[{"type":"video","vimeoId":"1132594141"},{"type":"text","markdown":"### Consejo del día:\n\nSirvan a lo superior. El servicio no es humillación, sino la forma suprema de manifestación de la fuerza. Cuando se mantienen firmes sobre sus pies y tienen suficientes recursos (conocimientos, energía, influencia), pueden servir a su familia, a su empresa, a su país o a una idea. Este servicio no les quita fuerza, sino que la multiplica."}],"pt":[{"type":"video","vimeoId":"1132594141"},{"type":"text","markdown":"### Dica do dia:\n\nSirva ao superior. Servir não é humilhação, mas a forma suprema de manifestação da força. Quando você está firmemente em pé e tem recursos suficientes (conhecimento, energia, influência), você pode servir à sua família, à sua empresa, ao seu país ou à sua ideia. Esse serviço não tira, mas multiplica sua força."}],"nl":[{"type":"video","vimeoId":"1132594141"},{"type":"text","markdown":"### Tip van de dag:\n\nDien het hogere. Dienen is geen vernedering, maar de hoogste vorm van krachtmanifestatie. Wanneer je stevig op je benen staat en voldoende middelen hebt (kennis, energie, invloed), kun je je familie, je bedrijf, je land of een idee dienen. Dit dienen neemt je kracht niet weg, maar vermeerdert haar."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-strength-18','intensive-strength',18,1,'День: 18','[{"type":"video","vimeoId":"1133444539"},{"type":"text","markdown":"### Совет дня:\n\nПрактикуйте стратегическое терпение. Некоторые процессы требуют времени, как созревание плода. Пытаться ускорить их силой - значит всё испортить. Умейте ждать подходящего момента для решающего действия, сохраняя при этом полную готовность и концентрацию."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1133444539"},{"type":"text","markdown":"### Tip of the day:\n\nPractice strategic patience. Some processes require time, like the ripening of a fruit. Trying to accelerate them by force means ruining everything. Know how to wait for the right moment for decisive action while maintaining full readiness and concentration."}],"de":[{"type":"video","vimeoId":"1133444539"},{"type":"text","markdown":"### Tipp des Tages:\n\nÜben Sie strategische Geduld. Manche Prozesse brauchen Zeit, wie das Reifen einer Frucht. Zu versuchen, sie mit Gewalt zu beschleunigen, bedeutet, alles zu verderben. Verstehen Sie es, auf den passenden Moment für eine entscheidende Handlung zu warten und dabei volle Bereitschaft und Konzentration zu bewahren."}],"fr":[{"type":"video","vimeoId":"1133444539"},{"type":"text","markdown":"### Conseil du jour :\n\nPratiquez la patience stratégique. Certains processus exigent du temps, comme la maturation d’un fruit. Tenter de les accélérer par la force, c’est tout gâter. Sachez attendre le moment propice à l’action décisive, tout en conservant une pleine disponibilité et concentration."}],"it":[{"type":"video","vimeoId":"1133444539"},{"type":"text","markdown":"### Consiglio del giorno:\n\nPraticate la pazienza strategica. Alcuni processi richiedono tempo, come la maturazione di un frutto. Cercare di accelerarli con la forza significa rovinare tutto. Sappiate attendere il momento opportuno per l''azione decisiva, mantenendo al contempo piena prontezza e concentrazione."}],"es":[{"type":"video","vimeoId":"1133444539"},{"type":"text","markdown":"### Consejo del día:\n\nPractiquen la paciencia estratégica. Algunos procesos requieren tiempo, como la maduración de un fruto. Intentar acelerarlos por la fuerza significa echarlo todo a perder. Sepan esperar el momento adecuado para la acción decisiva, manteniendo al mismo tiempo plena preparación y concentración."}],"pt":[{"type":"video","vimeoId":"1133444539"},{"type":"text","markdown":"### Dica do dia:\n\nPratique a paciência estratégica. Alguns processos exigem tempo, como o amadurecimento de um fruto. Tentar acelerá-los à força significa estragar tudo. Saiba esperar o momento adequado para a ação decisiva, mantendo ao mesmo tempo plena prontidão e concentração."}],"nl":[{"type":"video","vimeoId":"1133444539"},{"type":"text","markdown":"### Tip van de dag:\n\nBeoefen strategisch geduld. Sommige processen hebben tijd nodig, zoals het rijpen van een vrucht. Ze met geweld proberen te versnellen betekent alles bederven. Leer wachten op het juiste moment voor een beslissende actie, terwijl je volledige paraatheid en concentratie behoudt."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-strength-19','intensive-strength',19,1,'День: 19','[{"type":"video","vimeoId":"1113127443"},{"type":"text","markdown":"### Совет дня:\n\nСоздавайте порядок и структуру вокруг себя. Хаос поглощает энергию. Создавайте ясные правила, системы и ритуалы в своей работе, быту, отношениях. Структура высвобождает ментальные ресурсы, позволяя не тратить их на решение повторяющихся бытовых задач, а направить на стратегические цели."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1113127443"},{"type":"text","markdown":"### Tip of the day:\n\nCreate order and structure around yourself. Chaos absorbs energy. Create clear rules, systems and rituals in your work, daily life, relationships. Structure frees mental resources, allowing you not to spend them on solving recurring everyday tasks but to direct them toward strategic goals."}],"de":[{"type":"video","vimeoId":"1113127443"},{"type":"text","markdown":"### Tipp des Tages:\n\nSchaffen Sie Ordnung und Struktur um sich herum. Chaos absorbiert Energie. Schaffen Sie klare Regeln, Systeme und Rituale in Ihrer Arbeit, Ihrem Alltag, Ihren Beziehungen. Struktur setzt mentale Ressourcen frei, sodass Sie sie nicht für die Lösung wiederkehrender Alltagsaufgaben verbrauchen, sondern auf strategische Ziele richten können."}],"fr":[{"type":"video","vimeoId":"1113127443"},{"type":"text","markdown":"### Conseil du jour :\n\nCréez de l’ordre et de la structure autour de vous. Le chaos absorbe l’énergie. Créez des règles claires, des systèmes et des rituels dans votre travail, votre vie quotidienne et vos relations. La structure libère des ressources mentales, permettant de ne pas les dépenser pour résoudre des tâches domestiques répétitives, mais de les diriger vers des buts stratégiques."}],"it":[{"type":"video","vimeoId":"1113127443"},{"type":"text","markdown":"### Consiglio del giorno:\n\nCreate ordine e struttura intorno a voi. Il caos assorbe energia. Create regole, sistemi e rituali chiari nel vostro lavoro, nella vita quotidiana, nelle relazioni. La struttura libera risorse mentali, permettendo di non spenderle nella soluzione di compiti quotidiani ricorrenti, ma di indirizzarle verso obiettivi strategici."}],"es":[{"type":"video","vimeoId":"1113127443"},{"type":"text","markdown":"### Consejo del día:\n\nCreen orden y estructura a su alrededor. El caos absorbe energía. Creen reglas claras, sistemas y rituales en su trabajo, vida cotidiana y relaciones. La estructura libera recursos mentales, permitiendo no gastarlos en resolver tareas domésticas repetitivas, sino dirigirlos hacia objetivos estratégicos."}],"pt":[{"type":"video","vimeoId":"1113127443"},{"type":"text","markdown":"### Dica do dia:\n\nCrie ordem e estrutura ao seu redor. O caos absorve energia. Crie regras, sistemas e rituais claros no seu trabalho, na vida cotidiana, nas relações. A estrutura libera recursos mentais, permitindo não gastá-los na resolução de tarefas domésticas repetitivas, mas direcioná-los a objetivos estratégicos."}],"nl":[{"type":"video","vimeoId":"1113127443"},{"type":"text","markdown":"### Tip van de dag:\n\nCreëer orde en structuur om je heen. Chaos absorbeert energie. Creëer duidelijke regels, systemen en rituelen in je werk, je dagelijks leven en je relaties. Structuur maakt mentale middelen vrij, zodat je ze niet hoeft te besteden aan terugkerende huishoudelijke taken, maar kunt richten op strategische doelen."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-strength-20','intensive-strength',20,1,'День: 20','[{"type":"video","vimeoId":"1127406249"},{"type":"text","markdown":"### Совет дня:\n\nПомните, что сила дана для созидания. Высшее проявление силы - не в способности разрушать, а в способности созидать: строить компании, создавать здоровые семьи, реализовывать проекты, которые делают мир лучше. Сила, используемая только для разрушения, в конечном счёте уничтожает своего носителя."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1127406249"},{"type":"text","markdown":"### Tip of the day:\n\nRemember that strength is given for creation. The highest manifestation of strength is not in the ability to destroy, but in the ability to create: build companies, create healthy families, realize projects that make the world better. Strength used only for destruction ultimately destroys its bearer."}],"de":[{"type":"video","vimeoId":"1127406249"},{"type":"text","markdown":"### Tipp des Tages:\n\nDenken Sie daran, dass Kraft zum Aufbau gegeben ist. Die höchste Manifestation von Kraft liegt nicht in der Fähigkeit zu zerstören, sondern in der Fähigkeit aufzubauen: Unternehmen zu bilden, gesunde Familien zu schaffen, Projekte zu verwirklichen, die die Welt besser machen. Kraft, die nur zur Zerstörung eingesetzt wird, vernichtet letztlich ihren Träger."}],"fr":[{"type":"video","vimeoId":"1127406249"},{"type":"text","markdown":"### Conseil du jour :\n\nRappelez-vous que la force est donnée pour édifier. La manifestation suprême de la force ne réside pas dans la capacité à détruire, mais dans la capacité à édifier : bâtir des entreprises, créer des familles saines, réaliser des projets qui rendent le monde meilleur. La force utilisée uniquement pour détruire finit par détruire son porteur."}],"it":[{"type":"video","vimeoId":"1127406249"},{"type":"text","markdown":"### Consiglio del giorno:\n\nRicordate che la forza è data per creare. La più alta manifestazione della forza non sta nella capacità di distruggere, ma nella capacità di creare: costruire aziende, creare famiglie sane, realizzare progetti che rendono il mondo migliore. La forza usata solo per distruggere, in definitiva, distrugge chi la porta."}],"es":[{"type":"video","vimeoId":"1127406249"},{"type":"text","markdown":"### Consejo del día:\n\nRecuerden que la fuerza está dada para construir. La manifestación suprema de la fuerza no está en la capacidad de destruir, sino en la capacidad de crear: construir empresas, crear familias sanas, realizar proyectos que hacen del mundo un lugar mejor. La fuerza utilizada solo para destruir, en última instancia, destruye a su portador."}],"pt":[{"type":"video","vimeoId":"1127406249"},{"type":"text","markdown":"### Dica do dia:\n\nLembre-se de que a força é dada para a criação. A manifestação suprema da força não está na capacidade de destruir, mas na capacidade de criar: construir empresas, criar famílias saudáveis, realizar projetos que tornam o mundo melhor. A força usada apenas para a destruição, no fim, destrói seu próprio portador."}],"nl":[{"type":"video","vimeoId":"1127406249"},{"type":"text","markdown":"### Tip van de dag:\n\nBedenk dat kracht gegeven is om te scheppen. De hoogste manifestatie van kracht ligt niet in het vermogen om te vernietigen, maar in het vermogen om te scheppen: bedrijven bouwen, gezonde gezinnen creëren, projecten realiseren die de wereld beter maken. Kracht die alleen voor vernietiging wordt gebruikt, vernietigt uiteindelijk haar drager."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-strength-21','intensive-strength',21,1,'День: 21','[{"type":"video","vimeoId":"1137358518"},{"type":"text","markdown":"### Совет дня:\n\nНе привязывайтесь к результату. Делайте всё, что от вас зависит, вкладывая 100% усилий в процесс. Но как только действие совершено, отпустите результат. Чрезмерная привязанность к плодам своего труда создаёт напряжение и страх, которые мешают вашей силе проявляться и приносить плоды."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1137358518"},{"type":"text","markdown":"### Tip of the day:\n\nDo not become attached to the result. Do everything that depends on you, investing 100% of your efforts in the process. But as soon as the action is performed, let go of the result. Excessive attachment to the fruits of your labor creates tension and fear that prevent your strength from manifesting and bearing fruit."}],"de":[{"type":"video","vimeoId":"1137358518"},{"type":"text","markdown":"### Tipp des Tages:\n\nHängen Sie nicht am Ergebnis. Tun Sie alles, was von Ihnen abhängt, und investieren Sie 100 % Anstrengung in den Prozess. Aber sobald die Handlung vollzogen ist, lassen Sie das Ergebnis los. Übermäßige Anhaftung an die Früchte Ihrer Arbeit erzeugt Spannung und Angst, die Ihre Kraft daran hindern, sich zu manifestieren und Früchte zu tragen."}],"fr":[{"type":"video","vimeoId":"1137358518"},{"type":"text","markdown":"### Conseil du jour :\n\nNe vous attachez pas au résultat. Faites tout ce qui dépend de vous, en investissant 100 % de vos efforts dans le processus. Mais dès que l’action est accomplie, lâchez le résultat. Un attachement excessif aux fruits de votre travail crée tension et peur, qui empêchent votre force de se manifester et de porter des fruits."}],"it":[{"type":"video","vimeoId":"1137358518"},{"type":"text","markdown":"### Consiglio del giorno:\n\nNon attaccatevi al risultato. Fate tutto ciò che dipende da voi, investendo il 100% degli sforzi nel processo. Ma non appena l''azione è compiuta, lasciate andare il risultato. Un attaccamento eccessivo ai frutti del proprio lavoro crea tensione e paura, che impediscono alla vostra forza di manifestarsi e portare frutti."}],"es":[{"type":"video","vimeoId":"1137358518"},{"type":"text","markdown":"### Consejo del día:\n\nNo se apeguen al resultado. Hagan todo lo que dependa de ustedes, invirtiendo el 100% de sus esfuerzos en el proceso. Pero en cuanto la acción se ha realizado, suelten el resultado. El apego excesivo a los frutos de su trabajo crea tensión y miedo que impiden que su fuerza se manifieste y dé frutos."}],"pt":[{"type":"video","vimeoId":"1137358518"},{"type":"text","markdown":"### Dica do dia:\n\nNão se apegue ao resultado. Faça tudo o que depende de você, investindo 100% de esforço no processo. Mas, assim que a ação for realizada, solte o resultado. O apego excessivo aos frutos do seu trabalho cria tensão e medo, que impedem sua força de se manifestar e de dar frutos."}],"nl":[{"type":"video","vimeoId":"1137358518"},{"type":"text","markdown":"### Tip van de dag:\n\nRaak niet gehecht aan het resultaat. Doe alles wat van je afhangt en leg 100% inspanning in het proces. Maar zodra de handeling is verricht, laat je het resultaat los. Overmatige gehechtheid aan de vruchten van je werk creëert spanning en angst, die verhinderen dat je kracht zich manifesteert en vruchten draagt."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-strength-22','intensive-strength',22,1,'День: 22','[{"type":"video","vimeoId":"1133455053"},{"type":"text","markdown":"### Совет дня:\n\nУчитесь распознавать циклы: когда сеять, а когда собирать урожай, когда действовать, а когда ждать. Вся жизнь циклична. Есть время для активного расширения, а есть время для накопления сил и закрепления на позициях. Действовать вопреки естественному циклу - значит биться головой о стену. Развивайте чутьё, чтобы понимать, в какой фазе вы находитесь сейчас."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1133455053"},{"type":"text","markdown":"### Tip of the day:\n\nLearn to recognize cycles: when to sow and when to harvest, when to act and when to wait. All life is cyclical. There is a time for active expansion, and there is a time for accumulating strength and consolidating positions. To act contrary to the natural cycle means to bang your head against a wall. Develop your sense so that you understand which phase you are in now."}],"de":[{"type":"video","vimeoId":"1133455053"},{"type":"text","markdown":"### Tipp des Tages:\n\nLernen Sie, Zyklen zu erkennen: wann man sät und wann man die Ernte einbringt, wann man handelt und wann man wartet. Das ganze Leben ist zyklisch. Es gibt eine Zeit der aktiven Ausdehnung und eine Zeit des Kräftesammelns und der Festigung der Positionen. Gegen den natürlichen Zyklus zu handeln bedeutet, mit dem Kopf gegen die Wand zu schlagen. Entwickeln Sie ein Gespür dafür, in welcher Phase Sie sich gerade befinden."}],"fr":[{"type":"video","vimeoId":"1133455053"},{"type":"text","markdown":"### Conseil du jour :\n\nApprenez à reconnaître les cycles : quand semer et quand récolter, quand agir et quand attendre. Toute la vie est cyclique. Il y a un temps pour l’expansion active, et un temps pour accumuler des forces et s’affermir sur ses positions. Agir contre le cycle naturel, c’est se cogner la tête contre un mur. Développez votre intuition pour comprendre dans quelle phase vous vous trouvez maintenant."}],"it":[{"type":"video","vimeoId":"1133455053"},{"type":"text","markdown":"### Consiglio del giorno:\n\nImparate a riconoscere i cicli: quando seminare e quando raccogliere il raccolto, quando agire e quando attendere. Tutta la vita è ciclica. C''è un tempo per l''espansione attiva e c''è un tempo per accumulare forze e consolidare le posizioni. Agire contro il ciclo naturale significa sbattere la testa contro il muro. Sviluppate l''intuito per capire in quale fase vi trovate ora."}],"es":[{"type":"video","vimeoId":"1133455053"},{"type":"text","markdown":"### Consejo del día:\n\nAprendan a reconocer los ciclos: cuándo sembrar y cuándo cosechar, cuándo actuar y cuándo esperar. Toda la vida es cíclica. Hay un tiempo para la expansión activa y un tiempo para acumular fuerzas y consolidarse en las posiciones. Actuar en contra del ciclo natural significa golpearse la cabeza contra la pared. Desarrollen la intuición para comprender en qué fase se encuentran ahora."}],"pt":[{"type":"video","vimeoId":"1133455053"},{"type":"text","markdown":"### Dica do dia:\n\nAprenda a reconhecer os ciclos: quando semear e quando colher a safra, quando agir e quando esperar. Toda a vida é cíclica. Há um tempo para a expansão ativa, e há um tempo para acumular forças e se firmar nas posições. Agir contra o ciclo natural significa bater a cabeça na parede. Desenvolva a intuição para entender em que fase você está agora."}],"nl":[{"type":"video","vimeoId":"1133455053"},{"type":"text","markdown":"### Tip van de dag:\n\nLeer cycli herkennen: wanneer te zaaien en wanneer de oogst binnen te halen, wanneer te handelen en wanneer te wachten. Het hele leven is cyclisch. Er is een tijd voor actieve uitbreiding en er is een tijd om krachten te verzamelen en je posities te verstevigen. Handelen tegen de natuurlijke cyclus in betekent met je hoofd tegen de muur bonken. Ontwikkel je intuïtie om te begrijpen in welke fase je je nu bevindt."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-strength-23','intensive-strength',23,1,'День: 23','[{"type":"video","vimeoId":"1135819045"},{"type":"text","markdown":"### Совет дня:\n\nВедите, а не тащите. Вдохновляйте, а не принуждайте. Настоящее лидерство - это способность зажечь своим видением других. Люди идут не за тем, кто сильнее давит, а за тем, кто ясно видит путь и даёт им возможность стать частью чего-то большего. Ваша задача - транслировать смысл и указывать направление."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1135819045"},{"type":"text","markdown":"### Tip of the day:\n\nLead, don''t drag. Inspire, don''t coerce. True leadership is the ability to ignite others with your vision. People do not follow the one who pushes harder, but the one who clearly sees the path and gives them the opportunity to become part of something bigger. Your task is to convey meaning and indicate direction."}],"de":[{"type":"video","vimeoId":"1135819045"},{"type":"text","markdown":"### Tipp des Tages:\n\nFühren Sie, statt zu ziehen. Inspirieren Sie, statt zu zwingen. Wahre Führung ist die Fähigkeit, andere mit seiner Vision zu entzünden. Menschen folgen nicht dem, der stärker drückt, sondern dem, der den Weg klar sieht und ihnen die Möglichkeit gibt, Teil von etwas Größerem zu werden. Ihre Aufgabe ist es, Sinn zu vermitteln und die Richtung anzugeben."}],"fr":[{"type":"video","vimeoId":"1135819045"},{"type":"text","markdown":"### Conseil du jour :\n\nGuidez, ne tirez pas. Inspirez, ne contraignez pas. Le véritable leadership est la capacité d’enflammer les autres par votre vision. Les gens ne suivent pas celui qui appuie le plus fort, mais celui qui voit clairement le chemin et leur donne la possibilité de faire partie de quelque chose de plus grand. Votre tâche est de transmettre le sens et d’indiquer la direction."}],"it":[{"type":"video","vimeoId":"1135819045"},{"type":"text","markdown":"### Consiglio del giorno:\n\nGuidate, non trascinate. Ispirate, non costringete. La vera leadership è la capacità di accendere gli altri con la propria visione. Le persone non seguono chi preme più forte, ma chi vede chiaramente il cammino e dà loro la possibilità di diventare parte di qualcosa di più grande. Il vostro compito è trasmettere il senso e indicare la direzione."}],"es":[{"type":"video","vimeoId":"1135819045"},{"type":"text","markdown":"### Consejo del día:\n\nLideren, no arrastren. Inspiren, no obliguen. El verdadero liderazgo es la capacidad de encender a otros con su visión. La gente no sigue a quien presiona más fuerte, sino a quien ve claramente el camino y les da la posibilidad de formar parte de algo más grande. Su tarea es transmitir sentido e indicar la dirección."}],"pt":[{"type":"video","vimeoId":"1135819045"},{"type":"text","markdown":"### Dica do dia:\n\nLidere, não arraste. Inspire, não force. A verdadeira liderança é a capacidade de acender os outros com sua visão. As pessoas não seguem quem pressiona mais forte, mas quem vê claramente o caminho e lhes dá a possibilidade de se tornarem parte de algo maior. Sua tarefa é transmitir sentido e indicar a direção."}],"nl":[{"type":"video","vimeoId":"1135819045"},{"type":"text","markdown":"### Tip van de dag:\n\nLeid, en sleep niet mee. Inspireer, en dwing niet. Echt leiderschap is het vermogen om anderen met je visie te ontvlammen. Mensen volgen niet degene die harder drukt, maar degene die de weg duidelijk ziet en hun de mogelijkheid geeft deel te worden van iets groters. Je taak is betekenis over te brengen en de richting aan te wijzen."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-strength-24','intensive-strength',24,1,'День: 24','[{"type":"video","vimeoId":"1115391032"},{"type":"text","markdown":"### Совет дня:\n\nЗнайте своё место в иерархии. Любая система, от семьи до государства, иерархична. Поймите, кто стоит выше вас (у кого вы учитесь и кому служите) и кто ниже (за кого вы отвечаете). Умение подчиняться, не теряя достоинства, и руководить, не унижая других - признак зрелой силы."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1115391032"},{"type":"text","markdown":"### Tip of the day:\n\nKnow your place in the hierarchy. Any system, from family to state, is hierarchical. Understand who stands above you (from whom you learn and whom you serve) and who stands below (for whom you are responsible). The ability to obey without losing dignity and to lead without humiliating others - a sign of mature strength."}],"de":[{"type":"video","vimeoId":"1115391032"},{"type":"text","markdown":"### Tipp des Tages:\n\nKennen Sie Ihren Platz in der Hierarchie. Jedes System, von der Familie bis zum Staat, ist hierarchisch. Verstehen Sie, wer über Ihnen steht (von wem Sie lernen und wem Sie dienen) und wer unter Ihnen steht (für wen Sie verantwortlich sind). Die Fähigkeit, sich unterzuordnen, ohne die Würde zu verlieren, und zu führen, ohne andere zu erniedrigen - ein Zeichen reifer Stärke."}],"fr":[{"type":"video","vimeoId":"1115391032"},{"type":"text","markdown":"### Conseil du jour :\n\nConnaissez votre place dans la hiérarchie. Tout système, de la famille à l''État, est hiérarchique. Comprenez qui se trouve au-dessus de vous (auprès de qui vous apprenez et à qui vous servez) et qui se trouve en dessous (de qui vous êtes responsable). Savoir obéir sans perdre sa dignité et diriger sans humilier les autres est le signe d''une force mature."}],"it":[{"type":"video","vimeoId":"1115391032"},{"type":"text","markdown":"### Consiglio del giorno:\n\nSappiate qual è il vostro posto nella gerarchia. Qualsiasi sistema, dalla famiglia allo Stato, è gerarchico. Comprendete chi sta sopra di voi (da chi imparate e a chi servite) e chi sta sotto (di chi siete responsabili). Saper sottomettersi senza perdere la dignità e guidare senza umiliare gli altri - è segno di forza matura."}],"es":[{"type":"video","vimeoId":"1115391032"},{"type":"text","markdown":"### Consejo del día:\n\nConozca su lugar en la jerarquía. Cualquier sistema, desde la familia hasta el Estado, es jerárquico. Comprenda quién está por encima de usted (de quién aprende y a quién sirve) y quién está por debajo (por quién responde). Saber subordinarse sin perder la dignidad y dirigir sin humillar a los demás es signo de una fuerza madura."}],"pt":[{"type":"video","vimeoId":"1115391032"},{"type":"text","markdown":"### Dica do dia:\n\nSaiba seu lugar na hierarquia. Qualquer sistema, da família ao Estado, é hierárquico. Entenda quem está acima de você (de quem você aprende e a quem você serve) e quem está abaixo (por quem você responde). A capacidade de obedecer sem perder a dignidade e de liderar sem humilhar os outros - é sinal de força madura."}],"nl":[{"type":"video","vimeoId":"1115391032"},{"type":"text","markdown":"### Tip van de dag:\n\nKen uw plaats in de hiërarchie. Elk systeem, van familie tot staat, is hiërarchisch. Begrijp wie boven u staat (van wie u leert en wie u dient) en wie onder u staat (voor wie u verantwoordelijk bent). Het vermogen om te gehoorzamen zonder waardigheid te verliezen, en om te leiden zonder anderen te vernederen - is een teken van volwassen kracht."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-strength-25','intensive-strength',25,1,'День: 25','[{"type":"video","vimeoId":"1133513692"},{"type":"text","markdown":"### Совет дня:\n\nУтвердитесь в своей ценности. Ваша ценность не зависит от чужого одобрения, статуса или количества денег. Она заложена в вас по праву существования. Осознайте это и перестаньте искать подтверждения своей значимости. Тогда внешние атрибуты придут как следствие, а не как костыли для самооценки."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1133513692"},{"type":"text","markdown":"### Tip of the day:\n\nBecome established in your own value. Your value does not depend on someone else''s approval, status, or amount of money. It is laid in you by right of existence. Realize this and stop seeking confirmation of your significance. Then external attributes will come as a consequence, and not as crutches for self-esteem."}],"de":[{"type":"video","vimeoId":"1133513692"},{"type":"text","markdown":"### Tipp des Tages:\n\nFestigen Sie sich in Ihrem Wert. Ihr Wert hängt nicht von der Zustimmung anderer, vom Status oder von der Menge Geld ab. Er ist Ihnen durch das Recht der Existenz innegelegt. Erkennen Sie das und hören Sie auf, Bestätigung für Ihre Bedeutung zu suchen. Dann kommen äußere Attribute als Folge, nicht als Krücken für das Selbstwertgefühl."}],"fr":[{"type":"video","vimeoId":"1133513692"},{"type":"text","markdown":"### Conseil du jour :\n\nAffirmez-vous dans votre valeur. Votre valeur ne dépend pas de l''approbation d''autrui, du statut ou de la quantité d''argent. Elle est inscrite en vous de par votre droit d''exister. Prenez-en conscience et cessez de chercher des confirmations de votre importance. Alors les attributs extérieurs viendront comme une conséquence, et non comme des béquilles pour l''estime de soi."}],"it":[{"type":"video","vimeoId":"1133513692"},{"type":"text","markdown":"### Consiglio del giorno:\n\nSiate saldi nel vostro valore. Il vostro valore non dipende dall''approvazione altrui, dallo status o dalla quantità di denaro. È radicato in voi per diritto di esistenza. Rendetevi conto di questo e smettete di cercare conferme della vostra importanza. Allora gli attributi esterni arriveranno come conseguenza, e non come stampelle per l''autostima."}],"es":[{"type":"video","vimeoId":"1133513692"},{"type":"text","markdown":"### Consejo del día:\n\nAfírmese en su propio valor. Su valor no depende de la aprobación ajena, del estatus ni de la cantidad de dinero. Está depositado en usted por derecho de existencia. Tome conciencia de ello y deje de buscar confirmación de su importancia. Entonces los atributos externos llegarán como consecuencia, y no como muletas para la autoestima."}],"pt":[{"type":"video","vimeoId":"1133513692"},{"type":"text","markdown":"### Dica do dia:\n\nAfirme-se em seu valor. Seu valor não depende da aprovação alheia, do status ou da quantidade de dinheiro. Ele está depositado em você pelo direito de existir. Conscientize-se disso e pare de buscar confirmação da sua importância. Então os atributos externos virão como consequência, e não como muletas para a autoestima."}],"nl":[{"type":"video","vimeoId":"1133513692"},{"type":"text","markdown":"### Tip van de dag:\n\nSta vast in uw eigen waarde. Uw waarde hangt niet af van andermans goedkeuring, status of hoeveelheid geld. Ze is in u verankerd op grond van uw bestaansrecht. Realiseer u dat en stop met het zoeken naar bevestiging van uw eigen waarde. Dan komen uiterlijke attributen als gevolg, en niet als krukken voor uw eigenwaarde."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-strength-26','intensive-strength',26,1,'День: 26','[{"type":"video","vimeoId":"1133369904"},{"type":"text","markdown":"### Совет дня:\n\nВидьте ресурс в каждой ситуации. Для слабого человека проблема - это тупик и деструктивные эмоции. Для сильного - задача, скрывающая в себе ресурс. В провале - урок, во враге - учитель, в ограничении - стимул для креативности. И ресурсов очень много. Научитесь задавать себе вопрос: «Каков ещё ресурс этой ситуации?»"}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1133369904"},{"type":"text","markdown":"### Tip of the day:\n\nSee the resource in every situation. For a weak person, a problem is a dead end and destructive emotions. For a strong one - a task that hides a resource within itself. In failure - a lesson, in an enemy - a teacher, in limitation - a stimulus for creativity. And there are very many resources. Learn to ask yourself: «What other resource is there in this situation?»"}],"de":[{"type":"video","vimeoId":"1133369904"},{"type":"text","markdown":"### Tipp des Tages:\n\nSehen Sie in jeder Situation eine Ressource. Für einen schwachen Menschen ist ein Problem eine Sackgasse und destruktive Emotionen. Für einen starken - eine Aufgabe, die in sich eine Ressource birgt. Im Scheitern - eine Lektion, im Feind - ein Lehrer, in der Einschränkung - ein Anreiz für Kreativität. Und es gibt sehr viele Ressourcen. Lernen Sie, sich die Frage zu stellen: „Welche weitere Ressource hat diese Situation?“"}],"fr":[{"type":"video","vimeoId":"1133369904"},{"type":"text","markdown":"### Conseil du jour :\n\nVoyez une ressource dans chaque situation. Pour une personne faible, un problème est une impasse et des émotions destructrices. Pour une personne forte, c''est une tâche qui recèle une ressource. Dans l''échec, une leçon ; dans l''ennemi, un maître ; dans la limitation, un stimulant pour la créativité. Et les ressources sont très nombreuses. Apprenez à vous poser la question : « Quelle autre ressource cette situation recèle-t-elle ? »"}],"it":[{"type":"video","vimeoId":"1133369904"},{"type":"text","markdown":"### Consiglio del giorno:\n\nVedete una risorsa in ogni situazione. Per una persona debole il problema è un vicolo cieco ed emozioni distruttive. Per quella forte - un compito che nasconde in sé una risorsa. Nel fallimento - una lezione, nel nemico - un maestro, nella limitazione - uno stimolo per la creatività. E di risorse ce ne sono moltissime. Imparate a chiedervi: «Qual è l''altra risorsa di questa situazione?»"}],"es":[{"type":"video","vimeoId":"1133369904"},{"type":"text","markdown":"### Consejo del día:\n\nVea un recurso en cada situación. Para una persona débil, un problema es un callejón sin salida y emociones destructivas. Para una fuerte, una tarea que esconde en sí un recurso. En el fracaso, una lección; en el enemigo, un maestro; en la limitación, un estímulo para la creatividad. Y los recursos son muchísimos. Aprenda a hacerse la pregunta: «¿Qué otro recurso hay en esta situación?»"}],"pt":[{"type":"video","vimeoId":"1133369904"},{"type":"text","markdown":"### Dica do dia:\n\nEnxergue o recurso em cada situação. Para uma pessoa fraca, o problema é um beco sem saída e emoções destrutivas. Para uma pessoa forte, é uma tarefa que esconde em si um recurso. No fracasso - uma lição, no inimigo - um professor, na limitação - um estímulo para a criatividade. E há muitos recursos. Aprenda a se perguntar: «Qual é ainda o recurso desta situação?»"}],"nl":[{"type":"video","vimeoId":"1133369904"},{"type":"text","markdown":"### Tip van de dag:\n\nZie in elke situatie een hulpbron. Voor een zwak mens is een probleem een doodlopende weg en destructieve emoties. Voor een sterk mens is het een taak die een hulpbron in zich verbergt. In een mislukking schuilt een les, in een vijand een leraar, in een beperking een prikkel tot creativiteit. En er zijn heel veel hulpbronnen. Leer uzelf de vraag te stellen: ‘Welke andere hulpbron heeft deze situatie nog?’"}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-strength-27','intensive-strength',27,1,'День: 27','[{"type":"video","vimeoId":"1153853898"},{"type":"text","markdown":"### Совет дня:\n\nНаходите новые способы восстанавливать свои силы. Важно не только умение распределять свои силы, но и умение их восполнять. Найдите то, что наполняет именно вас - будь то уединение, общение с природой, хобби, медитация, книги, друзья, спорт... Регулярное восстановление - это не роскошь, а стратегическая необходимость."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1153853898"},{"type":"text","markdown":"### Tip of the day:\n\nFind new ways to restore your strength. It is important not only to be able to distribute your strength but also to be able to replenish it. Find what fills specifically you - be it solitude, communication with nature, a hobby, meditation, books, friends, sport... Regular restoration is not a luxury but a strategic necessity."}],"de":[{"type":"video","vimeoId":"1153853898"},{"type":"text","markdown":"### Tipp des Tages:\n\nFinden Sie neue Wege, Ihre Kräfte wiederherzustellen. Wichtig ist nicht nur die Fähigkeit, Ihre Kräfte einzuteilen, sondern auch die Fähigkeit, sie wieder aufzufüllen. Finden Sie das, was genau Sie erfüllt - sei es Zurückgezogenheit, Zeit in der Natur, ein Hobby, Meditation, Bücher, Freunde, Sport... Regelmäßige Wiederherstellung ist kein Luxus, sondern eine strategische Notwendigkeit."}],"fr":[{"type":"video","vimeoId":"1153853898"},{"type":"text","markdown":"### Conseil du jour :\n\nTrouvez de nouvelles façons de restaurer vos forces. Il est important non seulement de savoir répartir vos forces, mais aussi de savoir les reconstituer. Trouvez ce qui remplit précisément vous-même — que ce soit la solitude, le contact avec la nature, un hobby, la méditation, les livres, les amis, le sport... Une récupération régulière n''est pas un luxe, mais une nécessité stratégique."}],"it":[{"type":"video","vimeoId":"1153853898"},{"type":"text","markdown":"### Consiglio del giorno:\n\nTrovate nuovi modi per recuperare le vostre forze. È importante non solo la capacità di distribuire le vostre forze, ma anche quella di ricostituirle. Trovate ciò che ricolma proprio voi - che sia la solitudine, il contatto con la natura, un hobby, la meditazione, i libri, gli amici, lo sport... Il recupero regolare - non è un lusso, ma una necessità strategica."}],"es":[{"type":"video","vimeoId":"1153853898"},{"type":"text","markdown":"### Consejo del día:\n\nEncuentre nuevas formas de recuperar sus fuerzas. Es importante no solo la capacidad de distribuir sus fuerzas, sino también la de reponerlas. Encuentre lo que lo llena a usted en particular, ya sea la soledad, el contacto con la naturaleza, un pasatiempo, la meditación, los libros, los amigos, el deporte... La recuperación regular no es un lujo, sino una necesidad estratégica."}],"pt":[{"type":"video","vimeoId":"1153853898"},{"type":"text","markdown":"### Dica do dia:\n\nEncontre novas maneiras de restaurar suas forças. É importante não apenas a capacidade de distribuir suas forças, mas também a capacidade de repô-las. Encontre aquilo que preenche precisamente você - seja a solitude, o contato com a natureza, um hobby, a meditação, livros, amigos, esporte... A restauração regular - isto não é um luxo, mas uma necessidade estratégica."}],"nl":[{"type":"video","vimeoId":"1153853898"},{"type":"text","markdown":"### Tip van de dag:\n\nVind nieuwe manieren om uw krachten te herstellen. Belangrijk is niet alleen het vermogen om uw krachten te verdelen, maar ook het vermogen om ze aan te vullen. Vind dat wat juist u vervult - of dat nu alleen zijn is, contact met de natuur, een hobby, meditatie, boeken, vrienden, sport... Regelmatig herstel is geen luxe, maar een strategische noodzaak."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-strength-28','intensive-strength',28,1,'День: 28','[{"type":"video","vimeoId":"1129760004"},{"type":"text","markdown":"### Совет дня:\n\nРазвивайте не только силу, но и гибкость. Ваша главная цель должна быть неизменна, как Полярная звезда. Но пути её достижения (тактика) могут и должны меняться в зависимости от обстоятельств. Не упорствуйте в неработающих методах; будьте как вода, которая обходит препятствия, но неуклонно движется к океану."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1129760004"},{"type":"text","markdown":"### Tip of the day:\n\nDevelop not only strength, but also flexibility. Your main goal must be unchanging, like the North Star. But the paths to achieving it (tactics) can and must change depending on circumstances. Do not persist in non-working methods; be like water, which goes around obstacles but steadily moves toward the ocean."}],"de":[{"type":"video","vimeoId":"1129760004"},{"type":"text","markdown":"### Tipp des Tages:\n\nEntwickeln Sie nicht nur Stärke, sondern auch Flexibilität. Ihr Hauptziel muss unverändert sein wie der Polarstern. Aber die Wege zu seiner Erreichung (die Taktik) können und müssen sich je nach den Umständen ändern. Beharren Sie nicht auf nicht funktionierenden Methoden; seien Sie wie Wasser, das Hindernisse umgeht, aber unaufhaltsam zum Ozean fließt."}],"fr":[{"type":"video","vimeoId":"1129760004"},{"type":"text","markdown":"### Conseil du jour :\n\nDéveloppez non seulement la force, mais aussi la souplesse. Votre objectif principal doit être immuable, comme l''étoile Polaire. Mais les chemins pour y parvenir (la tactique) peuvent et doivent changer selon les circonstances. N''insistez pas dans des méthodes qui ne fonctionnent pas ; soyez comme l''eau, qui contourne les obstacles mais avance inexorablement vers l''océan."}],"it":[{"type":"video","vimeoId":"1129760004"},{"type":"text","markdown":"### Consiglio del giorno:\n\nSviluppate non solo la forza, ma anche la flessibilità. Il vostro obiettivo principale deve essere immutabile, come la Stella Polare. Ma le vie per raggiungerlo (la tattica) possono e devono cambiare a seconda delle circostanze. Non ostinatevi in metodi che non funzionano; siate come l''acqua, che aggira gli ostacoli, ma si muove inesorabilmente verso l''oceano."}],"es":[{"type":"video","vimeoId":"1129760004"},{"type":"text","markdown":"### Consejo del día:\n\nDesarrolle no solo la fuerza, sino también la flexibilidad. Su objetivo principal debe ser inmutable, como la Estrella Polar. Pero los caminos para alcanzarlo (la táctica) pueden y deben cambiar según las circunstancias. No se obstine en métodos que no funcionan; sea como el agua, que rodea los obstáculos, pero avanza de manera constante hacia el océano."}],"pt":[{"type":"video","vimeoId":"1129760004"},{"type":"text","markdown":"### Dica do dia:\n\nDesenvolva não apenas a força, mas também a flexibilidade. Seu objetivo principal deve ser imutável, como a Estrela Polar. Mas os caminhos para alcançá-lo (a tática) podem e devem mudar dependendo das circunstâncias. Não persevere em métodos que não funcionam; seja como a água, que contorna os obstáculos, mas se move inabalavelmente em direção ao oceano."}],"nl":[{"type":"video","vimeoId":"1129760004"},{"type":"text","markdown":"### Tip van de dag:\n\nOntwikkel niet alleen kracht, maar ook flexibiliteit. Uw hoofddoel moet onveranderlijk zijn, als de Poolster. Maar de wegen om het te bereiken (de tactiek) kunnen en moeten veranderen afhankelijk van de omstandigheden. Houd niet koppig vast aan methoden die niet werken; wees als water, dat obstakels omzeilt, maar onverdroten naar de oceaan stroomt."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-strength-29','intensive-strength',29,1,'День: 29','[{"type":"video","vimeoId":"1107312542"},{"type":"text","markdown":"### Совет дня:\n\nОтноситесь к деньгам как к инструменту. Деньги - это социальная энергия, соответствующая приносимой вами ценности. Не делайте деньги самоцелью, но и не пренебрегайте ими. Учитесь зарабатывать, управлять, сохранять и приумножать их, понимая, что это ещё один важный ресурс для достижения ваших целей."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1107312542"},{"type":"text","markdown":"### Tip of the day:\n\nTreat money as a tool. Money is social energy corresponding to the value you bring. Do not make money an end in itself, but also do not neglect it. Learn to earn, manage, preserve, and increase it, understanding that it is another important resource for achieving your goals."}],"de":[{"type":"video","vimeoId":"1107312542"},{"type":"text","markdown":"### Tipp des Tages:\n\nBetrachten Sie Geld als Werkzeug. Geld ist soziale Energie, die dem Wert entspricht, den Sie beitragen. Machen Sie Geld nicht zum Selbstzweck, aber vernachlässigen Sie es auch nicht. Lernen Sie, es zu verdienen, zu verwalten, zu bewahren und zu vermehren, und verstehen Sie dabei, dass es eine weitere wichtige Ressource für das Erreichen Ihrer Ziele ist."}],"fr":[{"type":"video","vimeoId":"1107312542"},{"type":"text","markdown":"### Conseil du jour :\n\nConsidérez l''argent comme un instrument. L''argent est une énergie sociale correspondant à la valeur que vous apportez. Ne faites pas de l''argent un but en soi, mais ne le négligez pas non plus. Apprenez à en gagner, à le gérer, à le conserver et à le faire fructifier, en comprenant qu''il s''agit d''une autre ressource importante pour atteindre vos objectifs."}],"it":[{"type":"video","vimeoId":"1107312542"},{"type":"text","markdown":"### Consiglio del giorno:\n\nConsiderate il denaro come uno strumento. Il denaro è energia sociale, corrispondente al valore che apportate. Non fate del denaro un fine in sé, ma non trascuratelo. Imparate a guadagnarlo, gestirlo, conservarlo e moltiplicarlo, comprendendo che è un''altra importante risorsa per raggiungere i vostri obiettivi."}],"es":[{"type":"video","vimeoId":"1107312542"},{"type":"text","markdown":"### Consejo del día:\n\nTrate el dinero como una herramienta. El dinero es energía social que corresponde al valor que usted aporta. No convierta el dinero en un fin en sí mismo, pero tampoco lo descuide. Aprenda a ganarlo, gestionarlo, conservarlo y multiplicarlo, entendiendo que es otro recurso importante para alcanzar sus objetivos."}],"pt":[{"type":"video","vimeoId":"1107312542"},{"type":"text","markdown":"### Dica do dia:\n\nTrate o dinheiro como uma ferramenta. O dinheiro é energia social, correspondente ao valor que você traz. Não faça do dinheiro um fim em si mesmo, mas também não o despreze. Aprenda a ganhar, administrar, conservar e multiplicá-lo, compreendendo que este é mais um recurso importante para alcançar seus objetivos."}],"nl":[{"type":"video","vimeoId":"1107312542"},{"type":"text","markdown":"### Tip van de dag:\n\nBeschouw geld als een instrument. Geld is sociale energie die overeenkomt met de waarde die u levert. Maak van geld geen doel op zich, maar verwaarloos het ook niet. Leer het te verdienen, te beheren, te behouden en te vermeerderen, in het besef dat het nog een belangrijke hulpbron is om uw doelen te bereiken."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-strength-30','intensive-strength',30,1,'День: 30','[{"type":"video","vimeoId":"1133367763"},{"type":"text","markdown":"### Что дальше?\n\nЯ надеюсь, что этот месяц практик принёс вам ощутимые результаты, и после выполнения этой практики у вас может возникнуть вопрос - «Что дальше?»… И тут перед вами большой выбор практикумов, интенсивов и курсов, которые я подготовил для гармонизации самых разных сфер жизни и внутренних психологических состояний. Чтобы сориентироваться, сначала определитесь с направлением - что сейчас вас более всего трогает, то есть вызывает дискомфорт, тревожит, воодушевляет… (где есть яркие эмоции - там есть энергия для развития), а затем подумайте сколько времени вы готовы посвятить урокам и практикам. Если сложно определиться, напишите мне или задайте вопрос на вебинаре. Ниже я перечислил практикумы и курсы, которые могут вас заинтересовать:\n\n\nПРАКТИКУМЫ:\n - Месяц здоровья: [https://zamkovoi.yoga/m1](https://zamkovoi.yoga/m1)\n - Месяц наслаждений: [https://zamkovoi.yoga/m2](https://zamkovoi.yoga/m2)\n - Месяц силы: [https://zamkovoi.yoga/m3](https://zamkovoi.yoga/m3)\n - Месяц любви: [https://zamkovoi.yoga/m4](https://zamkovoi.yoga/m4)\n - Месяц свободы: [https://zamkovoi.yoga/m5](https://zamkovoi.yoga/m5)\n - Месяц мудрости: [https://zamkovoi.yoga/m6](https://zamkovoi.yoga/m6)\n - Месяц святости: [https://zamkovoi.yoga/m7](https://zamkovoi.yoga/m7)\n\n\nКУРСЫ:\n - Йога и здоровье: [https://zamkovoi.yoga/yoga1](https://zamkovoi.yoga/yoga1)\n - Йога и женственность: [https://zamkovoi.yoga/yoga2](https://zamkovoi.yoga/yoga2)\n - Тантра - мистерия взаимоотношений: [https://zamkovoi.yoga/tantra12](https://zamkovoi.yoga/tantra12)\n - Осуществи мечту: [https://zamkovoi.yoga/yoga3](https://zamkovoi.yoga/yoga3)\n - Планета любви: [https://zamkovoi.yoga/yoga4](https://zamkovoi.yoga/yoga4)\n - Источник творческой силы: [https://zamkovoi.yoga/yoga5](https://zamkovoi.yoga/yoga5)\n - 36 шагов йоги: [https://zamkovoi.yoga/yoga36](https://zamkovoi.yoga/yoga36)\n - Путь души: [https://zamkovoi.yoga/yogas](https://zamkovoi.yoga/yogas)"}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1133367763"},{"type":"text","markdown":"### What''s next?\n\nI hope this month of practices has brought you tangible results, and after completing this practice you may have a question — “What’s next?”… And here before you is a large choice of workshops, intensives, and courses that I have prepared for harmonizing a wide variety of areas of life and inner psychological states. To get your bearings, first decide on the direction — what touches you most right now, that is, causes discomfort, worries, inspires… (where there are vivid emotions, there is energy for development), and then think about how much time you are ready to devote to lessons and practices. If it is difficult to decide, write to me or ask a question at the webinar. Below I have listed the workshops and courses that may interest you:\n\n\nWORKSHOPS:\n - Month of Health: [https://zamkovoi.yoga/m1](https://zamkovoi.yoga/m1)\n - Month of Pleasures: [https://zamkovoi.yoga/m2](https://zamkovoi.yoga/m2)\n - Month of Strength: [https://zamkovoi.yoga/m3](https://zamkovoi.yoga/m3)\n - Month of Love: [https://zamkovoi.yoga/m4](https://zamkovoi.yoga/m4)\n - Month of Freedom: [https://zamkovoi.yoga/m5](https://zamkovoi.yoga/m5)\n - Month of Wisdom: [https://zamkovoi.yoga/m6](https://zamkovoi.yoga/m6)\n - Month of Holiness: [https://zamkovoi.yoga/m7](https://zamkovoi.yoga/m7)\n\n\nCOURSES:\n - Yoga and Health: [https://zamkovoi.yoga/yoga1](https://zamkovoi.yoga/yoga1)\n - Yoga and Femininity: [https://zamkovoi.yoga/yoga2](https://zamkovoi.yoga/yoga2)\n - Tantra - the mystery of relationships: [https://zamkovoi.yoga/tantra12](https://zamkovoi.yoga/tantra12)\n - Fulfill the Dream: [https://zamkovoi.yoga/yoga3](https://zamkovoi.yoga/yoga3)\n - Planet of Love: [https://zamkovoi.yoga/yoga4](https://zamkovoi.yoga/yoga4)\n - Source of Creative Power: [https://zamkovoi.yoga/yoga5](https://zamkovoi.yoga/yoga5)\n - 36 Steps of Yoga: [https://zamkovoi.yoga/yoga36](https://zamkovoi.yoga/yoga36)\n - Path of the Soul: [https://zamkovoi.yoga/yogas](https://zamkovoi.yoga/yogas)"}],"de":[{"type":"video","vimeoId":"1133367763"},{"type":"text","markdown":"### Was kommt als Nächstes?\n\nIch hoffe, dass dieser Monat der Praktiken Ihnen spürbare Ergebnisse gebracht hat, und nach der Ausführung dieser Praxis kann bei Ihnen die Frage aufkommen - „Was kommt als Nächstes?“… Und hier haben Sie eine große Auswahl an Praxisprogrammen, Intensivkursen und Kursen, die ich zur Harmonisierung der verschiedensten Lebensbereiche und inneren psychologischen Zustände vorbereitet habe. Zur Orientierung bestimmen Sie zuerst die Richtung - was Sie gerade am meisten berührt, also Unbehagen auslöst, beunruhigt, begeistert… (wo starke Emotionen sind, dort ist Energie für Entwicklung), und dann überlegen Sie, wie viel Zeit Sie bereit sind, den Lektionen und Praktiken zu widmen. Wenn es schwerfällt, sich zu entscheiden, schreiben Sie mir oder stellen Sie eine Frage im Webinar. Unten habe ich Praxisprogramme und Kurse aufgelistet, die Sie interessieren könnten:\n\n\nPRAKTIKA:\n - Monat der Gesundheit: [https://zamkovoi.yoga/m1](https://zamkovoi.yoga/m1)\n - Monat der Genüsse: [https://zamkovoi.yoga/m2](https://zamkovoi.yoga/m2)\n - Monat der Kraft: [https://zamkovoi.yoga/m3](https://zamkovoi.yoga/m3)\n - Monat der Liebe: [https://zamkovoi.yoga/m4](https://zamkovoi.yoga/m4)\n - Monat der Freiheit: [https://zamkovoi.yoga/m5](https://zamkovoi.yoga/m5)\n - Monat der Weisheit: [https://zamkovoi.yoga/m6](https://zamkovoi.yoga/m6)\n - Monat der Heiligkeit: [https://zamkovoi.yoga/m7](https://zamkovoi.yoga/m7)\n\n\nKURSE:\n - Yoga und Gesundheit: [https://zamkovoi.yoga/yoga1](https://zamkovoi.yoga/yoga1)\n - Yoga und Weiblichkeit: [https://zamkovoi.yoga/yoga2](https://zamkovoi.yoga/yoga2)\n - Tantra - Mysterium der Beziehungen: [https://zamkovoi.yoga/tantra12](https://zamkovoi.yoga/tantra12)\n - Verwirkliche den Traum: [https://zamkovoi.yoga/yoga3](https://zamkovoi.yoga/yoga3)\n - Planet der Liebe: [https://zamkovoi.yoga/yoga4](https://zamkovoi.yoga/yoga4)\n - Quelle schöpferischer Kraft: [https://zamkovoi.yoga/yoga5](https://zamkovoi.yoga/yoga5)\n - 36 Schritte des Yoga: [https://zamkovoi.yoga/yoga36](https://zamkovoi.yoga/yoga36)\n - Weg der Seele: [https://zamkovoi.yoga/yogas](https://zamkovoi.yoga/yogas)"}],"fr":[{"type":"video","vimeoId":"1133367763"},{"type":"text","markdown":"### Et ensuite ?\n\nJ''espère que ce mois de pratiques vous a apporté des résultats sensibles, et qu''après avoir réalisé cette pratique, une question peut surgir : « Et ensuite ? »... Et ici s''ouvre devant vous un grand choix de séminaires pratiques, d''intensifs et de cours que j''ai préparés pour harmoniser les domaines les plus divers de la vie et les états psychologiques intérieurs. Pour vous orienter, déterminez d''abord la direction : ce qui vous touche le plus actuellement, c''est-à-dire provoque de l''inconfort, inquiète, inspire... (là où il y a des émotions vives, il y a de l''énergie pour le développement), puis réfléchissez au temps que vous êtes prêt à consacrer aux leçons et aux pratiques. S''il est difficile de vous décider, écrivez-moi ou posez une question lors du webinaire. Ci-dessous, j''ai énuméré les séminaires pratiques et les cours qui peuvent vous intéresser :\n\n\nATELIERS :\n - Mois de la santé : [https://zamkovoi.yoga/m1](https://zamkovoi.yoga/m1)\n - Mois des plaisirs : [https://zamkovoi.yoga/m2](https://zamkovoi.yoga/m2)\n - Mois de la force : [https://zamkovoi.yoga/m3](https://zamkovoi.yoga/m3)\n - Mois de l’amour : [https://zamkovoi.yoga/m4](https://zamkovoi.yoga/m4)\n - Mois de la liberté : [https://zamkovoi.yoga/m5](https://zamkovoi.yoga/m5)\n - Mois de la sagesse : [https://zamkovoi.yoga/m6](https://zamkovoi.yoga/m6)\n - Mois de la sainteté : [https://zamkovoi.yoga/m7](https://zamkovoi.yoga/m7)\n\n\nCOURS :\n - Yoga et santé: [https://zamkovoi.yoga/yoga1](https://zamkovoi.yoga/yoga1)\n - Yoga et féminité: [https://zamkovoi.yoga/yoga2](https://zamkovoi.yoga/yoga2)\n - Tantra - mystère des relations: [https://zamkovoi.yoga/tantra12](https://zamkovoi.yoga/tantra12)\n - Réalise ton rêve: [https://zamkovoi.yoga/yoga3](https://zamkovoi.yoga/yoga3)\n - Planète de l''amour: [https://zamkovoi.yoga/yoga4](https://zamkovoi.yoga/yoga4)\n - Source de force créatrice: [https://zamkovoi.yoga/yoga5](https://zamkovoi.yoga/yoga5)\n - 36 pas de yoga: [https://zamkovoi.yoga/yoga36](https://zamkovoi.yoga/yoga36)\n - Chemin de l''âme: [https://zamkovoi.yoga/yogas](https://zamkovoi.yoga/yogas)"}],"it":[{"type":"video","vimeoId":"1133367763"},{"type":"text","markdown":"### E adesso?\n\nSpero che questo mese di pratiche vi abbia portato risultati tangibili, e dopo aver completato questa pratica possa sorgervi la domanda: «E adesso?»… E qui davanti a voi c''è una grande scelta di laboratori pratici, intensivi e corsi che ho preparato per armonizzare le più diverse sfere della vita e gli stati psicologici interiori. Per orientarvi, prima definite la direzione: ciò che adesso vi tocca di più, cioè vi crea disagio, vi preoccupa, vi ispira… (dove ci sono emozioni vive, lì c''è energia per lo sviluppo), e poi pensate a quanto tempo siete pronti a dedicare alle lezioni e alle pratiche. Se è difficile decidere, scrivetemi o fate una domanda al webinar. Qui sotto ho elencato i laboratori pratici e i corsi che potrebbero interessarvi:\n\n\nPRATICUM:\n - Mese della salute: [https://zamkovoi.yoga/m1](https://zamkovoi.yoga/m1)\n - Mese dei piaceri: [https://zamkovoi.yoga/m2](https://zamkovoi.yoga/m2)\n - Mese della forza: [https://zamkovoi.yoga/m3](https://zamkovoi.yoga/m3)\n - Mese dell''amore: [https://zamkovoi.yoga/m4](https://zamkovoi.yoga/m4)\n - Mese della libertà: [https://zamkovoi.yoga/m5](https://zamkovoi.yoga/m5)\n - Mese della saggezza: [https://zamkovoi.yoga/m6](https://zamkovoi.yoga/m6)\n - Mese della santità: [https://zamkovoi.yoga/m7](https://zamkovoi.yoga/m7)\n\n\nCORSI:\n - Yoga e salute: [https://zamkovoi.yoga/yoga1](https://zamkovoi.yoga/yoga1)\n - Yoga e femminilità: [https://zamkovoi.yoga/yoga2](https://zamkovoi.yoga/yoga2)\n - Tantra - mistero delle relazioni: [https://zamkovoi.yoga/tantra12](https://zamkovoi.yoga/tantra12)\n - Realizza il sogno: [https://zamkovoi.yoga/yoga3](https://zamkovoi.yoga/yoga3)\n - Pianeta dell''amore: [https://zamkovoi.yoga/yoga4](https://zamkovoi.yoga/yoga4)\n - Fonte di forza creativa: [https://zamkovoi.yoga/yoga5](https://zamkovoi.yoga/yoga5)\n - 36 passi di yoga: [https://zamkovoi.yoga/yoga36](https://zamkovoi.yoga/yoga36)\n - Il cammino dell''anima: [https://zamkovoi.yoga/yogas](https://zamkovoi.yoga/yogas)"}],"es":[{"type":"video","vimeoId":"1133367763"},{"type":"text","markdown":"### ¿Qué sigue?\n\nEspero que este mes de prácticas le haya traído resultados tangibles, y que después de realizar esta práctica pueda surgirle la pregunta: «¿Qué sigue?»… Y aquí tiene ante usted una gran elección de talleres prácticos, intensivos y cursos que he preparado para armonizar las más diversas esferas de la vida y estados psicológicos internos. Para orientarse, primero defina la dirección: qué es lo que ahora más lo toca, es decir, le causa malestar, le preocupa, le inspira… (donde hay emociones vivas, allí hay energía para el desarrollo), y luego piense cuánto tiempo está dispuesto a dedicar a las lecciones y prácticas. Si le resulta difícil decidirse, escríbame o haga la pregunta en el webinar. A continuación he enumerado los talleres prácticos y cursos que pueden interesarle:\n\n\nTALLERES:\n - Mes de la salud: [https://zamkovoi.yoga/m1](https://zamkovoi.yoga/m1)\n - Mes de los placeres: [https://zamkovoi.yoga/m2](https://zamkovoi.yoga/m2)\n - Mes de la fuerza: [https://zamkovoi.yoga/m3](https://zamkovoi.yoga/m3)\n - Mes del amor: [https://zamkovoi.yoga/m4](https://zamkovoi.yoga/m4)\n - Mes de la libertad: [https://zamkovoi.yoga/m5](https://zamkovoi.yoga/m5)\n - Mes de la sabiduría: [https://zamkovoi.yoga/m6](https://zamkovoi.yoga/m6)\n - Mes de la santidad: [https://zamkovoi.yoga/m7](https://zamkovoi.yoga/m7)\n\n\nCURSOS:\n - Yoga y salud: [https://zamkovoi.yoga/yoga1](https://zamkovoi.yoga/yoga1)\n - Yoga y feminidad: [https://zamkovoi.yoga/yoga2](https://zamkovoi.yoga/yoga2)\n - Tantra - misterio de las relaciones: [https://zamkovoi.yoga/tantra12](https://zamkovoi.yoga/tantra12)\n - Haz realidad tu sueño: [https://zamkovoi.yoga/yoga3](https://zamkovoi.yoga/yoga3)\n - Planeta del amor: [https://zamkovoi.yoga/yoga4](https://zamkovoi.yoga/yoga4)\n - Fuente de la fuerza creativa: [https://zamkovoi.yoga/yoga5](https://zamkovoi.yoga/yoga5)\n - 36 pasos del yoga: [https://zamkovoi.yoga/yoga36](https://zamkovoi.yoga/yoga36)\n - Camino del alma: [https://zamkovoi.yoga/yogas](https://zamkovoi.yoga/yogas)"}],"pt":[{"type":"video","vimeoId":"1133367763"},{"type":"text","markdown":"### O que vem a seguir?\n\nEspero que este mês de práticas tenha trazido a você resultados perceptíveis, e, após realizar esta prática, pode surgir em você a pergunta - «O que vem a seguir?»… E aqui você tem uma grande escolha de práticas, intensivos e cursos que preparei para harmonizar as mais diversas áreas da vida e estados psicológicos internos. Para se orientar, primeiro defina a direção - o que agora mais toca você, ou seja, causa desconforto, o preocupa, o inspira… (onde há emoções intensas, ali há energia para o desenvolvimento), e depois pense quanto tempo você está disposto a dedicar às aulas e práticas. Se for difícil decidir, escreva para mim ou faça uma pergunta no webinar. Abaixo listei as práticas e cursos que podem interessar a você:\n\n\nPRATICUNS:\n - Mês da saúde: [https://zamkovoi.yoga/m1](https://zamkovoi.yoga/m1)\n - Mês dos prazeres: [https://zamkovoi.yoga/m2](https://zamkovoi.yoga/m2)\n - Mês da força: [https://zamkovoi.yoga/m3](https://zamkovoi.yoga/m3)\n - Mês do amor: [https://zamkovoi.yoga/m4](https://zamkovoi.yoga/m4)\n - Mês da liberdade: [https://zamkovoi.yoga/m5](https://zamkovoi.yoga/m5)\n - Mês da sabedoria: [https://zamkovoi.yoga/m6](https://zamkovoi.yoga/m6)\n - Mês da santidade: [https://zamkovoi.yoga/m7](https://zamkovoi.yoga/m7)\n\n\nCURSOS:\n - Yoga e saúde: [https://zamkovoi.yoga/yoga1](https://zamkovoi.yoga/yoga1)\n - Yoga e feminilidade: [https://zamkovoi.yoga/yoga2](https://zamkovoi.yoga/yoga2)\n - Tantra - mistério das relações: [https://zamkovoi.yoga/tantra12](https://zamkovoi.yoga/tantra12)\n - Realize o sonho: [https://zamkovoi.yoga/yoga3](https://zamkovoi.yoga/yoga3)\n - Planeta do amor: [https://zamkovoi.yoga/yoga4](https://zamkovoi.yoga/yoga4)\n - Fonte da força criativa: [https://zamkovoi.yoga/yoga5](https://zamkovoi.yoga/yoga5)\n - 36 passos de yoga: [https://zamkovoi.yoga/yoga36](https://zamkovoi.yoga/yoga36)\n - Caminho da alma: [https://zamkovoi.yoga/yogas](https://zamkovoi.yoga/yogas)"}],"nl":[{"type":"video","vimeoId":"1133367763"},{"type":"text","markdown":"### Wat nu?\n\nIk hoop dat deze maand van praktijken je voelbare resultaten heeft gebracht, en dat na het uitvoeren van deze praktijk bij je de vraag kan opkomen - «Wat nu?»… En hier heb je een grote keuze aan prakticums, intensives en cursussen die ik heb voorbereid voor het harmoniseren van de meest uiteenlopende levensgebieden en innerlijke psychologische toestanden. Om je te oriënteren, bepaal eerst de richting - wat je nu het meest raakt, dat wil zeggen ongemak veroorzaakt, je bezighoudt, inspireert… (waar levendige emoties zijn - daar is energie voor ontwikkeling), en bedenk daarna hoeveel tijd je bereid bent aan lessen en praktijken te besteden. Als het moeilijk is om te kiezen, schrijf me of stel een vraag tijdens het webinar. Hieronder heb ik de prakticums en cursussen opgesomd die je mogelijk interesseren:\n\n\nPRAKTIJKEN:\n - Maand van gezondheid: [https://zamkovoi.yoga/m1](https://zamkovoi.yoga/m1)\n - Maand van genot: [https://zamkovoi.yoga/m2](https://zamkovoi.yoga/m2)\n - Maand van kracht: [https://zamkovoi.yoga/m3](https://zamkovoi.yoga/m3)\n - Maand van liefde: [https://zamkovoi.yoga/m4](https://zamkovoi.yoga/m4)\n - Maand van vrijheid: [https://zamkovoi.yoga/m5](https://zamkovoi.yoga/m5)\n - Maand van wijsheid: [https://zamkovoi.yoga/m6](https://zamkovoi.yoga/m6)\n - Maand van heiligheid: [https://zamkovoi.yoga/m7](https://zamkovoi.yoga/m7)\n\n\nCURSUSSEN:\n - Yoga en gezondheid: [https://zamkovoi.yoga/yoga1](https://zamkovoi.yoga/yoga1)\n - Yoga en vrouwelijkheid: [https://zamkovoi.yoga/yoga2](https://zamkovoi.yoga/yoga2)\n - Tantra - mysterie van relaties: [https://zamkovoi.yoga/tantra12](https://zamkovoi.yoga/tantra12)\n - Verwezenlijk je droom: [https://zamkovoi.yoga/yoga3](https://zamkovoi.yoga/yoga3)\n - Planeet van de liefde: [https://zamkovoi.yoga/yoga4](https://zamkovoi.yoga/yoga4)\n - Bron van creatieve kracht: [https://zamkovoi.yoga/yoga5](https://zamkovoi.yoga/yoga5)\n - 36 stappen van yoga: [https://zamkovoi.yoga/yoga36](https://zamkovoi.yoga/yoga36)\n - Pad van de ziel: [https://zamkovoi.yoga/yogas](https://zamkovoi.yoga/yogas)"}]}'::jsonb,null) on conflict(id) do nothing;
